INSERT INTO catalogo_obras (id, tmdb_id, tipo, titulo, titulo_original, ano, sinopse, duracao, temporadas, poster_path, backdrop_path, nota, votos, popularidade, idioma_original, eixo_1, eixo_2, eixo_3, eixo_4, eixo_5, eixo_6, eixo_7, eixo_8, confianca, ativo, atualizado_em) VALUES
(1, 279246, 'serie', 'A Imperatriz Se Casou Novamente', '재혼 황후', 2026, 'A amada imperatriz Navier governa o Império do Oriente ao lado do imperador Sovieshu. Mas, quando Sovieshu se apaixona por uma escrava fugitiva e exige o divórcio, Navier aceita sob uma única condição: receber permissão para se casar com o príncipe rival Heinrey, do Reino do Ocidente.', NULL, 1, '/lzS8kJgL5pNlX25iVVjafhvQGBy.jpg', '/fNcpHmuZLKoyhNMBEzdqzX8iIvg.jpg', 8.7, 105, 190.35, 'ko', 55, 15, 84, 27, 40, 47, 49, 74, 83, 1, '2026-11-18 19:09:23'),
(2, 303745, 'serie', 'Amor Disfarçado', '나의 유죄인간', 2026, 'Yoon Yi-jun, herdeiro do Grupo Taekang, é o principal suspeito de um assassinato chocante. Para descobrir a verdade, a detetive Kang Jae-hee se infiltra como seu secretário para vigiá-lo de perto. Quanto mais se aproximam da verdade, mais próximos também ficam. Será que Jae-hee, que esconde sua identidade, e Yi-jun, que guarda um segredo, conseguirão revelar o que realmente sentem um pelo outro?', NULL, 1, '/fhYPYQyVopTbPIf4A7FN5Q3lxPR.jpg', '/ob7m6JqZ7jSOocR3VL73VxRC6Is.jpg', 9, 85, 142.04, 'ko', 45, 45, 42, 43, 20, 47, 15, 52, 100, 1, '2026-11-18 19:09:23'),
(3, 70528, 'serie', 'Chicago Typewriter', '시카고 타자기', 2017, 'O que é preciso para manter o seu status como um de autor popular?\n\n Han Se Ju (Yoo Ah In) foi um escritor em sua vida passada durante a ocupação japonesa nos anos 1930. Ele reencarnou como um autor de bestseller nos dias atuais. Mas Se Ju está deprimido e tem um bloqueio criativo que o impede de completar o seu próximo trabalho.\n\nEnquanto isso Yoo Jin Oh (Go Kyung Pyo) é um escritor fantasma talentoso que pode tirar Se Ju dessa situação difícil, mas o homem parece guardar um grande segredo sobre o mistério das vidas passadas dele, de Se Ju e de Jeon.\n\n…', 70, 1, '/5qD8pAFPGuioviwaam20YNrjH8q.jpg', '/f44Ykw0MnAcFvBeYhmdKekcX35J.jpg', 7.9, 51, 88.67, 'ko', 55, 15, 84, 27, 40, 47, 49, 74, 83, 1, '2026-11-18 19:09:24'),
(4, 289517, 'serie', 'Um Trabalho do Inferno', '꿀알바', 2026, 'Endividado, um jovem aceita empregos lucrativos em uma agência misteriosa, mas logo descobre que sua busca por dinheiro vai se tornar um pesadelo.', NULL, 1, '/sb7uyzV8re3uSvogl6jn8KjLbAH.jpg', '/gWedDgBsZkuOho2qe3q2sTQmbpO.jpg', 7.5, 111, 71.69, 'ko', 57, 15, 50, 33, 28, 71, 33, 52, 83, 1, '2026-11-18 19:09:24'),
(5, 293610, 'serie', 'Doctor X: A Máfia do Jaleco Branco', '닥터X: 하얀 마피아의 시대', 2026, 'Uma cirurgiã enigmática e brilhante chega a um hospital dominado pelo ego e pela corrupção. Encarando uma oposição brutal, ela resolve casos aparentemente impossíveis.', NULL, 1, '/d41TWEoIeMHI4Hwa3kkwkVvnVF5.jpg', '/mDYIV71RL3mkaW8IfSGNthuVB7l.jpg', 8.6, 65, 67.33, 'ko', 61, 15, 42, 39, 0, 71, 25, 52, 100, 1, '2026-11-18 19:09:24'),
(6, 93405, 'serie', 'Round 6', '오징어 게임', 2021, 'Centenas de jogadores falidos aceitam um estranho convite para um jogo de sobrevivência. Um prêmio milionário aguarda, mas as apostas são altas e mortais.', NULL, 3, '/6gcHdboppvplmBWxvROc96NJnmm.jpg', '/2meX1nMdScFOoV4370rqHWKmXhY.jpg', 7.9, 17957, 48.7, 'ko', 57, 25, 64, 59, 28, 71, 51, 52, 100, 1, '2026-11-18 19:09:25'),
(7, 99966, 'serie', 'All of Us Are Dead', '지금 우리 학교는', 2022, 'Uma epidemia mortal surge em uma escola. Encurralados, os alunos só tem uma opção: lutar com todas as forças para não virarem zumbis.', 65, 2, '/d9yefq8dNke4UbuqStBtUcO9TxD.jpg', '/jZAtLKNZbQZZLm9OLcY9rdZZV5F.jpg', 8.3, 4528, 37.3, 'ko', 55, 25, 98, 53, 40, 47, 67, 74, 100, 1, '2026-11-18 19:09:25'),
(8, 293607, 'serie', '100 Dias de Mentiras', '100일의 거짓말', 2026, 'Em busca de liberdade, a maior batedora de carteiras de Gyeongseong se infiltra no governo colonial japonês para roubar segredos. Mas se apaixona pelo filho do seu alvo.', NULL, 1, '/yUdCm0T0Ot6gbf6ti2hnD6oCAPC.jpg', '/3SvKCITqMtjgPIhFBjRc4yTAc4H.jpg', 8.6, 20, 35.64, 'ko', 47, 25, 64, 53, 40, 47, 51, 52, 83, 1, '2026-11-18 19:09:26'),
(9, 276161, 'serie', 'Aprendendo a Lição', '참교육', 2026, 'O respeito foi pelo ralo dentro das escolas. É aí que entra uma unidade especial para ensinar lições pragmáticas e mordazes que não estão nos livros didáticos.', 70, 1, '/oXjXhXUzwlRevYcFapt1Q2R9WRF.jpg', '/sGitHICLzIQQBiwE67lZLy6W67u.jpg', 9.3, 1027, 35.56, 'ko', 41, 55, 64, 63, 48, 47, 41, 52, 100, 1, '2026-11-18 19:09:26'),
(10, 289423, 'serie', 'Um Choque de Amor', '나를 충전해줘', 2026, 'Um herdeiro com um coração artificial e uma mulher elétrica fecham um acordo que faz os batimentos cardíacos dele dispararem (em todos os sentidos).', NULL, 1, '/ncqFauZ8eT5jq6E7jNxsopMwd8m.jpg', '/cnb3SelfQKewpo0bw4HCNRHjwY4.jpg', 8.5, 69, 31.1, 'ko', 49, 45, 84, 37, 48, 47, 39, 74, 100, 1, '2026-11-18 19:09:27'),
(11, 278573, 'serie', 'A Coroa Perfeita', '21세기 대군부인', 2026, 'Na Coreia do Sul do século 21, governada por uma monarquia constitucional, uma herdeira chaebol com tudo, menos status, tenta controlar seu futuro após cruzar com o príncipe que não tem nada, apenas status. Unidos por um contrato de casamento, eles vivem um romance que desafia barreiras sociais.', NULL, 1, '/vS70MWKvCb6bT9kYj8OTmumcsWq.jpg', '/6ekykPwvAywJRjFEnUoCFWTO9O3.jpg', 8.9, 243, 30.08, 'ko', 41, 45, 50, 37, 48, 47, 23, 52, 83, 1, '2026-11-18 19:09:27'),
(12, 127529, 'serie', 'Cães de Caça', '사냥개들', 2023, 'Dois jovens boxeadores unem forças para enfrentar inimigos impiedosos com sede de sangue, arriscando as próprias vidas para fazer justiça e proteger as pessoas que amam.', 61, 2, '/uFNHrunRIlyzRlRS7c9InUVgFDa.jpg', '/zhsEnDNCQX5dlI2wbKzV90pV0B9.jpg', 8.5, 836, 28.47, 'ko', 51, 25, 56, 59, 12, 47, 43, 52, 100, 1, '2026-11-18 19:09:28'),
(13, 200709, 'serie', 'Classe dos Heróis Fracos', '약한영웅', 2022, 'Com a ajuda de amigos inesperados, um aluno talentoso e introvertido decide enfrentar os valentões do colégio, sem fazer ideia do perigo que está correndo.', 84, 2, '/kZeJeV8L3WlVp3L6DZS0WaDelfj.jpg', '/cLTAda6fMRirkCY1xfO4pmcHVkk.jpg', 8.7, 567, 28.19, 'ko', 47, 25, 64, 53, 40, 47, 51, 52, 83, 1, '2026-11-18 19:09:28'),
(14, 68398, 'serie', 'Dr. Romântico', '낭만닥터 김사부', 2016, 'Kim Sa Bu já teve a fama de ser um ótimo cirurgião em um hospital enorme. Um dia, ele saiu da indústria e agora ele é o cirurgião chefe no Hospital Soldam no interior. Depois de ele conduzir uma cirurgia de sucesso no Presidente Shin, ele consegue melhorar o hospital com apoio de confiança. Mas, então, o Presidente Shin morre. Novas pessoas aparecem e seus alunos precisam deixar o hospital. Além disso, seu pulso, que foi machucado há três anos, começa a agir de uma maneira estranha. No fim, ele vai a um hospital enorme para resolver a falta de mão de…', 60, 3, '/eBbxLx6Gzz7sG1oE8FXNQPjYOV7.jpg', '/cmk8d1e1GxrwTaau0Tj4zm1osm0.jpg', 8.1, 138, 28.14, 'ko', 47, 15, 50, 27, 40, 47, 33, 52, 67, 1, '2026-11-18 19:09:32'),
(15, 219246, 'serie', 'Se a Vida Te Der Tangerinas...', '폭싹 속았수다', 2025, 'Em Jeju, a união entre uma jovem ousada e um rapaz esforçado se transforma em uma história de obstáculos e triunfos, provando que o amor pode perdurar por gerações.', NULL, 1, '/k42rlc5drUiSl9s8lqeM9dLjHQw.jpg', '/a9qlroMOHewiDsUR93PYMVfpbF5.jpg', 8.8, 630, 26.34, 'ko', 47, 15, 50, 27, 40, 47, 33, 52, 67, 1, '2026-11-18 19:09:32'),
(16, 112888, 'serie', 'Beleza Verdadeira', '여신강림', 2020, 'Uma adolescente insegura aprende os truques da maquiagem e começa a fazer um enorme sucesso na escola. Mas não vai ser fácil manter as aparências.', NULL, 1, '/g7ocbs1UieVybM3kypqXBfPczaL.jpg', '/3E1GroTJCRdIYHa5n62GqjmqxQR.jpg', 8.3, 2747, 26.19, 'ko', 41, 45, 50, 37, 48, 47, 23, 52, 83, 1, '2026-11-18 19:09:33'),
(17, 119769, 'serie', 'O Taxista', '모범택시', 2021, 'Do Ki viveu mais honestamente do que qualquer outro oficial das Forças Especiais. Mas, quando um assassino em série mata sua mãe, ele passa a viver seus dias em agonia. Injustiçado e abalado, Do Ki conhece Jang Sung Chul, que o recruta para trabalhar em sua empresa, Táxi Arco-íris. Longe de ser um serviço de táxi comum, a Táxi Arco-íris é uma organização secreta que vinga as vítimas que a lei não protegeu. Do Ki se torna um taxista estrela, que cumpre a vingança dos clientes de forma satisfatória. Ha Na é uma promotora pública que está investigando a…', 64, 3, '/qDLhCBbl7eUSesMSV9rYqHR8qwW.jpg', '/i1SyUHsi45psSH1xy9sM0in8FKJ.jpg', 8.1, 223, 22.53, 'ko', 51, 25, 56, 59, 12, 47, 43, 52, 100, 1, '2026-11-18 19:09:33'),
(18, 135157, 'serie', 'Alquimia das Almas', '환혼', 2022, 'Uma feiticeira poderosa no corpo de uma mulher cega é convocada a mudar o destino de um homem de uma renomada família.', 75, 2, '/1PmLJGwX61w32dlu4bwmxtizWwt.jpg', '/nBZyWSGAUEzCH7Mna0zUNTpBQlQ.jpg', 8.6, 831, 22.3, 'ko', 65, 25, 98, 59, 28, 71, 67, 74, 100, 1, '2026-11-18 19:09:34'),
(19, 291496, 'serie', 'Um Grude de Amor', '이런 엿같은 사랑', 2026, 'Após perder a memória, uma promotora vai morar com o suposto namorado, um treinador de boxe. Resta saber se esse grude vai se transformar em amor verdadeiro.', NULL, 1, '/qITVjM7ETkIH0l8WoIApSrzDjgu.jpg', '/mp2AFsWsuyxCzenJh3DTKw7z4jG.jpg', 8.7, 141, 21.89, 'ko', 41, 45, 50, 37, 48, 47, 23, 52, 83, 1, '2026-11-18 19:09:34'),
(20, 113268, 'serie', 'Caçadores de Demônios', '경이로운 소문', 2020, 'De dia, trabalham num restaurante. À noite, são caçadores de demônios. Eles usam seus poderes especiais para perseguir espíritos malignos que atacam os humanos.', 64, 2, '/blL4dpmy2Vc65VtnJwlEX7w0uEf.jpg', '/jNyK0FF7t7oaU4wMpRkEnEIOVlW.jpg', 8.3, 477, 20.31, 'ko', 57, 25, 64, 59, 28, 71, 51, 52, 100, 1, '2026-11-18 19:09:35'),
(21, 296206, 'serie', 'Agente Kim: Reativado', '김부장', 2026, 'Um pai que leva uma vida comum desenterra as habilidades do passado como agente especial para procurar a filha desaparecida. Mas acaba atraindo uma atenção indesejada.', NULL, 1, '/2fWPaP8xplaAv2YxUoXccfsP72S.jpg', '/g1LJLlmWP74zv9yXKEXm7g9p10O.jpg', 8.4, 230, 19.29, 'ko', 51, 25, 56, 59, 12, 47, 43, 52, 100, 1, '2026-11-18 19:09:35'),
(22, 226102, 'serie', 'Acidente', '크래시', 2024, 'Um drama sobre Cha Yeon-ho, um individualista razoável do KAIST, e Min So-hee, um ás da investigação de trânsito com julgamento frio e sensibilidade calorosa na Investigação de Crimes de Trânsito (TCI).', NULL, 2, '/mlm7ZnMZxyexylGeAD48QgjEeAg.jpg', '/4wZZ8CGEsjXaKt5TosiFqbaPymD.jpg', 8.6, 20, 19.13, 'ko', 49, 75, 56, 87, 26, 47, 43, 52, 100, 1, '2026-11-18 19:09:36'),
(23, 96648, 'serie', 'Sweet Home', '스위트홈', 2020, 'Quando humanos viram monstros selvagens e espalham o terror, um jovem atormentado e seus vizinhos de apartamento lutam para sobreviver sem perder a humanidade.', NULL, 3, '/tB3N2GfA5krC53vQCChLZaCRT6n.jpg', '/mceCXNTny6a5F3rQgShLoyARw4l.jpg', 8.2, 1639, 18.99, 'ko', 59, 45, 98, 71, 46, 47, 77, 74, 83, 1, '2026-11-18 19:09:36'),
(24, 61148, 'serie', 'Imperatriz Ki', '기황후', 2013, 'Genghis Khan construiu um império que abrangeu vastas regiões no leste da Ásia e no leste da Europa. E havia uma mulher que detinha imenso poder na dinastia Yuan, fundada por Genghis Khan, por 37 anos. Ela não era descendente de mongóis nem dos chineses han. Ela veio de Goryeo, um pequeno reino no Extremo Oriente. Ela foi levada para mongol contra sua vontade como Gungnyeo (mulheres do palácio), mas de alguma forma superou seu status humilde para se tornar uma imperatriz em outra terra. O nome dela era Imperatriz Ki.', 60, 1, '/1J21GWGF3sqxuduC21v7WpWUqnY.jpg', '/pefCiIoIrWglxwpoqIdnhL0IlGZ.jpg', 7.3, 66, 18.25, 'ko', 47, 15, 50, 30, 30, 47, 51, 37, 83, 1, '2026-11-18 19:09:37'),
(25, 96102, 'serie', 'Hospital Playlist', '슬기로운 의사생활', 2020, 'Todos os dias são extraordinários para cinco médicos e seus pacientes dentro de um hospital, onde coexistem nascimento, morte e tudo mais.', 80, 2, '/zy0FJYPsKkfOrZG5r5lFtTIx1up.jpg', '/ji7KaBHhxb6ngHEHxXHcfEzi9bu.jpg', 8.6, 179, 17.75, 'ko', 41, 45, 50, 37, 48, 47, 23, 52, 83, 1, '2026-11-18 19:09:37'),
(26, 201859, 'serie', 'Aula de amor', '수업중입니다', 2022, 'A trama retrata um drama juvenil sobre o primeiro amor, repleto de emoção, através da perspectiva do protagonista, que aprende o significado de família e comunidade.', 20, 3, '/j4PAXhpcVsqHXf2SqHlJGAN3IYF.jpg', '/4NffLgfKgSyosvA2qGZxJh7aa1v.jpg', 7, 29, 17.73, 'ko', 47, 15, 50, 27, 40, 47, 33, 52, 67, 1, '2026-11-18 19:09:38'),
(27, 215072, 'serie', 'Uma Loja Para Assassinos', '킬러들의 쇼핑몰', 2024, 'O único familiar vivo de Jian, seu tio, morre repentinamente. Só então ela descobre que ele tinha uma loja suspeita. Quem era o tio dela, e que tipo de loja ele gerenciava? Antes que Jian possa entender o que está acontecendo, ela é atacada por homens desconhecidos que estão atrás dos produtos do tio. Agora que está sozinha, Jian vai conseguir sobreviver?', NULL, 2, '/hx84Fg4I35nkxtH69e9aOmUVtdR.jpg', '/lg134VJrvY3ZdOlP4lTu1onOhcf.jpg', 8.5, 260, 17.32, 'ko', 57, 25, 64, 59, 28, 71, 51, 52, 100, 1, '2026-11-18 19:09:38'),
(28, 307106, 'serie', 'Entre os Nossos Passos', '연애박사', 2026, 'Um ex-nadador que reconstrói sua vida através da robótica após perder a perna e uma mulher que encontra um novo caminho acadêmico depois de se afastar de seus sonhos originais se envolvem em um romance tranquilo e reconfortante enquanto estudam engenharia mecânica.', 70, 1, '/vyrpZOFIZJkQG8ZWTezmlNGav8R.jpg', '/wwSoLQrLyiXXUbRnZq1eWBbHaRR.jpg', 8.7, 20, 17.05, 'ko', 41, 45, 50, 37, 48, 47, 23, 52, 83, 1, '2026-11-18 19:09:38'),
(29, 94796, 'serie', 'Pousando no Amor', '사랑의 불시착', 2019, 'Um acidente de parapente leva uma herdeira sul-coreana à Coreia do Norte. Ali, ela acaba conhecendo um oficial do exército, que vai ajudá-la a se esconder.', NULL, 1, '/sLBtmtaqrngZegQwbnL2fSzzTBJ.jpg', '/3yEHM2HT2vrUtO93YzTJNgEfiZG.jpg', 8.5, 995, 16.4, 'ko', 41, 45, 50, 37, 48, 47, 23, 52, 83, 1, '2026-11-18 19:09:39'),
(30, 126485, 'serie', 'Em Movimento', '무빙', 2023, 'Nesta série de ação sobrenatural, jovens que escondem superpoderes e seus pais, que vivem com segredos dolorosos do passado, enfrentam grandes perigos juntos.', NULL, 2, '/pHvCiSsiIKjFTs115HWjz5O54qQ.jpg', '/29jWaRhKtey1efp5G7Fu97NAmzz.jpg', 8.5, 318, 16.35, 'ko', 57, 25, 64, 59, 28, 71, 51, 52, 100, 1, '2026-11-18 19:09:39'),
(31, 1263337, 'filme', 'Coração Selvagem', 'Heart of the Beast', 2026, 'Um ex-soldado ferido e seu cão de guerra aposentado lutam para sobreviver na região do Alasca e encontrar o caminho de volta para casa após um acidente aéreo na mata.', 104, NULL, '/n4PJa4xVo4SjIsBvTA0yGMKjTBh.jpg', '/yE766yhgg98tKwTKd8CyNvAtmn6.jpg', 7.7, 990, 507.5, 'en', 51, 52, 68, 99, 34, 62, 86, 60, 67, 1, '2026-11-18 19:12:29'),
(32, 1368337, 'filme', 'A Odisseia', 'The Odyssey', 2026, 'Acompanhe o rei grego Odisseu em sua perigosa jornada de 20 anos para voltar a Ítaca após a Guerra de Troia, enfrentando monstros e deuses enquanto sua esposa Penélope resiste em seu reino.', 172, NULL, '/m0ehGErq8GTLK4WZxaq9QLGAR3u.jpg', '/c7btGYblBnfAaw713WvFM0Kimc7.jpg', 8, 5087, 478.61, 'en', 55, 72, 100, 100, 56, 50, 100, 70, 83, 1, '2026-11-18 19:12:30'),
(33, 1400837, 'filme', 'Outra Mamãe', 'Other Mommy', 2026, 'Uma menina de 8 anos, filha de um casal que enfrenta problemas conjugais, encara uma entidade sinistra que sai do seu armário e torna-se cada vez mais ameaçadora para a família.', 94, NULL, '/hiuBB4ZqGbL7uihdVPUahFtg7Zr.jpg', '/smZ8BT4Vzw4iCEppTLCnN8jNYtn.jpg', 6.4, 497, 411.84, 'en', 61, 22, 60, 67, 36, 50, 40, 52, 50, 1, '2026-11-18 19:12:30'),
(34, 1423191, 'filme', 'Resident Evil', 'Resident Evil', 2026, 'Bryan, um tranquilo entregador de órgãos, é enviado para uma entrega noturna no Hospital Geral de Raccoon City. No caminho por uma estrada montanhosa coberta de neve, ele acidentalmente atropela uma mulher desconhecida. Ela sobrevive, mas algo está muito errado. Ao tentar ajudar, Bryan se depara com um surto em larga escala envolvendo mutações horríveis com tentáculos e monstruosidades bioengenheiradas.', 94, NULL, '/bvBTdNaWVPrHKjyPFnsigZJsKdD.jpg', '/3icyRAqgakNcQn6aDVz9libFmBA.jpg', 7.5, 2335, 400.97, 'en', 75, 34, 100, 85, 36, 58, 80, 94, 83, 1, '2026-11-18 19:12:31'),
(35, 969681, 'filme', 'Homem-Aranha: Um Novo Dia', 'Spider-Man: Brand New Day', 2026, 'É um novo dia para Peter Parker. Combatendo o crime em tempo integral como Homem-Aranha em um mundo que não se lembra mais dele e lidando com a pressão de ver seus antigos amigos seguirem em frente sem sua presença, Peter passa por uma mudança que talvez nem ele tenha o poder de controlar. Mas essa transformação também pode ser a única coisa capaz de deter uma surpreendente nova ameaça à cidade e às pessoas que ele ama: um poderoso vilão que ninguém sequer consegue enxergar.', 143, NULL, '/x0nvYzQpyJc5pdT9lMnkMuYAg0O.jpg', '/subj7knTn4DeS6KS7qI66EQKe9i.jpg', 8.5, 6947, 328.26, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:12:32'),
(36, 687163, 'filme', 'Devoradores de Estrelas', 'Project Hail Mary', 2026, 'O professor de ciências Ryland Grace acorda em uma espaçonave a anos-luz de casa, sem nenhuma lembrança de quem é ou como chegou ali. À medida que sua memória retorna, ele começa a descobrir sua missão: resolver o enigma de uma substância misteriosa que está fazendo o Sol morrer. Ele precisará recorrer ao seu conhecimento científico e a ideias nada convencionais para salvar tudo na Terra da extinção… mas uma amizade inesperada pode significar que ele não terá que fazer isso sozinho.', 157, NULL, '/2i8uru7rlbHKaoIbC2V4FZLT7uW.jpg', '/8Tfys3mDZVp4tNoH2ktm06a0Tau.jpg', 8.6, 8934, 240.61, 'en', 65, 62, 100, 75, 50, 58, 96, 94, 67, 1, '2026-11-18 19:12:32'),
(37, 1813355, 'filme', 'Uma História de Derry', 'A Story of Derry', 2026, 'Séculos antes da aparição do palhaço Pennywise em Derry, três jovens nativos americanos encontram um aterrorizante espírito ancestral na floresta.', 29, NULL, '/9duTLm4Xk62wGIWJBfdco9lPHvW.jpg', '/z26LxXDMmAIzKr06FPDudCJyvsM.jpg', 6.6, 133, 223.32, 'en', 67, 2, 60, 55, 18, 74, 30, 52, 83, 1, '2026-11-18 19:12:33'),
(38, 1244523, 'filme', 'Boiúna - Terror no Amazonas', 'Beware Boiúna', 2026, 'Um grupo de jovens médicos embarca em missão humanitária na Amazônia, cada um com seus próprios interesses ocultos. No entanto, nem todos recebem bem a chegada do grupo, e a visita deles desperta um predador ancestral: a Boiúna. A criatura mítica retorna para defender seu território. Em meio à selva densa, trava-se uma luta pela sobrevivência, e as fronteiras entre caçador e presa, herói e vilão, tornam-se cada vez mais tênues.', 103, NULL, '/mCyttsR7mW91v2Mpy5AXMCtWKAK.jpg', '/9nU0FKNefmhbgi2xXlvZchZsqwm.jpg', 6, 66, 179.5, 'en', 61, 20, 68, 100, 26, 62, 66, 52, 83, 1, '2026-11-18 19:12:34'),
(39, 1294189, 'filme', 'Fuga Mortal', 'The Mongoose', 2026, 'Um herói de guerra falsamente acusado, sem nada a perder, lidera a polícia em uma épica perseguição televisiva de carro pelo país, ajudado por membros de seu antigo batalhão das Forças Especiais do Exército e monitorado de perto por um público fascinado que torce por sua fuga segura.', 100, NULL, '/3QX08keJGtcIJsCyy4Mdaq28ZGq.jpg', '/bySCyjQXNPgsnLTlgJpSMnRazPD.jpg', 6.4, 201, 141.82, 'en', 51, 48, 58, 100, 40, 62, 82, 52, 67, 1, '2026-11-18 19:12:34'),
(40, 1567605, 'filme', 'Ebenezer e os Fantasmas do Natal', 'Ebenezer', 2026, 'Ebenezer Scrooge é um velho avarento que recebe a visita do fantasma de seu antigo sócio, Jacob Marley, e dos Espíritos do Natal Passado, Presente e Futuro. Os encontros o força a confrontar o próprio passado e a lutar por uma segunda chance de ser feliz.', 115, NULL, '/7MBeM27NNcCYUszjTNYJUycPDhV.jpg', '/fdOVxyNNL95SuI8BGaN6vudEuYX.jpg', 7.6, 107, 137.36, 'en', 53, 86, 86, 67, 58, 50, 68, 62, 67, 1, '2026-11-18 19:12:35'),
(41, 1562642, 'filme', 'Ghost Soldier', 'Ghost Soldier', 2026, 'Um engenheiro de sistemas de armas e ex-boina verde protege seus vizinhos em Wyoming contra uma corporação implacável que ameaça sua comunidade rural.', 90, NULL, '/h1MUn834b2u1FDQWObUBwp5jlHJ.jpg', '/ggqvhSdAASrseKuMlzk51sbvbE8.jpg', 9.1, 26, 133.48, 'en', 51, 48, 58, 100, 40, 62, 82, 52, 67, 1, '2026-11-18 19:12:35'),
(42, 1300968, 'filme', 'Jogos Vorazes: Amanhecer na Colheita', 'The Hunger Games: Sunrise on the Reaping', 2026, 'Revisite o mundo de Panem 24 anos antes dos eventos de Jogos Vorazes, começando na manhã da colheita dos 50º Jogos Vorazes, também conhecida como o Segundo Massacre Quaternário.', 158, NULL, '/ibZ6GSHtCeC7fLDJ2uyXNemgYwr.jpg', '/aqFZcr2dxSZ2UwWSo1WC6C0rwDf.jpg', 7.8, 21, 122.65, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:12:36'),
(43, 1543469, 'filme', 'No Coração de Nashville', 'Heartland', 2026, 'Misty Jones (Jessica Chastain), uma ex-estrela da música country, sai do isolamento para investigar o desaparecimento de sua sobrinha — também uma cantora country em ascensão — e precisa enfrentar seu próprio passado e o submundo sórdido de Nashville. Sua busca revela um lado obscuro da cidade, onde ninguém, nem mesmo Misty, é quem aparenta ser.', 113, NULL, '/rhtPUCWTsZX9aWYeOpQDgtgCqCQ.jpg', '/gVhJbOCns6GNsQaUbLszQUkFIKf.jpg', 6.3, 84, 120.34, 'en', 61, 40, 50, 87, 22, 86, 64, 52, 67, 1, '2026-11-18 19:12:37'),
(44, 1101412, 'filme', 'A Queda 2: No Limite', 'Fall 2: Deadpoint', 2026, 'De luto pela morte de sua irmã Shiloh, Jax Hunter cria um laço com Luce, a amiga corajosa de Shiloh. Juntas, elas enfrentam a perigosa passarela suspensa do Monte Kwan, na Tailândia. Quando um deslizamento de rochas as deixa presas em uma estreita prancha a mais de 3.000 metros de altitude, Jax precisa enfrentar seus medos para sobreviver.', 100, NULL, '/xtxEvJACNnbz3WYmJ5mYT1a0KGk.jpg', '/nGau0KBOaRILSK5MqFcuTfv7GMl.jpg', 7.2, 845, 118.45, 'en', 47, 36, 50, 75, 34, 62, 58, 52, 50, 1, '2026-11-18 19:12:37'),
(45, 1283515, 'filme', 'Verity', 'Verity', 2026, 'A escritora Lowen Ashleigh está à beira da falência quando aceita a oportunidade de sua vida: completar os livros restantes de uma série de sucesso que Verity Crawford, autora de thrillers best-sellers, não consegue terminar após um acidente misterioso. Ao chegar à luxuosa propriedade dos Crawford, Ashleigh percebe gradualmente que as coisas não são exatamente o que parecem.', 117, NULL, '/fy7q7xcyUjHXiKRuYblhcUTgBn0.jpg', '/cKetrF2dAnQ0AMV5i4BMOs41I5P.jpg', 7, 737, 107.79, 'en', 61, 40, 50, 87, 22, 86, 64, 52, 67, 1, '2026-11-18 19:12:38'),
(46, 1228834, 'filme', 'The Fix', 'The Fix', 2026, 'Desiludidos com o fim da guerra no Afeganistão, um grupo de ex-agentes da CIA, em desgraça e marcados pela guerra, parte para Teerã com o objetivo de realizar um golpe que mudará suas vidas.', 142, NULL, '/a1j5writymMPFPyOhBT7s1xX6v6.jpg', '/dJTWIecL2vxsCRl5G0lRhPsfrhc.jpg', 5.8, 97, 106.4, 'en', 51, 48, 58, 100, 40, 62, 82, 52, 67, 1, '2026-11-18 19:12:38'),
(47, 1185344, 'filme', 'The Beast', 'The Beast', 2026, 'Quando uma milícia de hostis não identificados coordena um golpe contra os Estados Unidos, o presidente precisa revidar utilizando as capacidades ofensivas altamente secretas de sua limusine blindada, apelidada de A Besta.', 99, NULL, '/ocg5JfJP19fodcv5uQUApkmZMdI.jpg', '/r5RYEmZzm1Z6imS7XfiKPnMlyc7.jpg', 5.3, 44, 102.42, 'en', 47, 44, 58, 100, 40, 62, 76, 52, 67, 1, '2026-11-18 19:12:39'),
(48, 1514026, 'filme', 'Buddy', 'Buddy', 2026, 'Lembra de BUDDY, o unicórnio laranja vibrante e estrela daquele clássico programa de televisão infantil que levava alegria e lições de vida para a sala de estar? Dentro do mundo colorido de It\'s Buddy!, um grupo de crianças passa os dias cantando, dançando e ajudando Buddy a espalhar felicidade. Mas, quando uma das crianças se recusa a participar da brincadeira, Buddy não fica nada satisfeito, e rachaduras começam a surgir nesse mundo aparentemente perfeito.', 95, NULL, '/29QY0eScq4chCvZNBx3BIxNdbml.jpg', '/sMmG82PtjK8A9rVc34gwKQtCm3A.jpg', 6.8, 289, 98.04, 'en', 63, 58, 96, 77, 44, 50, 52, 62, 83, 1, '2026-11-18 19:12:40'),
(49, 299534, 'filme', 'Vingadores: Ultimato', 'Avengers: Endgame', 2019, 'Após os eventos devastadores de \"Vingadores: Guerra Infinita\", o universo está em ruínas devido aos esforços do Titã Louco, Thanos. Com a ajuda de aliados remanescentes, os Vingadores devem se reunir mais uma vez a fim de desfazer as ações de Thanos e restaurar a ordem no universo de uma vez por todas, não importando as consequências.', 181, NULL, '/9fRX8UKlIW7Lb9GqNsJVakWWFCi.jpg', '/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 8.2, 29412, 88.9, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:12:40'),
(50, 1432306, 'filme', 'Sleepwalker', 'Sleepwalker', 2026, 'Após perder a filha em um acidente de carro que deixou seu marido abusivo em coma, uma mãe em luto enfrenta visões perturbadoras que confundem os limites entre realidade e pesadelo.', 89, NULL, '/760SP4VsZagpyB9WLfeZykE3DFg.jpg', '/2dYKSPT1SJZVlKwXHic4Ma53f0X.jpg', 4.8, 21, 87.86, 'en', 61, 12, 60, 91, 20, 62, 48, 52, 67, 1, '2026-11-18 19:12:41'),
(51, 354912, 'filme', 'Viva: A Vida é Uma Festa', 'Coco', 2017, 'Apesar da desconcertante proibição da música imposta pela sua família há várias gerações, Miguel sonha em tornar-se um músico de sucesso como o seu ídolo, Ernesto de la Cruz. Desesperado para provar o seu talento, Miguel encontra-se na deslumbrante e colorida Terra dos Mortos, seguindo uma misteriosa cadeia de acontecimentos. Pelo caminho, conhece o encantador Hector e, juntos, partem numa extraordinária viagem para desvendar a verdadeira história por detrás da história da família de Miguel.', 109, NULL, '/6oNm06TPz2vGiPc2I52oXW3JwPS.jpg', '/g7CHF8gTLGooTbP4GznIGwaqAGL.jpg', 8.2, 21892, 86.37, 'en', 73, 100, 100, 87, 72, 50, 100, 60, 100, 1, '2026-11-18 19:12:42'),
(52, 1153576, 'filme', 'Street Fighter', 'Street Fighter', 2026, 'Em 1993, os lutadores Ryu e Ken Masters são colocados de volta no combate quando a misteriosa Chun-Li os recruta para o próximo Torneio Street Fighter: uma brutal briga de socos, destino e fúria. Entretanto, por trás desse campeonato, se esconde uma conspiração mortal que os força a encarar um ao outro e os demônios do passado. E se eles não fizerem, é game over!', 119, NULL, '/6gWmrC2GyDbUM1ET5EBg9lxBi7S.jpg', '/9vNW8ysMKIbefbEQOFEZIKpMqwZ.jpg', 6.3, 247, 83.92, 'en', 67, 64, 100, 74, 56, 50, 83, 59, 67, 1, '2026-11-18 19:12:42'),
(53, 791523, 'filme', 'O Bosque Selvagem', 'Wildwood', 2026, 'A determinada adolescente Prue McKeel embarca em uma missão desesperada de resgate depois que seu irmão caçula é sequestrado por um bando de corvos. Acompanhada por seu colega de classe desajeitado, mas leal, Curtis Mehlberg, Prue navega por um mundo habitado por animais falantes, bandidos e figuras poderosas movidas pela dor e pela ambição. À medida que a dupla é arrastada para um conflito que ameaça o equilíbrio da própria floresta, Prue precisa descobrir uma força e uma crença que jamais soube que possuía.', 130, NULL, '/mcuUYNWGJHPEaRumOlgSZCzMRPc.jpg', '/sl5NJ1vtyhP9Vr88bB4blULsJYp.jpg', 8.5, 293, 79.93, 'en', 73, 78, 100, 75, 50, 50, 100, 70, 83, 1, '2026-11-18 19:12:43'),
(54, 755898, 'filme', 'A Guerra dos Mundos', 'War of the Worlds', 2025, 'Will Radford é um renomado analista de cibersegurança do Departamento de Segurança Interna dos Estados Unidos, encarregado de rastrear possíveis ameaças à segurança nacional por meio de um programa de vigilância em massa. No entanto, um ataque inesperado por uma entidade desconhecida o leva a suspeitar que o governo esteja escondendo algo dele… e do restante do mundo.', 90, NULL, '/yY5CbfXBxsPvYi0TzmaCP7uunnn.jpg', '/iZLqwEwUViJdSkGVjePGhxYzbDb.jpg', 4, 1212, 79.2, 'en', 65, 40, 84, 81, 34, 70, 82, 86, 67, 1, '2026-11-18 19:12:43'),
(55, 1437511, 'filme', 'Como Roubar um Banco', 'How to Rob a Bank', 2026, 'Um grupo de assaltantes de banco habilidosos transmite seus ousados roubos ao vivo, sem perceber que sua crescente fama viral os colocou na mira de um veterano agente do FBI e de uma brilhante engenheira de software. Mesmo com a dupla se aproximando cada vez mais, a quadrilha ultrapassa todos os limites, arriscando tudo por aquilo em que acredita — e por seu assalto mais ambicioso até então.', 122, NULL, '/6QOVs2PMyxHtE4tHiMZS1eIboxl.jpg', '/u38hNQbxvIicUdfrHpqa9puBnA9.jpg', 6.2, 42, 75.1, 'en', 55, 48, 50, 100, 12, 62, 74, 52, 83, 1, '2026-11-18 19:12:44'),
(56, 1400940, 'filme', 'Cara-de-Barro', 'Clayface', 2026, 'A ascensão meteórica de Matt Hagen de garoto das ruas de Gotham a astro de Hollywood é tragicamente interrompida quando as ações de um chefão do crime local o deixam terrivelmente desfigurado. Abandonado por sua equipe e sem nada, Matt busca um tratamento de ponta que, milagrosamente, o devolve à sua antiga forma... mas que também afeta, de maneira inesperada, sua percepção da realidade, lançando-o em uma espiral destrutiva de obsessão e vingança.', 109, NULL, '/dqvHs2YXks989ScXvsngbqAeBHX.jpg', '/f1TVhqJJdxMvUsUDuKHS0ekgYkk.jpg', 7.4, 455, 74.46, 'en', 75, 12, 94, 91, 20, 70, 66, 86, 83, 1, '2026-11-18 19:12:45'),
(57, 1339713, 'filme', 'Obsessão', 'Obsession', 2026, 'Sem grandes pretensões, um romântico incurável compra um brinquedo que promete realizar desejos únicos. Ele quebra o artefato misterioso enquanto pede para conquistar a crush e consegue exatamente o que desejava, mas descobre que a consequência é sinistra.', 109, NULL, '/wUc6IDf5ChjM1UyQye21qFBeJY0.jpg', '/5lTZyuBTNOfawsfPT8Q0cIg6qAF.jpg', 8.2, 6664, 74.44, 'en', 61, 12, 60, 91, 20, 62, 48, 52, 67, 1, '2026-11-18 19:12:45'),
(58, 26817, 'filme', 'Médica, Bonita e Solteira', 'Sex and the Single Girl', 1964, 'Bob Weston é o top repórter de uma revista tabloide, desprezível mas altamente rentável, que deve seu sucesso a histórias destacando sexo. Helen Gurley Brown é uma jovem psicóloga brilhante e bonita de 23 anos, que é a autora do best-seller \"Sex and the Single Girl\". Weston percebe que Brown não irá lhe dar uma entrevista, porque ela já foi objeto de um dos seus desprezíveis artigos sensacionalistas. Então ele se disfarça como seu amigo e vizinho Frank Broderick, um fabricante de meias que é totalmente dominado por uma esposa ciumenta. Depois de várias…', 110, NULL, '/pI12O5kfQonHy6svQIhc59oOVJt.jpg', '/rPHvIqO4KuVPxlfwbsnROFbCzQB.jpg', 6.5, 85, 74.43, 'en', 42, 100, 50, 50, 64, 50, 32, 41, 67, 1, '2026-11-18 19:12:46'),
(59, 1288445, 'filme', 'Código: Vingança', 'Mutiny', 2026, 'Após testemunhar o assassinato de seu chefe bilionário e ser injustamente incriminado pelo crime, Cole Reed embarca em um navio cargueiro em uma cruzada solitária para vingar a morte do chefe. No entanto, à medida que avança em sua missão, ele descobre que está no centro de uma perigosa conspiração internacional.', 95, NULL, '/gVZgjKIsXZOT3cNZm5PJZBtQRaG.jpg', '/qDa0fqDqIBCovRp975RvtGPcuN3.jpg', 7.6, 1092, 73.54, 'en', 47, 44, 58, 100, 40, 62, 76, 52, 67, 1, '2026-11-18 19:12:46'),
(60, 1291595, 'filme', 'Sobrenatural: Agora Entre Nós', 'Insidious: Out of the Further', 2026, 'Um trio de criminosos se infiltra em um bairro tranquilo e força uma nova família a entrar no plano astral, onde descobrem uma verdade aterradora: o Além está se infiltrando no mundo real.', 106, NULL, '/8IEzyoBOCbKIvJ9DMwHgceJkNsP.jpg', '/p40lmrdI4blcAPZQMTPaiy5v5Ym.jpg', 7.7, 1077, 72.42, 'en', 61, 12, 60, 91, 20, 62, 48, 52, 67, 1, '2026-11-18 19:12:47'),
(61, 1765072, 'filme', 'Tudo Pode Ser Visto', 'You Can See Everything', 2026, 'Trinta e quatro dias antes de ser enviada para a prisão, a notória fundadora do Vale do Silício, Elizabeth Holmes, convida uma equipe de filmagem cética para documentar cada passo seu. O que começa como um retrato íntimo de uma criminosa enigmática se transforma em uma jornada alucinante de três anos rumo ao abismo.', 175, NULL, '/mnu5cNfijdbuU4iWrV2Lg7AfM0J.jpg', '/nhIL3O4W9h5V5JbNQm7yjoDk3So.jpg', 8.8, 128, 70.5, 'en', 41, 50, 18, 35, 54, 50, 42, 52, 50, 1, '2026-11-18 19:12:47'),
(62, 1101383, 'filme', 'O Fim da Rua', 'The End of Oak Street', 2026, 'Após um misterioso evento cósmico abalar o bairro Oak Street e o transportar dos subúrbios para um lugar desconhecido, a família Platt descobre que sua sobrevivência vai depender da união entre todos para enfrentar um ambiente agora irreconhecível.', 100, NULL, '/aqEPRht1pZR653rmU7eHyk8wSNP.jpg', '/wnR8pwWtoL3TFwP41mLCt91ReCt.jpg', 7, 2483, 68.31, 'en', 75, 40, 84, 87, 22, 94, 82, 86, 83, 1, '2026-11-18 19:12:48'),
(63, 1465063, 'filme', 'A Ilha Esquecida', 'Forgotten Island', 2026, 'Jo e Raissa se veem presas no fantástico mundo da ilha esquecida de Nakali. Elas descobrem que seu único caminho para casa pode custar uma vida inteira de memórias e emoções.', 98, NULL, '/7OTbIk4TwYzpvf1GbOGXAFafxiz.jpg', '/2o9FzuBzCqrDTdlHRuEVnGD2d5h.jpg', 8, 270, 68.11, 'en', 67, 100, 100, 85, 80, 50, 100, 70, 100, 1, '2026-11-18 19:12:48'),
(64, 1084244, 'filme', 'Toy Story 5', 'Toy Story 5', 2026, 'O trabalho de Buzz, Woody, Jessie e do resto da gangue fica exponencialmente mais difícil quando eles enfrentam uma nova ameaça à diversão: a tecnologia.', 100, NULL, '/jTN1hdfP88Km63waezqIN1uUqT3.jpg', '/qjTqY5coNiz6sVtPng40IzltsoN.jpg', 8.2, 2896, 67.81, 'en', 59, 100, 100, 85, 80, 50, 82, 60, 100, 1, '2026-11-18 19:12:48'),
(65, 891621, 'filme', 'Cavalo Selvagem Nove', 'Wild Horse Nine', 2026, 'Pouco antes do golpe de Estado no Chile em 1973, dois agentes da CIA são enviados de Santiago para a Ilha de Páscoa em uma missão de teste de confiança. Entre as famosas estátuas que são o marco da ilha, conhecidas como muais, eles enfrentam passados sombrios e conspirações, enquanto o envolvimento de um dos agentes com estudantes rebeldes ameaça arruinar a viagem.', 120, NULL, '/mfnJ58xi3BJLDf9sSHAfNm1QJY9.jpg', '/3uLA0ujne91bkzFStZICCYeqhnt.jpg', 8, 250, 67.76, 'en', 45, 66, 42, 91, 14, 62, 40, 52, 83, 1, '2026-11-18 19:12:49'),
(66, 1570488, 'filme', 'O Natal Perfeito de um Cachorro', 'A Dog\'s Perfect Christmas', 2026, 'Depois que uma emergência médica separa a família Goss, o determinado cãozinho Winstead faz de tudo para reunir seus humanos antes da véspera de Natal.', 102, NULL, '/2YhgEEGYOQfl3CzoRcYys8b6JxH.jpg', '/hhQT0TySg3LXCE8BEPpfPJ5zJA2.jpg', 7.2, 67, 66.76, 'en', 41, 60, 50, 49, 52, 50, 36, 52, 67, 1, '2026-11-18 19:12:49'),
(67, 1669915, 'filme', 'Angel and the Badman', 'Angel and the Badman', 2026, 'Um bandido ferido encontra uma misericórdia inesperada ao cuidar da filha de um fazendeiro. A esperança do amor o leva a uma vida diferente até que a lei e seu passado violento se aproximem de sua nova casa. Agora ele deve escolher o tipo de homem que ele se tornará.', 105, NULL, '/mJe53zlhGBdcjtN1GqncNZ5Unm0.jpg', '/hULWeQoEJUhiZ6NlANxsLoMJJ5p.jpg', 8.4, 22, 65.48, 'en', 41, 90, 76, 83, 66, 50, 100, 24, 100, 1, '2026-11-18 19:12:50'),
(68, 1117898, 'filme', 'O Gatola da Cartola', 'The Cat in the Hat', 2026, 'O Gatola da Cartola assume sua tarefa mais difícil até agora no I.I.I.I. — Instituto para Instituir a Imaginação e a Inspiração: animar e alegrar Gabby e Sebastian, dois irmãos com dificuldade para se adaptar à cidade para a qual acabaram de se mudar. Conhecido por levar as situações longe demais, esta pode ser a última chance de o agente do caos provar seu valor... ou perder seu chapéu mágico!', 114, NULL, '/sAUr79TPVXMmZrpsqGh6xTH9jy6.jpg', '/9y9o686DsQg0KzPtERzcW7Cf8IE.jpg', 7, 29, 61.14, 'en', 63, 100, 100, 79, 80, 50, 98, 70, 100, 1, '2026-11-18 19:12:50'),
(69, 1384216, 'filme', 'Ponto Sem Retorno', 'The Dog Stars', 2026, 'Após a população mundial ter sido devastada por uma pandemia, um homem vive uma existência solitária em um hangar de aviões no Colorado com seu cachorro e um pistoleiro taciturno com quem fez amizade. Quando uma transmissão misteriosa surge no rádio enquanto ele pilota seu velho Cessna, isso desencadeia uma busca pela origem do som.', 118, NULL, '/1C2qbfUW3lTzb8vpZeG8pjYzW3Q.jpg', '/3k7GzxOdLZkN3eZsuhLi2eRzkXO.jpg', 7.2, 1017, 60.22, 'en', 65, 48, 92, 100, 40, 70, 100, 86, 83, 1, '2026-11-18 19:12:51'),
(70, 155, 'filme', 'Batman: O Cavaleiro das Trevas', 'The Dark Knight', 2008, 'Após dois anos desde o surgimento do Batman, os criminosos de Gotham City têm muito o que temer. Com a ajuda do tenente James Gordon e do promotor público Harvey Dent, Batman luta contra o crime organizado. Acuados com o combate, os chefes do crime aceitam a proposta feita pelo Coringa e o contratam para combater o Homem-Morcego.', 152, NULL, '/dutnVGV9ljCZh84bkTE1TVZ4s4Y.jpg', '/cfT29Im5VDvjE0RpyKOSdCKZal7.jpg', 8.5, 37420, 59.92, 'en', 51, 44, 50, 100, 12, 62, 68, 51, 83, 1, '2026-11-18 19:12:52'),
(71, 1148365, 'filme', 'Matchbox - O Filme', 'Matchbox the Movie', 2026, 'Quando um grupo de antigos amigos de infância se reencontra, o encontro toma um rumo inesperado ao se depararem com uma perigosa trama internacional e precisarem salvar o mundo.', 127, NULL, '/hgPJA0NTmXYpPA3cgh4ZrI1PubL.jpg', '/jdJsnhHfkIi3J7jwfiCFT4gXNx5.jpg', 7.5, 647, 59.22, 'en', 45, 100, 76, 100, 64, 50, 86, 60, 83, 1, '2026-11-18 19:12:52'),
(72, 1204680, 'filme', 'Coyote vs. Acme', 'Coyote vs. Acme', 2026, 'Após décadas de falhas catastróficas com os produtos ACME em sua caçada ao Papa-Léguas, Wile E. Coyote decide que é hora de buscar justiça e processar a corporação. Ao lado de um advogado azarado, Coyote trava uma batalha jurídica épica contra o impiedoso CEO da companhia. Enquanto enfrentam o sistema, a dupla desenvolve uma amizade improvável e luta para provar que a culpa de tantos desastres nunca foi do instinto, mas sim de defeitos de fabricação.', 102, NULL, '/eZX2GyAJt5k0bL4OJbZGDvvxESD.jpg', '/rueyXwlewVPAP5NkqCUJx4RjhqB.jpg', 8.2, 1504, 57.84, 'en', 59, 100, 100, 85, 80, 50, 82, 60, 100, 1, '2026-11-18 19:12:53'),
(73, 157336, 'filme', 'Interestelar', 'Interstellar', 2014, 'As reservas naturais da Terra estão chegando ao fim e um grupo de astronautas recebe a missão de verificar possíveis planetas para receberem a população mundial, possibilitando a continuação da espécie. Cooper é chamado para liderar o grupo e aceita a missão sabendo que pode nunca mais ver os filhos. Ao lado de Brand, Jenkins e Doyle, ele seguirá em busca de um novo lar.', 169, NULL, '/tR1XVa5bxgdh2bRw2u0DzrgkO2l.jpg', '/8sNiAPPYU14PUepFNeSNGUTiHW.jpg', 8.5, 41939, 57.39, 'en', 57, 38, 100, 51, 44, 58, 80, 93, 83, 1, '2026-11-18 19:12:53'),
(74, 1232569, 'filme', 'Pinóquio: Maldição de Madeira', 'Pinocchio: Unstrung', 2026, 'O boneco de madeira Pinóquio é trazido à vida por forças macabras. Distante da inocência original, sua jornada para se tornar um menino de verdade é marcada por violência e vingança. À medida que Pinóquio persegue brutalmente aqueles que cruzam seu caminho, antigos laços familiares são distorcidos em horrores impensáveis.', 81, NULL, '/wgO649swkzsI58q3ikpxYNvkwv7.jpg', '/7RsPdXLDNugDIlwXPVeeprNfMx.jpg', 6.3, 174, 57.31, 'en', 75, 24, 96, 67, 24, 74, 56, 62, 83, 1, '2026-11-18 19:12:54'),
(75, 1108427, 'filme', 'Moana', 'Moana', 2026, 'Na Polinésia Antiga, quando uma terrível maldição contraída por Maui chega à ilha de um impetuoso chefe, sua filha obstinada responde ao chamado do Oceano para procurar o semideus e consertar as coisas. Adaptação live-action do filme de animação da Disney de 2016 \'Moana\'', 115, NULL, '/iHpNZzSMLWPfnDqTVuMyRIhrdiW.jpg', '/c6BPbkO5Npt1OdwttAxCFo06wtH.jpg', 7.4, 1071, 56.44, 'en', 53, 100, 100, 85, 80, 50, 98, 70, 100, 1, '2026-11-18 19:12:54'),
(76, 27, 'filme', '9 Canções', '9 Songs', 2004, 'Londres, verão de 2003. Matt conhece Lisa, uma jovem estudante americana, em meio a um show. Eles logo se apaixonam, vivendo um intenso relacionamento sexual entremeado por vários shows que acompanham.', 71, NULL, '/91O7z0vo7MiNWd5xD2BoivwbQsb.jpg', '/bybAHw5fenKXRFI4phanPhpljlT.jpg', 5.5, 613, 56.01, 'en', 51, 72, 50, 31, 50, 50, 36, 45, 83, 1, '2026-11-18 19:12:54'),
(77, 1195803, 'filme', 'Wicker', 'Wicker', 2026, NULL, 105, NULL, '/6FcBZOKvyrLCKGCyBG0ySCR4okt.jpg', '/xVh1ypMoVkMf5IB7y3hnRplJ14c.jpg', 7.5, 54, 53.86, 'en', 49, 100, 86, 47, 64, 50, 48, 56, 83, 1, '2026-11-18 19:12:55'),
(78, 1503762, 'filme', 'Razão e Sensibilidade', 'Sense and Sensibility', 2026, 'Uma nova e irresistível releitura do icônico romance “Razão e Sensibilidade”, de Jane Austen: uma história encantadora, espirituosa e com a qual é fácil se identificar, sobre amor e irmandade.', 125, NULL, '/kuSSXcjitZy1LLGGoB9XqLBPCYl.jpg', '/tIcONOFK9D3F89ETK8DBS1hIwVF.jpg', 7.2, 170, 52.59, 'en', 43, 46, 50, 19, 50, 50, 26, 46, 67, 1, '2026-11-18 19:12:55'),
(79, 1377237, 'filme', 'Três Horas Para Viver', 'Runner', 2026, 'Um transportador de elite embarca em uma missão urgente: entregar um órgão vital para salvar a vida de uma garotinha de sete anos. O que parecia ser uma tarefa objetiva logo se transforma em uma corrida frenética contra o tempo quando uma perigosa organização criminosa entra em cena para impedir o sucesso da entrega.', 98, NULL, '/vzb3bKOFtciIVSEIsLOZH4uJfxN.jpg', '/npXZNWjOEYrqdMDPQ11SGBrXqAG.jpg', 8.2, 862, 52.34, 'en', 45, 78, 58, 100, 48, 62, 72, 52, 83, 1, '2026-11-18 19:12:56'),
(80, 1375441, 'filme', 'Primetime', 'Primetime', 2026, 'Um jornalista determinado a tirar sua emissora da falência iminente cria um programa para expor ao vivo criminosos e se torna sucesso de audiência mudando a história televisiva. No entanto, um hacker descobre um segredo e os papéis podem acabar se invertendo.', 110, NULL, '/lmrulvLbmaejTix1YaMxo1oGhH1.jpg', '/sEsMwSDUWGIx9EfNxzM6KzVSsSQ.jpg', 6.8, 452, 51.94, 'en', 51, 20, 42, 69, 0, 62, 46, 52, 83, 1, '2026-11-18 19:12:57');
INSERT INTO catalogo_obras (id, tmdb_id, tipo, titulo, titulo_original, ano, sinopse, duracao, temporadas, poster_path, backdrop_path, nota, votos, popularidade, idioma_original, eixo_1, eixo_2, eixo_3, eixo_4, eixo_5, eixo_6, eixo_7, eixo_8, confianca, ativo, atualizado_em) VALUES
(81, 9963, 'filme', 'Premonições', 'Premonition', 2007, 'Linda Hanson é uma mulher suburbana que um dia é avisada que seu marido, Jim, morreu em um terrível desastre automobilístico. Porém, ao acordar no dia seguinte, tudo está perfeitamente normal em sua vida e Jim está vivo. A única diferença é que Bridgette, sua filha mais velha, está com cicatrizes horríveis no rosto, que Linda não tem a menor idéia de como surgiram. Sem entender o que está acontecendo, Linda começa a pôr em dúvida sua própria sanidade mental.', 96, NULL, '/bKBVU2i0DqloYqoxv803VAYsDCy.jpg', '/esXYvlivZ8j0HGqob949CIjqnGi.jpg', 6.3, 1761, 51.84, 'en', 57, 20, 50, 69, 16, 86, 54, 51, 83, 1, '2026-11-18 19:12:57'),
(82, 1376400, 'filme', 'Crawlers', 'Crawlers', 2026, NULL, 80, NULL, '/lNXeEpg4yLSRwXwOeR5lbPgwbqL.jpg', '/ayJsUQ4bEG6yY0UB6lMboiaDfYE.jpg', 6, 59, 51.15, 'en', 61, 12, 60, 91, 20, 62, 48, 52, 67, 1, '2026-11-18 19:12:58'),
(83, 1275779, 'filme', 'Dia D', 'Disclosure Day', 2026, 'O mundo entra em colapso quando uma meteorologista, em plena transmissão ao vivo, é dominada por uma força invisível, perdendo a fala e emitindo sons perturbadores. Enquanto fenômenos inexplicáveis e sinais de controle mental em massa se espalham, um informante tenta expor segredos governamentais guardados por décadas.', 146, NULL, '/pmff1wjKrgJi92PPr346lAifzlg.jpg', '/1e0KDRYKRPHiVNj8yQKYuU2jVyQ.jpg', 7.4, 4038, 51.13, 'en', 65, 40, 84, 81, 34, 70, 82, 86, 67, 1, '2026-11-18 19:12:58'),
(84, 1437396, 'filme', 'Your Mother Your Mother Your Mother', 'Your Mother Your Mother Your Mother', 2026, 'Latif é um muçulmano devoto, pai de três filhos e matador de aluguel guiado por um rígido código: não usa armas de fogo e só aceita alvos que considera merecedores. Após a morte da esposa, decide abandonar o crime e se dedicar à família. Mas o antigo patrão e uma guerra entre grupos religiosos de Houston frustram seus planos. Latif precisa encontrar leite materno para a filha bebê, ao mesmo tempo que a violência volta a cercá-lo e põe à prova sua fé e suas convicções.', 112, NULL, '/4KaPZSKnInnArErTTgy9Oy14leR.jpg', '/45Mbs6dmn2W0hvuyxXPDkKREHpP.jpg', 6.6, 79, 51.1, 'en', 51, 28, 50, 100, 6, 62, 64, 52, 100, 1, '2026-11-18 19:12:59'),
(85, 1476746, 'filme', 'A Última Entrega', 'The Florist', 2026, 'Um horticultor discreto, que secretamente é um assassino profissional, vê sua identidade ameaçada ao criar uma amizade inesperada com uma testemunha de corrupção policial.', 97, NULL, '/iVYJbqGrAgwPAcihayklVRd7ZMF.jpg', '/lpk0MwAn0UA3qCy9Iub4xMe15gv.jpg', 5.7, 40, 50.61, 'en', 59, 53, 58, 100, 40, 62, 76, 52, 67, 1, '2026-11-18 19:12:59'),
(86, 1255833, 'filme', 'Dentro da Baleia', 'Whalefall', 2026, 'Um jovem mergulhador resolveu buscar os restos mortais do seu pai em alto mar, mas no meio dessa triste aventura é capturado por uma baleia cachalote de 25 metros e 60 toneladas. Restando apenas uma hora de oxigênio, ele terá que fazer de tudo para encontrar uma forma de ir embora e seguir a sua vida, mas para isso terá que enfrentar uma grande jornada física e emocional para que ele consiga redescobrir a sua vontade de viver após a vivência do luto.', 106, NULL, '/66fDoNVCtPrP6jIqMpV1sUEcciw.jpg', '/shW2jHkQLZVv4Fko2rJDqTGU0gx.jpg', 6.6, 146, 50.32, 'en', 51, 40, 50, 81, 34, 62, 64, 52, 50, 1, '2026-11-18 19:13:02'),
(87, 1315772, 'filme', 'Minions & Monstros', 'Minions & Monsters', 2026, 'Esta é a frenética, ridícula e totalmente verdadeira história de como os Minions conquistaram Hollywood, se tornaram estrelas de cinema, perderam tudo, libertaram monstros pelo mundo e, depois, se uniram para tentar salvar o planeta do caos que eles mesmos haviam acabado de criar.', 87, NULL, '/hTowtXrkCY7FJyoj4p91JckrJSE.jpg', '/kkcwhgSFd81QDlXo8ytrpHPQjhy.jpg', 7.5, 1405, 49.81, 'en', 67, 100, 100, 85, 80, 50, 100, 70, 100, 1, '2026-11-18 19:13:02'),
(88, 27205, 'filme', 'A Origem', 'Inception', 2010, 'Cobb é um ladrão habilidoso que comete espionagem corporativa infiltrando-se no subconsciente de seus alvos durante o estado de sono. Impedido de retornar para sua família, ele recebe a oportunidade de se redimir ao realizar uma tarefa aparentemente impossível: plantar uma ideia na mente do herdeiro de um império. Para realizar o crime perfeito, ele conta com a ajuda do parceiro Arthur, o discreto Eames e a arquiteta de sonhos Ariadne. Juntos, eles correm para que o inimigo não antecipe seus passos.', 148, NULL, '/9e3Dz7aCANy5aRUQF745IlNloJ1.jpg', '/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg', 8.4, 40764, 48.87, 'en', 65, 54, 84, 89, 28, 58, 78, 85, 83, 1, '2026-11-18 19:13:02'),
(89, 299536, 'filme', 'Vingadores: Guerra Infinita', 'Avengers: Infinity War', 2018, 'Homem de Ferro, Thor, Hulk e os Vingadores se unem para combater seu inimigo mais poderoso, o maligno Thanos. Em uma missão para coletar todas as seis pedras infinitas, Thanos planeja usá-las para infligir sua vontade maléfica sobre a realidade.', 148, NULL, '/A4kvp7vY1BDLrrQIagRCffLKj1t.jpg', '/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 8.2, 33429, 48.31, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:13:03'),
(90, 980431, 'filme', 'Avatar Aang: O Último Mestre do Ar', 'Avatar Aang: The Last Airbender', 2026, 'O Avatar Aang, o último mestre do ar do mundo, toma conhecimento de um poder antigo que poderia salvar sua cultura da extinção. Com a ajuda de seus amigos, ele embarca em uma busca global para encontrá-lo antes que caia em mãos erradas e ameace destruir a paz que eles sacrificaram tudo para alcançar.', 99, NULL, '/tiUtJXN4OZaK2PQM0q8mbbBgKS4.jpg', '/ezbrL1dMymKQZw7mDEWa2ZTzN7d.jpg', 9, 1454, 47.55, 'en', 73, 86, 100, 100, 56, 50, 100, 70, 100, 1, '2026-11-18 19:13:03'),
(91, 1083381, 'filme', 'Backrooms: Um Não-Lugar', 'Backrooms', 2026, 'Em 1990, o vendedor de móveis Clark descobre em sua loja um portal para os \"Backrooms\", um labirinto infinito de escritórios surreais. Fascinado, ele convence sua funcionária Kat e o namorado dela a mapearem as anomalias do local. Após o desaparecimento de Clark, sua terapeuta, a Dra. Mary Kline, mergulha na dimensão impossível para resgatá-lo, sendo forçada a confrontar seus próprios traumas enquanto busca uma saída.', 110, NULL, '/3Rd8YUpupcJh0jxjqLn79UHb2in.jpg', '/QNE9Ihuas4duMHJYGQgAcuRtXz.jpg', 7, 4135, 46.74, 'en', 85, 22, 94, 73, 24, 82, 58, 86, 83, 1, '2026-11-18 19:13:04'),
(92, 693134, 'filme', 'Duna: Parte Dois', 'Dune: Part Two', 2024, 'A jornada de Paul Atreides continua. Ele está determinado a buscar vingança contra aqueles que destruíram sua família e seu lar. Com a ajuda de Chani e dos Fremen, ele embarca em uma jornada espiritual, mística e marcial. Se torna Muad\'Dib, o líder messiânico dos Fremen, enquanto luta para evitar um futuro sombrio que ele testemunhou em visões. No entanto, suas ações inadvertidamente desencadeiam uma Guerra Santa em seu nome, que se espalha pelo universo conhecido. Enquanto enfrenta escolhas difíceis entre o amor por Chani e o destino de seu povo, Paul…', 166, NULL, '/VMy4UGsI2u3f4fALGeCqCdsQBb.jpg', '/eZ239CUp1d6OryZEBPnO2n87gMG.jpg', 8.1, 9000, 46.45, 'en', 65, 62, 100, 75, 50, 58, 96, 94, 67, 1, '2026-11-18 19:13:04'),
(93, 278, 'filme', 'Um Sonho de Liberdade', 'The Shawshank Redemption', 1994, 'Em 1946, Andy Dufresne, um banqueiro jovem e bem sucedido, tem a sua vida radicalmente modificada ao ser condenado por um crime que nunca cometeu, o homicídio de sua esposa e do amante dela. Ele é mandado para uma prisão que é o pesadelo de qualquer detento, a Penitenciária Estadual de Shawshank, no Maine. Lá ele irá cumprir a pena perpétua. Andy logo será apresentado a Warden Norton, o corrupto e cruel agente penitenciário, que usa a Bíblia como arma de controle e ao Capitão Byron Hadley que trata os internos como animais. Andy faz amizade com Ellis…', 142, NULL, '/umX3lBhHoTV7Lsci140Yr8VpXyN.jpg', '/pNjh59JSxChQktamG3LMp9ZoQzp.jpg', 8.7, 31873, 45.37, 'en', 50, 30, 42, 45, 16, 50, 39, 49, 67, 1, '2026-11-18 19:13:05'),
(94, 1366, 'filme', 'Rocky: Um Lutador', 'Rocky', 1976, 'Rocky Balboa, um pequeno boxeador da classe trabalhadora da Filadélfia, é arbitrariamente escolhido para lutar contra o campeão dos pesos pesados, Apollo Creed, quando o adversário do invicto lutador agendado para a luta é ferido. Durante o treinamento com o mal-humorado Mickey Goldmill, Rocky timidamente começa um relacionamento com Adrian, a invisível irmã de Paulie, seu amigo empacotador de carne.', 119, NULL, '/b9B1DXcPNsJfTtc4x2LKA3bykoJ.jpg', '/bacOuUnRBoAO1NjMfsAGX2EKRrS.jpg', 7.8, 9110, 45.34, 'en', 44, 30, 50, 36, 44, 50, 46, 47, 50, 1, '2026-11-18 19:13:06'),
(95, 101299, 'filme', 'Jogos Vorazes: Em Chamas', 'The Hunger Games: Catching Fire', 2013, 'Após saírem vencedores da última edição dos Jogos Vorazes, as atitudes desafiadoras de Katniss e Peeta acabam inspirando uma rebelião contra a opressiva Capital. No entanto, os dois são obrigados a participarem de uma edição especial do torneio, o Massacre Quaternário, que acontece apenas a cada 25 anos, e reúne vencedores das edições anteriores.', 146, NULL, '/m1lky5ftnhLRpkoYWKssH8qvlRU.jpg', '/eHaazLxM5LRMh0ySkVy7SK6wUWt.jpg', 7.4, 19071, 44.82, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:13:06'),
(96, 533535, 'filme', 'Deadpool & Wolverine', 'Deadpool & Wolverine', 2024, 'Um apático Wade Wilson trabalha duro na vida civil. Seus dias como mercenário moralmente flexível, Deadpool, ficaram para trás. Quando seu planeta enfrenta uma ameaça, Wade deve relutantemente vestir-se novamente com um ainda mais relutante... relutante? Mais relutante? Ele deve convencer um Wolverine relutante em... Porra. As sinopses são tão estúpidas.', 128, NULL, '/cJFqqiDYprqExaXatu4AaoMzDG2.jpg', '/by8z9Fe8y7p4jo2YlW2SZDnptyT.jpg', 7.6, 9863, 43.39, 'en', 59, 88, 92, 99, 64, 58, 82, 86, 83, 1, '2026-11-18 19:13:06'),
(97, 83533, 'filme', 'Avatar: Fogo e Cinzas', 'Avatar: Fire and Ash', 2025, 'Após a devastadora guerra contra a RDA e a perda de seu filho mais velho, Jake Sully e Neytiri enfrentam uma nova ameaça em Pandora: o Povo das Cinzas, uma tribo Na\'vi violenta e sedenta por poder, liderada pela implacável Varang. A família de Jake deve lutar por sua sobrevivência e pelo futuro de Pandora em um conflito que os leva aos seus limites emocionais e físicos.', 197, NULL, '/3almrQT8GnrDjnQeWotdExjJhZm.jpg', '/u8DU5fkLoM5tTRukzPC31oGPxaQ.jpg', 7.6, 4706, 42.58, 'en', 73, 68, 100, 75, 50, 58, 100, 100, 83, 1, '2026-11-18 19:13:07'),
(98, 1128204, 'filme', 'Devorador', 'Feed', 2026, 'Cinco influencers passam um fim de semana na floresta para ajudar uma amiga a superar uma perda. Mas a escapada se torna uma visceral luta pela sobrevivência quando o sangue da jovem desperta o primeiro vampiro da história.', 83, NULL, '/zuhbisyyICXuYR8k3lE6pTpq5Vl.jpg', '/4ZeaWA6DzFVOjWTi70b9ZAaQktf.jpg', 6.6, 45, 42.56, 'en', 57, 18, 60, 61, 36, 50, 34, 52, 50, 1, '2026-11-18 19:13:07'),
(99, 24428, 'filme', 'Os Vingadores: The Avengers', 'The Avengers', 2012, 'Loki, o irmão de Thor, ganha acesso ao poder ilimitado do cubo cósmico ao roubá-lo de dentro das instalações da S.H.I.E.L.D. Nick Fury, o diretor desta agência internacional que mantém a paz, logo reúne os únicos super-heróis que serão capazes de defender a Terra de ameaças sem precedentes. Homem de Ferro, Capitão América, Hulk, Thor, Viúva Negra e Gavião Arqueiro formam o time dos sonhos de Fury, mas eles precisam aprender a colocar os egos de lado e agir como um grupo em prol da humanidade.', 143, NULL, '/PtSapjHdDjlVcsqdEo0u7rDE6i.jpg', '/9BBTo63ANSmhC4e6r62OJFuK2GL.jpg', 8.1, 40403, 42.39, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:13:08'),
(100, 438631, 'filme', 'Duna', 'Dune', 2021, 'Em um futuro distante, planetas são comandados por casas nobres que fazem parte de um império feudal intergalático. Paul Atreides é um jovem cuja família toma o controle do planeta deserto Arrakis, também conhecido como Duna. A única fonte da especiaria Melange, a substância mais importante do cosmos, Arrakis se mostra ser um planeta nem um pouco fácil de governar.', 155, NULL, '/uzERcfV2rSHNhW5eViQiO9hNiA7.jpg', '/qVgZu5BTx6pu4owCvVOm4zjTfOi.jpg', 7.8, 15990, 41.94, 'en', 65, 62, 100, 75, 50, 58, 96, 94, 67, 1, '2026-11-18 19:13:08'),
(101, 1458099, 'filme', 'O Último Batedor de Carteiras', 'The Only Living Pickpocket in New York', 2026, 'Harry Lehman é um batedor de carteiras veterano que continua na ativa, mas com rendimentos cada vez menores em uma Nova York profundamente transformada. As carteiras cheias de dinheiro foram substituídas por cartões de crédito fáceis de cancelar, e Harry luta para sobreviver enquanto cuida de Rosie, sua esposa com deficiência. Quando ele inadvertidamente rouba e repassa um valioso pen drive, inicia uma corrida contra o tempo para devolver o objeto, ou terá de enfrentar a fúria de uma vingativa família de criminosos.', 88, NULL, '/pNdB9va2AEPQe9UfhKAdIt8nus9.jpg', '/oahXjJ0UxnkJthITntGMrXVXQsJ.jpg', 7.5, 22, 41.84, 'en', 51, 20, 42, 69, 0, 62, 46, 52, 83, 1, '2026-11-18 19:13:09'),
(102, 238, 'filme', 'O Poderoso Chefão', 'The Godfather', 1972, 'Em 1945, Don Corleone é o chefe de uma mafiosa família italiana de Nova York. Ele costuma apadrinhar várias pessoas, realizando importantes favores para elas, em troca de favores futuros. Com a chegada das drogas, as famílias começam uma disputa pelo promissor mercado. Quando Corleone se recusa a facilitar a entrada dos narcóticos na cidade, não oferecendo ajuda política e policial, sua família começa a sofrer atentados para que mudem de posição. É nessa complicada época que Michael, um herói de guerra nunca envolvido nos negócios da família, vê a…', 175, NULL, '/oJagOzBu9Rdd9BrciseCm3U3MCU.jpg', '/tSPT36ZKlP2WVHJLM4cQPLSzv3b.jpg', 8.7, 24005, 41.84, 'en', 48, 30, 42, 42, 16, 50, 38, 47, 67, 1, '2026-11-18 19:13:09'),
(103, 14836, 'filme', 'Coraline e o Mundo Secreto', 'Coraline', 2009, 'Entediada em sua nova casa, a pequena Coraline descobre uma porta secreta que contém um mundo parecido com o dela, porém melhor em muitas maneiras. Coraline se encanta com a descoberta, mas logo descobre que há algo de errado quando seus pais alternativos tentam mantê-la eternamente nesse mundo paralelo.', 100, NULL, '/rranXmvqPT4NoXzmxhFtXr9nNYT.jpg', '/hofnlIyF6bePkgQOpcuRWLvzf15.jpg', 8, 9782, 41.78, 'en', 83, 60, 100, 67, 58, 50, 76, 61, 100, 1, '2026-11-18 19:13:10'),
(104, 671, 'filme', 'Harry Potter e a Pedra Filosofal', 'Harry Potter and the Philosopher\'s Stone', 2001, 'Harry Potter é um garoto órfão que vive infeliz com seus tios, os Dursley. Em seu aniversário de 11 anos ele recebe uma carta que mudará sua vida: um convite para ingressar em Hogwarts, uma Escola de Magia e Bruxaria.', 152, NULL, '/4rtsbE9aQ1qw4gv7yYwaNYfWFoS.jpg', '/5jkE2SzR5uR2egEb1rRhF22JyWN.jpg', 7.9, 30647, 41.75, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:10'),
(105, 131631, 'filme', 'Jogos Vorazes: A Esperança - Parte 1', 'The Hunger Games: Mockingjay - Part 1', 2014, 'Após sobreviver à temível arena dos Jogos Vorazes, Katniss Everdeen está desanimada e destruída. Depois que a Capital reduziu o Distrito 12 a destroços, ela se refugiou no Distrito 13. Peeta Mellark foi submetido a uma lavagem cerebral, e agora está sob o domínio de Snow. Então, a presidência quer que Katniss lidere uma \"resistência\" e mobilize a população em uma empreitada que irá colocá-la no centro da trama para desmascarar Snow.', 123, NULL, '/hekpVNWOROZm57RS4OLW0ySkxx9.jpg', '/lV1P1Q5gLDXVG1ZYCxZHStkcQC3.jpg', 6.8, 17253, 41.49, 'en', 65, 52, 100, 99, 34, 70, 100, 93, 83, 1, '2026-11-18 19:13:11'),
(106, 1302904, 'filme', 'Da Magia à Sedução: Feitiço de Amor', 'Practical Magic 2', 2026, 'O tempo passou, mas Sally e Gillian ainda são assombradas pela maldição do clã Owen, que todos que amam acabam morrendo. Agora, as duas devem confrontar poderes que ameaçam acabar com sua família de uma vez por todas.', 130, NULL, '/6xb6fv7MluhncJkNU6VtUWCBz3S.jpg', '/oIglj0Jy9duG4LnrRUpH8n001Pk.jpg', 7.2, 400, 40.29, 'en', 53, 100, 86, 53, 64, 50, 54, 56, 83, 1, '2026-11-18 19:13:11'),
(107, 120, 'filme', 'O Senhor dos Anéis: A Sociedade do Anel', 'The Lord of the Rings: The Fellowship of the Ring', 2001, 'Após herdar um anel de seu tio, o hobbit Frodo participa da missão de salvar a Terra-Média do perverso Sauron. Ele precisa conduzir o Um Anel até a Montanha da Perdição e destruí-lo para sempre e, para isso, conta com a aliança de oito bravos companheiros contando com um mago, três hobbits, um elfo, um anão e dois homens.', 179, NULL, '/tlvsNCwWEIgwAM23aNzTmMIcPEZ.jpg', '/oiwc338EoBgS4sEI2ixAny4KQKg.jpg', 8.5, 28899, 39.67, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:13:12'),
(108, 695721, 'filme', 'Jogos Vorazes: A Cantiga dos Pássaros e das Serpentes', 'The Hunger Games: The Ballad of Songbirds & Snakes', 2023, 'Anos antes de se tornar o tirânico presidente de Panem, Coriolanus Snow aos 18 anos vê uma chance de mudança de sorte quando é escolhido para ser mentor de Lucy Gray Baird, a garota tributo do empobrecido Distrito 12.', 157, NULL, '/a9z2cmIBfx99dtzj8TaSFU50AnW.jpg', '/bk1TitfD4YIGrM6AvljonMCtfnl.jpg', 7, 3819, 39.48, 'en', 70, 51, 92, 83, 52, 58, 86, 86, 67, 1, '2026-11-18 19:13:12'),
(109, 1751701, 'filme', 'After Impact', 'After Impact', 2026, 'Depois de herdar a enorme estufa de seu pai quando um asteróide ameaça a Terra, Ethan enfrenta traição e isolamento. Sobrevivendo ao impacto no bunker de sua família, maltratado e desesperado, uma voz no rádio revela que não está sozinho.', 95, NULL, '/yzDuAQCY2n6zzOlBkn6JzhLhY3k.jpg', '/k22XyPbce7zvzzf5OnT4uaY8ZD1.jpg', 5.7, 32, 39.44, 'en', 61, 20, 84, 63, 28, 70, 72, 86, 83, 1, '2026-11-18 19:13:13'),
(110, 634649, 'filme', 'Homem-Aranha: Sem Volta Para Casa', 'Spider-Man: No Way Home', 2021, 'Peter Parker é desmascarado e não consegue mais separar sua vida normal dos grandes riscos de ser um super-herói. Quando ele pede ajuda ao Doutor Estranho, os riscos se tornam ainda mais perigosos, e o forçam a descobrir o que realmente significa ser o Homem-Aranha...', 149, NULL, '/xaKydnMw6wR1MBAjS5seGPVusbs.jpg', '/iQFcwSGbZXMkeyKrxbPnwnRo5fl.jpg', 7.9, 23583, 39.32, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:13:13'),
(111, 1284046, 'filme', 'Protocolo de Extermínio', 'Onslaught', 2026, 'Uma sniper precisa lutar sozinha contra um esquadrão de soldados geneticamente modificados no meio do deserto para salvar sua filha pequena.', 92, NULL, '/S8yJg9VlcDRB55CFIBAF7V2lZ3.jpg', '/pmPXXniQlb4EdYY0gVZO90rf54F.jpg', 5.6, 151, 39.32, 'en', 61, 20, 68, 100, 26, 62, 66, 52, 83, 1, '2026-11-18 19:13:14'),
(112, 1559980, 'filme', 'Gospel de Natal', 'The Gospel of Christmas', 2026, 'Um pastor se muda com a família para um bairro complicado de Nova York e precisa salvar uma igreja do fechamento antes do Natal.', 104, NULL, '/5feAob9lh4WE2ZqlzqQulYegI9S.jpg', '/p1Ag7etCR5yUvElhwZmWsMo5IFu.jpg', 7.3, 21, 38.66, 'en', 55, 78, 56, 51, 66, 50, 64, 52, 83, 1, '2026-11-18 19:13:14'),
(113, 1130948, 'filme', 'Rosebush Pruning', 'Rosebush Pruning', 2026, 'Sob o sol da Catalunha, uma rica família branca norte-americana vive em um isolamento hedonista, buscando amor e validação uns nos outros, em suas roupas de grife e na música pop. Quando Jack, o irmão mais velho, apresenta sua noiva para a família, tensões há muito tempo reprimidas vêm à tona e os laços de sangue da matilha começam a se romper.', 97, NULL, '/uor0DM9RAc0ZwJXT4wrT8XAvsKL.jpg', '/vcZ3UUVmFNk90DBSrTBlTKCdbbE.jpg', 5.5, 76, 38.3, 'en', 46, 43, 50, 67, 32, 62, 38, 52, 83, 1, '2026-11-18 19:13:15'),
(114, 603, 'filme', 'Matrix', 'The Matrix', 1999, 'O jovem programador Thomas Anderson é atormentado por estranhos pesadelos em que está sempre conectado por cabos a um imenso sistema de computadores do futuro. À medida que o sonho se repete, ele começa a desconfiar da realidade. Thomas conhece os misteriosos Morpheus e Trinity e descobre que é vítima de um sistema inteligente e artificial chamado Matrix, que manipula a mente das pessoas e cria a ilusão de um mundo real enquanto usa os cérebros e corpos dos indivíduos para produzir energia.', 136, NULL, '/lDqMDI3xpbB9UQRyeXfei0MXhqb.jpg', '/tlm8UkiQsitc8rSuIAscQDCnP8d.jpg', 8.3, 29286, 37.77, 'en', 64, 58, 92, 89, 56, 58, 93, 83, 67, 1, '2026-11-18 19:13:15'),
(115, 1281331, 'filme', 'O Outro Lado das Redes', 'The Social Reckoning', 2026, 'Frances Haugen, uma jovem engenheira do Facebook, conta com a ajuda de Jeff Horwitz, repórter do The Wall Street Journal, para embarcar em uma jornada arriscada que acaba revelando alguns dos segredos mais bem guardados da rede social.', 112, NULL, '/51AEphEZ5JXaV0FL5PGITjLQE0m.jpg', '/wXTaGcqX3jvdXSKCJAkl5jZyrKp.jpg', 7, 142, 36.49, 'en', 47, 20, 50, 63, 28, 62, 54, 52, 67, 1, '2026-11-18 19:13:16'),
(116, 153518, 'filme', 'Angry Birds: O Filme', 'The Angry Birds Movie', 2016, 'Red, um pássaro com problemas de temperamento, o veloz Chuck, e o volátil Bomba sempre foram excluídos. Mas quando a ilha onde moram é visitada por misteriosos porquinhos verdes, cabe a estes improváveis rejeitados descobrir qual o plano da gangue suína.', 95, NULL, '/awL1XD7ukn3Lg3GDJDyP3MZwyz8.jpg', '/o4mhrLxv6I70kvYA42qANGUF7ya.jpg', 6.3, 4199, 36.33, 'en', 59, 100, 100, 66, 80, 50, 76, 60, 100, 1, '2026-11-18 19:13:16'),
(117, 1286656, 'filme', 'Eu Sou o Rocky', 'I Play Rocky', 2026, 'Antes de Rocky se tornar uma lenda que atravessa gerações, Stallone precisou lutar para sobreviver. Na pele de um ator fracassado, ele escreve a história definitiva de um perdedor e precisa lutar pela chance de interpretar o papel de sua vida: Rocky Balboa. Conheça a trajetória por trás da criação de Rocky: Um Lutador.', 128, NULL, '/yGJDq5MAzGcFal1oFwLedeGkWGX.jpg', '/1lnnjBCRLZzKRhQipK5zm61YkPe.jpg', 8.5, 40, 35.85, 'en', 39, 30, 50, 27, 44, 50, 62, 20, 67, 1, '2026-11-18 19:13:17'),
(118, 1226863, 'filme', 'Super Mario Galaxy: O Filme', 'The Super Mario Galaxy Movie', 2026, 'Depois de salvar o Reino dos Cogumelos, Mario e seus amigos se encontram em uma missão intergaláctica para deter um novo vilão ameaçador.', 95, NULL, '/b3WeTp42eJSRuE4UZfyPCOJW4c.jpg', '/kxQiIJ4gVcD3K6o14MJ72p5yRcE.jpg', 8.2, 3991, 35.8, 'en', 75, 100, 100, 70, 80, 50, 91, 67, 100, 1, '2026-11-18 19:13:17'),
(119, 2034, 'filme', 'Dia de Treinamento', 'Training Day', 2001, 'Jake Hoyt, um jovem policial de Los Angeles, entra para a equipe de narcóticos da polícia e recebe como oficial de treinamento e parcerio Alonzo Harris, um policial veterano e corrupto. Com o passar do dia, o jovem é exposto a todo tipo de corrupção e é ainda acusado de assassinato, acontecimentos que são orquestrados por Alonzo a fim de encobrir um engano cometido por ele junto à máfia russa, que pode fazer com que ele seja morto se não conseguir uma grande quantia de dinheiro até a meia-noite.', 122, NULL, '/ju2TUNXdCosCMOWXJA1BxtylyOj.jpg', '/nuO8o9ltxhI7AZQxePavEZ4TyHa.jpg', 7.5, 7026, 35.72, 'en', 51, 38, 50, 77, 22, 50, 56, 51, 83, 1, '2026-11-18 19:13:18'),
(120, 414906, 'filme', 'Batman', 'The Batman', 2022, 'Em seu segundo ano de combate ao crime, Batman descobre corrupção em Gotham City que se conecta à sua própria família enquanto enfrenta um serial killer conhecido como Charada.', 185, NULL, '/wd7b4Nv9QBHDTIjc2m7sr0IUMoh.jpg', '/rvtdN5XkWAfGX6xDuPL6yYS2seK.jpg', 7.7, 12918, 35.53, 'en', 65, 40, 42, 93, 0, 86, 56, 52, 83, 1, '2026-11-18 19:13:18'),
(121, 1561726, 'filme', 'Masterplan', 'Masterplan', 2026, 'Quando um ladrão lendário decide roubar a Mona Lisa, ele recruta dois jovens para ajudá-lo: Chiara, especialista italiana em crimes cibernéticos, e Jay, especialista francês em explosivos. Eles só não sabem que ele é pai dos dois. Em meio a um reencontro caótico, a nova família terá que aprender a trabalhar em equipe – e tentar não se matar - se quiser ter chances de realizar o roubo do século.', 109, NULL, '/5xmXVd7nCK3tAo34XkO58SxUCip.jpg', '/fAlQZsCOCvxOj0PmFmt4i8IWR2u.jpg', 6.7, 252, 35.49, 'en', 57, 41, 58, 95, 40, 62, 72, 52, 67, 1, '2026-11-18 19:13:19'),
(122, 122, 'filme', 'O Senhor dos Anéis: O Retorno do Rei', 'The Lord of the Rings: The Return of the King', 2003, 'O confronto final entre as forças do bem e do mal que lutam pelo controle do futuro da Terra-Média se aproxima. Sauron planeja um grande ataque a Minas Tirith, capital de Gondor, o que faz com que Gandalf e Pippin partam para o local na intenção de ajudar a resistência. Um exército é reunido por Théoden em Rohan, em mais uma tentativa de deter as forças de Sauron. Enquanto isso, Frodo, Sam e Gollum seguem sua viagem rumo à Montanha da Perdição para destruir o Um Anel.', 202, NULL, '/rU4oIKv5I4C59DpcXKmT7kNwGI0.jpg', '/ctiw6FZK4N36LmkjSklWEbuvlq9.jpg', 8.5, 27854, 35.35, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:13:19'),
(123, 858035, 'filme', 'Klara e o Sol', 'Klara and the Sun', 2026, 'Klara é uma Amiga Artificial que deseja apenas encontrar o lar perfeito. Quando conhece Josie, ambas imediatamente percebem uma espécie de alma gêmea uma na outra. Josie tem uma relação conturbada com a mãe e ambas sofreram grandes perdas, mas a inocência e a lealdade inabalável de Klara começam a curar a família e a trazer luz ao mundo complicado de Josie.', 95, NULL, '/cO85DOKRaAzkU9WFDfDSF9rt1Dk.jpg', '/2Zk5jRXUlrfkU3RsutMPMHey1Y.jpg', 6.1, 34, 34.59, 'en', 57, 26, 84, 33, 44, 58, 58, 86, 67, 1, '2026-11-18 19:13:20'),
(124, 1273221, 'filme', 'Todo Mundo em Pânico', 'Scary Movie', 2026, 'Vinte e seis anos depois de escaparem de um assassino mascarado suspeitosamente familiar, o Quarteto Fantástico está de volta à mira do criminoso, e nenhuma propriedade intelectual de filmes de terror está a salvo.', 95, NULL, '/y9yJd2qIIwhZcllHeKHsz5eRvNr.jpg', '/xWBiXclrRmTggQHMRsIn84YHavs.jpg', 6.3, 2150, 34.14, 'en', 45, 80, 50, 67, 58, 50, 46, 52, 50, 1, '2026-11-18 19:13:21'),
(125, 213, 'filme', 'Intriga Internacional', 'North by Northwest', 1959, 'Confundido com um agente secreto, de uma hora para outra o publicitário Roger Tornhill se vê envolvido numa complicada trama de espionagem, sendo acusado inclusive de assassinato. Enquanto tenta provar sua inocência, é perseguido tanto pela polícia como por agentes criminosos.', 136, NULL, '/fYMQBR5SXqMoOYsOBxgZYEtXTr7.jpg', '/OR8oloCZ3klJtB7Y0i8pSqWw5a.jpg', 8, 4742, 33.83, 'en', 47, 52, 68, 95, 36, 62, 88, 53, 67, 1, '2026-11-18 19:13:21'),
(126, 872585, 'filme', 'Oppenheimer', 'Oppenheimer', 2023, 'A história do físico americano J. Robert Oppenheimer, seu papel no Projeto Manhattan e no desenvolvimento da bomba atômica durante a Segunda Guerra Mundial, e o quanto isso mudaria a história do mundo para sempre.', 181, NULL, '/dUPQszWoRSE9FucJTbVp2bwEi9G.jpg', '/neeNHeXjMF5fXoCJRsOmkNGC7q.jpg', 8, 12934, 33.77, 'en', 35, 2, 50, 27, 54, 50, 82, 8, 83, 1, '2026-11-18 19:13:22'),
(127, 1081003, 'filme', 'Supergirl', 'Supergirl', 2026, 'Quando um adversário implacável atinge alguém muito próximo dela, Kara Zor-El relutantemente une forças com uma companheira improvável em uma épica jornada interestelar de vingança e justiça.', 108, NULL, '/pgKFmJ4mvohpI6LUdRj6uIn6wQR.jpg', '/heZQmyNvkH236ha2M3JckdUQQqb.jpg', 6.6, 2747, 33.65, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:13:23'),
(128, 1084242, 'filme', 'Zootopia 2', 'Zootopia 2', 2025, 'Os detetives Judy Hopps e Nick Wilde se encontram na trilha sinuosa de um réptil misterioso que chega a Zootopia e vira a metrópole dos mamíferos de cabeça para baixo.', 108, NULL, '/sOgzzmyHJ3uWjEU509AwrcXoE71.jpg', '/lgotja3xMoJZbynwHfcQcJAEMWH.jpg', 7.7, 3702, 33.64, 'en', 69, 100, 100, 91, 68, 74, 82, 60, 100, 1, '2026-11-18 19:13:23'),
(129, 9495, 'filme', 'O Corvo', 'The Crow', 1994, 'O roqueiro Eric Draven está morto... Mas, estranhamente, ele ainda vive. Ele ainda não pode descansar em paz. Não enquanto os vermes responsáveis por sua morte e também pelo assassinato de sua noiva permanecerem vivos. Assim, Draven retorna de seu túmulo para submeter seus matadores à uma implacável vingança. E ele não está sozinho. Um amedrontador corvo do outro mundo guia Draven em sua jornada.', 101, NULL, '/41JAMG1NlbfhKJ9Hh5Um9e3YXfW.jpg', '/2VN9umruwVZsT1Pr1NMCV71HpUu.jpg', 7.5, 4787, 33.53, 'en', 58, 54, 94, 100, 40, 62, 100, 59, 83, 1, '2026-11-18 19:13:24'),
(130, 1236045, 'filme', 'Sobrevivência', 'Animals', 2026, 'O filho de um candidato a prefeito de Los Angeles é sequestrado. Agora, ele e a esposa tentam conseguir o dinheiro do resgate e tomam decisões arriscadas.', 109, NULL, '/62vtHEyzKhFRuEOLLiQfPi60mSs.jpg', '/5yzM78Tp8nYwSCQtyRcmnHmCn5C.jpg', 6.9, 759, 33.5, 'en', 51, 28, 50, 100, 6, 62, 64, 52, 100, 1, '2026-11-18 19:13:24'),
(131, 550, 'filme', 'Clube da Luta', 'Fight Club', 1999, 'Um homem deprimido que sofre de insônia conhece um estranho vendedor de sabonetes chamado Tyler Durden. Eles formam um clube clandestino com regras rígidas onde lutam com outros homens cansados de suas vidas mundanas. Mas sua parceria perfeita é comprometida quando Marla chama a atenção de Tyler.', 139, NULL, '/mCICnh7QBH0gzYaTQChBDDVIKdm.jpg', '/c6OLXfKAk5BKeR6broC8pYiCquX.jpg', 8.4, 33373, 33.4, 'en', 51, 13, 50, 57, 24, 62, 49, 49, 67, 1, '2026-11-18 19:13:25'),
(132, 99861, 'filme', 'Vingadores: Era de Ultron', 'Avengers: Age of Ultron', 2015, 'Ao tentar proteger o planeta de ameaças, Tony Stark constrói um sistema de inteligência artificial que cuidaria da paz mundial. O projeto acaba dando errado e gera o nascimento do Ultron. Com o destino da Terra em jogo, os Vingadores terão que se unir para mais uma vez salvar a raça humana da extinção.', 141, NULL, '/uvzqTsRmUzk9mJVzX8cMSWMyM5l.jpg', '/kIBK5SKwgqIIuRKhhWrJn3XkbPq.jpg', 7.3, 25370, 33.23, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:13:25'),
(133, 8913, 'filme', 'Cemitério Maldito', 'Pet Sematary', 1989, 'Recentemente os Creeds se mudaram para uma nova casa nos arredores de Chicago. A casa é perfeita, exceto por duas coisas: Os reboques, que vivem fazendo barulho na estrada, e o misterioso cemitério no bosque atrás da casa. Os vizinhos dos Creeds estão relutantes em falar sobre o cemitério e eles tem um bom motivo para tal comportamento. Gradativamente o casal toma conhecimento da verdade e ficam chocados ao saberem do perigo que seus filhos correm. Quando o gato da família morre atropelado, eles o enterram em um cemitério indígena que tem o poder de…', 103, NULL, '/5sBCDm9sFRS2LmlvBH7381Q53Wm.jpg', '/xWq3T9P4NU2pTdZ3hXFygsNnAq4.jpg', 6.7, 2529, 32.97, 'en', 60, 22, 60, 67, 36, 50, 41, 49, 50, 1, '2026-11-18 19:13:26'),
(134, 936075, 'filme', 'Michael', 'Michael', 2026, 'A história da vida de Michael Jackson além da música, traçando sua jornada desde a descoberta de seu talento extraordinário como líder dos Jackson Five até o artista visionário cuja ambição criativa impulsionou uma busca implacável para se tornar o maior artista do mundo.', 128, NULL, '/gKWVxVJ5Q0JcQKj2Z8Hu5Qwo7s2.jpg', '/ufSwlnECLoUbBjPrFqEQcWBzHwc.jpg', 8.6, 4745, 32.89, 'en', 55, 56, 50, 51, 44, 50, 56, 52, 67, 1, '2026-11-18 19:13:26'),
(135, 70160, 'filme', 'Jogos Vorazes', 'The Hunger Games', 2012, 'Num futuro distante, boa parte da população é controlada por um regime totalitário, que relembra esse domínio realizando um evento anual – e mortal – entre os 12 distritos sob sua tutela. Para salvar sua irmã caçula, a jovem Katniss Everdeen se oferece como voluntária para representar seu distrito na competição e acaba contando com a companhia de Peeta Melark, desafiando não só o sistema dominante, mas também a força dos outros oponentes.', 142, NULL, '/l6jn53LMu07uPt8A42JWIKi1Beb.jpg', '/eVYChqJavS1DCXFeJE2lzVUMLKp.jpg', 7.2, 24048, 32.3, 'en', 65, 60, 100, 100, 40, 70, 100, 93, 100, 1, '2026-11-18 19:13:26'),
(136, 674, 'filme', 'Harry Potter e o Cálice de Fogo', 'Harry Potter and the Goblet of Fire', 2005, 'Em seu 4º ano na Escola de Magia e Bruxaria de Hogwards, Harry Potter é misteriosamente selecionado para participar do Torneio Tribruxo, uma competição internacional em que precisará enfrentar alunos mais velhos e experientes de Hogwards e também de outras escolas de magia. Além disso a aparição da marca negra de Voldemort ao término da Copa Mundial de Quadribol põe a comunidade de bruxos em pânico, já que sinaliza que o temido bruxo está prestes a retornar.', 157, NULL, '/5oWB3hjzyECRBAjgWkmZinxl9qA.jpg', '/8f9dnOtpArDrOMEylpSN9Sc6fuz.jpg', 7.8, 22954, 31.35, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:27'),
(137, 597, 'filme', 'Titanic', 'Titanic', 1997, 'Um artista pobre e uma jovem rica se conhecem e se apaixonam na fatídica jornada do Titanic, em 1912. Embora esteja noiva do arrogante herdeiro de uma siderúrgica, a jovem desafia sua família e amigos em busca do verdadeiro amor.', 194, NULL, '/As0zX43h3w6kD2NS4uVHu9HKdEh.jpg', '/sCzcYW9h55WcesOqA12cgEr9Exw.jpg', 7.9, 28097, 31.06, 'en', 46, 50, 50, 25, 50, 50, 33, 43, 67, 1, '2026-11-18 19:13:27'),
(138, 772, 'filme', 'Esqueceram de Mim 2: Perdido em Nova York', 'Home Alone 2: Lost in New York', 1992, 'Garoto se vê novamente sozinho, quando em virtude de uma confusão no aeroporto que fez com que ele ao invés de embarcar com a família para a Flórida partisse sozinho para Nova York. Mas como tinha o cartão de crédito do pai, ele se hospeda no melhor hotel da cidade, mas também encontra os dois ladrões que tinha enfrentado no passado e que agora planejam se vingar dele.', 120, NULL, '/qffLHZU9mU0zqmOISnjir2oDEsR.jpg', '/8fnYJPoXxwAN4valDLgz2whMGTH.jpg', 6.8, 11077, 31.03, 'en', 44, 100, 74, 85, 80, 50, 77, 57, 83, 1, '2026-11-18 19:13:28'),
(139, 131634, 'filme', 'Jogos Vorazes: A Esperança - O Final', 'The Hunger Games: Mockingjay - Part 2', 2015, 'Katniss e seus amigos Peeta, Gale e Finnick embarcam em sua última missão: organizar uma resistência contra o presidente e libertar o povo de Panem. A coragem de Katniss faz renascer a esperança em um país disposto a se livrar da opressão.', 136, NULL, '/5KSQkozSelQj6bq8NCKtINvsSSj.jpg', '/qVgLMRVNB5bHU0inmRa0ueShacN.jpg', 6.9, 13787, 30.91, 'en', 70, 63, 100, 100, 52, 58, 100, 94, 83, 1, '2026-11-18 19:13:28'),
(140, 1050981, 'filme', 'A Arte de Ser Heumann', 'Being Heumann', 2026, 'Firme, exigente e cansada de ser tratada como um fardo, Judy Heumann faz de sua indignação uma revolução. Em 1977, ela e mais de 100 manifestantes pelos direitos das pessoas com deficiência enviam uma mensagem contundente: o sistema é deficiente, não nós.', 127, NULL, '/k9uyh5Fdm2d2cdpNryVvlsnpTnM.jpg', '/25aB8RXP4mfQLFRSuEEhk0d0sTC.jpg', 7, 27, 30.89, 'en', 39, 30, 50, 27, 44, 50, 62, 20, 67, 1, '2026-11-18 19:13:29'),
(141, 453395, 'filme', 'Doutor Estranho no Multiverso da Loucura', 'Doctor Strange in the Multiverse of Madness', 2022, 'Doutor Estranho, com a ajuda de aliados místicos antigos e novos, atravessa as perigosas realidades alternativas e alucinantes do Multiverso para enfrentar um novo adversário misterioso.', 126, NULL, '/7pLIVfovuIf2KQOOvMsKx3Lanrg.jpg', '/AdyJH8kDm8xT8IKTlgpEC15ny4u.jpg', 7.2, 11146, 30.5, 'en', 59, 76, 100, 100, 56, 50, 100, 70, 83, 1, '2026-11-18 19:13:30'),
(142, 680, 'filme', 'Pulp Fiction: Tempo de Violência', 'Pulp Fiction', 1994, 'Vincent Vega e Jules Winnfield são dois assassinos profissionais que trabalham fazendo cobranças para Marsellus Wallace, um poderosos gângster. Vega é forçado a sair com a garota do chefe, temendo passar dos limites. Enquanto isso, o pugilista Butch Coolidge se mete em apuros por ganhar uma luta que deveria perder.', 154, NULL, '/tptjnB2LDbuUWya9Cx5sQtv5hqb.jpg', '/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg', 8.5, 31361, 30.44, 'en', 48, 70, 42, 97, 14, 62, 47, 49, 83, 1, '2026-11-18 19:13:30'),
(143, 1726, 'filme', 'Homem de Ferro', 'Iron Man', 2008, 'Tony Stark é um industrial bilionário, que também é um brilhante inventor. Ao ser sequestrado ele é obrigado por terroristas a construir uma arma devastadora mas, ao invés disto, constrói uma armadura de alta tecnologia que permite que fuja de seu cativeiro. A partir de então ele passa a usá-la para combater o crime, sob o alter ego do Homem de Ferro.', 126, NULL, '/mqN7RxojEiPoh3FTSTwOtwg7KAu.jpg', '/cKvDv2LpwVEqbdXWoQl4XgGN6le.jpg', 7.7, 29209, 30, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:13:32'),
(144, 244786, 'filme', 'Whiplash: Em Busca da Perfeição', 'Whiplash', 2014, 'Andrew sonha em ser o melhor baterista de sua geração. Ele chama a atenção do impiedoso mestre do jazz Terence Fletcher, que ultrapassa os limites e transforma seu sonho em uma obsessão, colocando em risco a saúde física e mental do jovem músico.', 107, NULL, '/2msJb27jMeuA101ox4MuTQK4mDa.jpg', '/fRGxZuo7jJUWQsVg9PREb98Aclp.jpg', 8.4, 17415, 29.83, 'en', 55, 46, 50, 75, 28, 62, 64, 51, 83, 1, '2026-11-18 19:13:32'),
(145, 121, 'filme', 'O Senhor dos Anéis: As Duas Torres', 'The Lord of the Rings: The Two Towers', 2002, 'Após a captura de Merry e Pippin pelos orcs, a Sociedade do Anel é dissolvida. Frodo e Sam seguem sua jornada rumo à Montanha da Perdição para destruir o anel e serão obrigados a confiar no misterioso Gollum. Enquanto isso, Aragorn, o elfo e o arqueiro Legolas e o anão Gimli partem para resgatar os hobbits sequestrados e chegam ao reino de Rohan, onde o rei Théoden foi vítima de uma maldição mortal de Saruman.', 180, NULL, '/mCs8vxvScCqVM3YFMQIdbrdFEhu.jpg', '/6G73mNyooWAEQTpckPSnFxFoNmc.jpg', 8.4, 25008, 29.59, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:13:33'),
(146, 1007757, 'filme', 'Como Mágica', 'Swapped', 2026, 'Uma pequena criatura da floresta e um pássaro majestoso trocam de corpo e precisam se unir para sobreviver à aventura mais incrível de suas vidas.', 102, NULL, '/2TZiL4ZYOwWeIjGfz3glpMuPqpN.jpg', '/zMwhWailP1WY7sb6AoE6b8ugoy.jpg', 8.8, 2304, 29.33, 'en', 73, 100, 100, 75, 72, 50, 100, 70, 100, 1, '2026-11-18 19:13:36'),
(147, 11, 'filme', 'Guerra nas Estrelas', 'Star Wars', 1977, 'A princesa Leia é mantida refém pelas forças imperiais comandadas por Darth Vader. Luke Skywalker e Han Solo precisam libertá-la e restaurar a liberdade e a justiça na galáxia.', 121, NULL, '/dw7X9YPjjAfIxKHW04V64Bb9TB0.jpg', '/4qCqAdHcNKeAHcK8tJ8wNJZa9cx.jpg', 8.2, 23186, 29.14, 'en', 62, 70, 100, 100, 56, 58, 100, 89, 83, 1, '2026-11-18 19:13:37'),
(148, 13, 'filme', 'Forrest Gump: O Contador de Histórias', 'Forrest Gump', 1994, 'Quarenta anos da história dos Estados Unidos, vistos pelos olhos de Forrest Gump, um rapaz com QI abaixo da média e com boas intenções. Por obra do acaso, ele consegue participar de momentos cruciais, como a Guerra do Vietnã e o Caso Watergate, mas continua pensando no seu amor de infância, Jenny Curran.', 142, NULL, '/d74WpIsH8379TIL4wUxDneRCYv2.jpg', '/66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg', 8.5, 30914, 28.83, 'en', 40, 80, 50, 35, 58, 50, 23, 43, 83, 1, '2026-11-18 19:13:38'),
(149, 672, 'filme', 'Harry Potter e a Câmara Secreta', 'Harry Potter and the Chamber of Secrets', 2002, 'De férias na casa de seus tios, Harry Potter recebe a visita de Dobby, um elfo doméstico, que veio avisá-lo para não retornar à Escola de Magia e Bruxaria de Hogwarts, pois lá correrá um grande perigo. Harry não lhe dá ouvidos e decide retornar aos estudos, enfrentando um segundo ano recheado de novidades. Uma delas é a contratação de um novo professor, Gilderoy Lockhart, um grande galã que não perde uma oportunidade de fazer marketing pessoal. Porém, o aviso de Dobby se confirma e logo toda Hogwarts está envolvida em um mistério que resulta no…', 161, NULL, '/811j0Jf2D0mK1U6RxXJoZgOB29n.jpg', '/7tbeoSTWW2cWPecjQo9fcdf0Hzv.jpg', 7.7, 24426, 28.71, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:39'),
(150, 335984, 'filme', 'Blade Runner 2049', 'Blade Runner 2049', 2017, 'Trinta anos após os acontecimentos do primeiro filme, um novo blade runner, o oficial K da polícia de Los Angeles, desenterra um segredo há muito enterrado que tem o potencial de mergulhar o que resta da sociedade no caos. A descoberta de K o leva a uma busca para encontrar Rick Deckard, um ex-blade runner do LAPD que está desaparecido há 30 anos.', 164, NULL, '/49pANIZXRAdHUiWjjBv4vxPeqRC.jpg', '/gNdLJU9TxrpGx4dkZidjys3fyy0.jpg', 7.6, 16042, 28.48, 'en', 57, 26, 84, 33, 44, 58, 58, 86, 67, 1, '2026-11-18 19:13:39'),
(151, 673, 'filme', 'Harry Potter e o Prisioneiro de Azkaban', 'Harry Potter and the Prisoner of Azkaban', 2004, 'É o início do terceiro ano na escola de magia e bruxaria de Hogwarts. Harry, Ron e Hermione têm muito o que aprender. Mas uma ameaça ronda a escola e ela se chama Sirius Black. Após doze anos encarcerado na prisão de Azkaban, ele consegue escapar e volta para vingar seu mestre, Lord Voldemort. Para piorar, os Dementores, guardas supostamente enviados para proteger Hogwarts e seguir os passos de Black, parecem ser ameaças ainda mais perigosas.', 142, NULL, '/1HdMUghqlgOIvbsU9ZtO40IPRzl.jpg', '/vbk5CfaAHOjQPSAcYm6AoRRz2Af.jpg', 8, 24001, 28.11, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:40'),
(152, 1560520, 'filme', 'Batman: A Queda do Morcego - Parte 1', 'Batman: Knightfall Part 1: Knightfall', 2026, 'O Asilo Arkham foi destruído, e todos os seus detentos foram soltos em Gotham City. Enquanto corre contra o tempo para capturar alguns de seus maiores inimigos, Batman é levado ao limite de suas capacidades físicas e mentais, rumo a um confronto final contra uma nova ameaça: o homem chamado Bane!', 79, NULL, '/kOeLi6uIhAlWchS7ZkgDwWSavYT.jpg', '/caBIySpwuFi2i7ynvHIlnxJLOdN.jpg', 9.1, 512, 28.04, 'en', 61, 60, 100, 89, 50, 50, 92, 60, 100, 1, '2026-11-18 19:13:41'),
(153, 1327819, 'filme', 'Cara de Um, Focinho de Outro', 'Hoppers', 2026, 'Mabel é uma jovem amante da natureza que tenta impedir o prefeito Jerry de construir uma rodovia que destruirá suas florestas locais. Graças a um experimento secreto de troca de cérebros, Mabel consegue transferir sua mente para um castor robô e segue para um lago, onde refugiados da industrialização invasora desembarcaram. Lá, ela tenta convencer os animais, liderados pelo castor majestoso Rei George, a se juntarem a ela e impedirem a construção da rodovia.', 105, NULL, '/ftPFJBGbldoWiiPrmesW96zBzdH.jpg', '/u53UYu5XG2hNgWGvs3xGhAVzypl.jpg', 8.1, 2539, 27.79, 'en', 73, 100, 100, 85, 80, 58, 100, 94, 100, 1, '2026-11-18 19:13:41'),
(154, 1607127, 'filme', 'O Último Tiro Certo', 'One Last Shot', 2026, 'O Navy SEAL Jake Harris volta à ação quando um ex-companheiro ameaça o mundo.', 98, NULL, '/owdiTFWuWq4UxPth6nXNsO6x74Q.jpg', '/7AArZYRp6zGtbvSbbqoHn9xFp0L.jpg', 7.3, 169, 27.52, 'en', 47, 44, 58, 100, 40, 62, 76, 52, 67, 1, '2026-11-18 19:13:42'),
(155, 557, 'filme', 'Homem-Aranha', 'Spider-Man', 2002, 'Peter Parker é um jovem estudioso que vive com seus tios, Ben e May, desde que seus pais faleceram. Peter tem dificuldade em se relacionar com seus colegas, por ser tímido e por eles o considerarem um nerd. Até que, em uma demonstração científica, um acidente inesperado faz com que uma aranha modificada geneticamente pique Peter. A partir de então seu corpo é quimicamente alterado pela picada da aranha.', 121, NULL, '/RbZQL5hXmydecu82UHw9ZGyytB.jpg', '/zQ8AxTPiCiS5nnwXpwTBPBHSaa5.jpg', 7.4, 21805, 27.49, 'en', 65, 58, 92, 89, 56, 58, 92, 85, 67, 1, '2026-11-18 19:13:43'),
(156, 361743, 'filme', 'Top Gun: Maverick', 'Top Gun: Maverick', 2022, 'Depois de mais de 30 anos de serviço como um dos principais aviadores da Marinha, Pete \"Maverick\" Mitchell está de volta, rompendo os limites como um piloto de testes corajoso. No mundo contemporâneo das guerras tecnológicas, Maverick enfrenta drones e prova que o fator humano ainda é essencial.', 131, NULL, '/kPbuLGVSJHATkW9fX9L3h1wM0Pa.jpg', '/AaV1YIdWKnjAIAOe8UUKBFm327v.jpg', 8.2, 11930, 27.45, 'en', 47, 38, 58, 71, 50, 50, 64, 52, 67, 1, '2026-11-18 19:13:43'),
(157, 760104, 'filme', 'X: A Marca da Morte', 'X', 2022, 'Em 1979, um grupo de jovens cineastas se propôs a fazer um filme adulto na zona rural do Texas, mas quando seus solitários e idosos anfitriões os pegam em flagrante, o elenco se vê lutando por suas vidas.', 106, NULL, '/4BarWJRYFB5fN7LsJI9U2ul79hB.jpg', '/o375tDNib7tihlkWdtLW1fQhNL1.jpg', 6.7, 4249, 27.39, 'en', 61, 22, 60, 67, 36, 50, 40, 52, 50, 1, '2026-11-18 19:13:44'),
(158, 8966, 'filme', 'Crepúsculo', 'Twilight', 2008, 'Isabella Swan é uma adolescente que vai morar com seu pai em uma nova cidade depois que sua mãe decide casar-se novamente. No colégio, ela fica fascinada por Edward Cullen, um garoto que esconde um segredo obscuro. Eles se apaixonam, mas Edward sabe que quanto mais avançam no relacionamento, mais ele está colocando Bella e aqueles à sua volta em perigo.', 122, NULL, '/o4ki1gYHkP6IWNdwjHvI9vzfpuC.jpg', '/weAYfu6FfrNxEDJ3xH1XpgQcqUv.jpg', 6.3, 14877, 27.29, 'en', 51, 52, 86, 19, 50, 50, 48, 55, 83, 1, '2026-11-18 19:13:44'),
(159, 8871, 'filme', 'O Grinch', 'How the Grinch Stole Christmas', 2000, 'Um Grinch que odeia o Natal resolve criar um plano para impedir que os habitantes da pequena cidade de Quemlândia possam comemorar a data festiva. Para tanto, na véspera do grande dia, o Grinch resolve invadir as casas das pessoas e furtivamente roubar delas tudo o que esteja relacionado ao Natal.', 105, NULL, '/iVvFVBcdUMPgPCnLFICzBEwZxgZ.jpg', '/sy0vo1cmpKqwPRiMUiJ45jyLsX7.jpg', 6.8, 8594, 27.08, 'en', 53, 100, 92, 67, 80, 50, 76, 61, 83, 1, '2026-11-18 19:13:45'),
(160, 9479, 'filme', 'O Estranho Mundo de Jack', 'The Nightmare Before Christmas', 1993, 'Jack Skellington, o Rei das Abóboras, se cansa de fazer o Dia das Bruxas todos os anos e deixa os limites da cidade. Por acaso, acaba atravessando o portal do Natal, onde vê a alegria do espírito natalino. Ao retornar para a Cidade do Halloween, sem ter compreendido o que viu, ele começa a convencer os cidadãos a sequestrarem o Papai Noel e fazerem seu próprio Natal. Apesar de sua leal namorada Sally ser contra, o Papai Noel é capturado e os fatos mostrarão que Sally estava certa o tempo todo.', 76, NULL, '/g6zcll9bcAmoVNiMxt4wmVwTl5f.jpg', '/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', 7.9, 10953, 26.26, 'en', 72, 88, 100, 57, 72, 50, 93, 59, 83, 1, '2026-11-18 19:13:46');
INSERT INTO catalogo_obras (id, tmdb_id, tipo, titulo, titulo_original, ano, sinopse, duracao, temporadas, poster_path, backdrop_path, nota, votos, popularidade, idioma_original, eixo_1, eixo_2, eixo_3, eixo_4, eixo_5, eixo_6, eixo_7, eixo_8, confianca, ativo, atualizado_em) VALUES
(161, 240, 'filme', 'O Poderoso Chefão: Parte II', 'The Godfather Part II', 1974, 'Após a máfia matar sua família, o jovem Vito foge da sua cidade na Sicília e vai para a América. Vito luta para manter sua família. Ele mata Black Hand Fanucci, que exigia dos comerciantes uma parte dos seus ganhos. Com a morte de Fanucci, o poderio de Vito cresce, mas sua família é o que mais importa para ele. Agora baseado no Lago Tahoe, Michael planeja fazer incursões em Las Vegas e Havana instalando negócios ligados ao lazer, mas descobre que aliados como Hyman Roth estão tentando matá-lo.', 202, NULL, '/3ViYPhSAPwH2avQjdMl49F8PklB.jpg', '/pGzqRKrYeK4LogoysNro0vG8d8N.jpg', 8.6, 14634, 26.15, 'en', 48, 30, 42, 42, 16, 50, 38, 47, 67, 1, '2026-11-18 19:13:46'),
(162, 1061474, 'filme', 'Superman', 'Superman', 2025, 'Superman, um jovem repórter de Metrópolis, embarca em uma jornada para reconciliar sua herança kryptoniana com sua criação humana como Clark Kent.', 128, NULL, '/1ZLhjqbNgd0jzczAQtqMbwuMJKB.jpg', '/eGX66zonvc4bXg3rM08RUxdYSDx.jpg', 7.3, 5782, 26.14, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:13:47'),
(163, 617126, 'filme', 'Quarteto Fantástico: Primeiros Passos', 'The Fantastic 4: First Steps', 2025, 'No vibrante cenário de um mundo retrofuturista inspirado nos anos 1960, a Primeira Família da Marvel é forçada a equilibrar seus papéis como heróis com a força de seus laços familiares, enquanto defendem a Terra de um deus espacial voraz chamado Galactus e sua enigmática arauta, a Surfista Prateada.', 115, NULL, '/8F2vIxWycANHW763lnx2hJVtjDC.jpg', '/s94NjfKkcSczZ1FembwmQZwsuwY.jpg', 6.9, 4165, 26.05, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:13:48'),
(164, 569094, 'filme', 'Homem-Aranha: Através do Aranhaverso', 'Spider-Man: Across the Spider-Verse', 2023, 'Miles Morales retorna para o próximo capítulo da saga do Aranhaverso, uma aventura épica que transportará o Homem-Aranha em tempo integral e amigável do bairro do Brooklyn através do Multiverso para unir forças com Gwen Stacy e uma nova equipe de Homens-Aranha para enfrentar com um vilão mais poderoso do que qualquer coisa que eles já encontraram.', 140, NULL, '/fBS6y0LYX4kU6pPSBYMdQy6SIHX.jpg', '/kVd3a9YeLGkoeR50jGEXM6EqseS.jpg', 8.3, 9565, 25.89, 'en', 79, 80, 100, 100, 56, 58, 100, 94, 100, 1, '2026-11-18 19:13:48'),
(165, 807, 'filme', 'Seven - Os Sete Crimes Capitais', 'Se7en', 1995, 'Quando, a ponto de se aposentar, o detetive William Somerset aborda o último caso com a ajuda do recém-transferido David Mills, eles descobrem uma série de assassinatos. Logo percebem que estão lidando com um assassino que tem como alvo pessoas que ele acredita representar os sete pecados capitais.', 127, NULL, '/dZXYPSEaXCeigR2GEuZoukNmLTf.jpg', '/jwBs4djVIe9Kz3Vu9rsI9aEEKWU.jpg', 8.4, 24242, 25.82, 'en', 64, 40, 42, 93, 0, 86, 57, 49, 83, 1, '2026-11-18 19:13:49'),
(166, 324857, 'filme', 'Homem-Aranha: No Aranhaverso', 'Spider-Man: Into the Spider-Verse', 2018, 'Miles Morales é um jovem negro do Brooklyn que se tornou o Homem-Aranha inspirado no legado de Peter Parker, já falecido. Entretanto, ao visitar o túmulo de seu ídolo em uma noite chuvosa, ele é surpreendido com a presença do próprio Peter, vestindo o traje do herói aracnídeo sob um sobretudo. A surpresa fica ainda maior quando Miles descobre que ele veio de uma dimensão paralela, assim como outras variações do Homem-Aranha.', 117, NULL, '/ybQSBSrINtjWsJQ6Ih8sva8HlEZ.jpg', '/1ntePsIqeklfmrQJqZPncCydsqY.jpg', 8.4, 18270, 25.57, 'en', 79, 80, 100, 100, 56, 58, 100, 94, 100, 1, '2026-11-18 19:13:50'),
(167, 911430, 'filme', 'F1: O Filme', 'F1', 2025, 'Sonny Hayes, a lenda do automobilismo, é persuadido a deixar a aposentadoria para liderar uma equipe de Fórmula 1 em dificuldades—e ser mentor de um jovem piloto famoso—enquanto busca mais uma oportunidade de glória.', 155, NULL, '/fMcY5hpVZQ0cLKHvFM1mo6GrAr0.jpg', '/lkDYN0whyE82mcM20rwtwjbniKF.jpg', 7.8, 5018, 25.5, 'en', 47, 38, 58, 71, 50, 50, 64, 52, 67, 1, '2026-11-18 19:13:50'),
(168, 293167, 'filme', 'Kong: A Ilha da Caveira', 'Kong: Skull Island', 2017, 'Um ex-militar viaja com um grupo de desbravadores até a mítica Ilha da Caveira, onde seu irmão desapareceu enquanto procurava o Titan, soro que teria o poder de curar todas as doenças. Além de resgatar o irmão, o homem irá enfrentar as criaturas que habitam o local. A equipe de exploradores se aventura nas profundezas da ilha desconhecida no Pacífico, que é tão bonita quanto traiçoeira, sem saber que estão atravessando para o domínio do mítico Kong.', 118, NULL, '/y7ZdnfEA8AEyCFdojYBxeevtZtc.jpg', '/nVodCGKYLpqNC8YwQAbivKlWCgZ.jpg', 6.6, 11484, 25.49, 'en', 70, 76, 100, 100, 56, 50, 100, 70, 83, 1, '2026-11-18 19:13:51'),
(169, 19995, 'filme', 'Avatar', 'Avatar', 2009, 'Apesar de não ter mais os movimentos da perna, o ex-fuzileiro naval Jake Sully ainda sente que pode ser um guerreiro. Sua intuição começa a se tornar realidade quando ele viaja anos-luz até a estação espacial montada no Planeta Pandora. Habitado por grandes seres azuis, os Na´vi, o local tem uma atmosfera fatal para qualquer terrestre. Por isso, oficiais criaram o programa Avatar, em que um corpo biológico, híbrido de humano e Na´vi, pode ser comandado a distância.', 179, NULL, '/lRRMQhlOLM9xgvjKKFndOmptqKR.jpg', '/vL5LR6WdxWPjLPFRLe133jXWsh5.jpg', 7.6, 35049, 25.38, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:13:51'),
(170, 767, 'filme', 'Harry Potter e o Enigma do Príncipe', 'Harry Potter and the Half-Blood Prince', 2009, 'À medida que Lord Voldemort aumenta seu controle sobre o mundo Trouxa e bruxo, Hogwarts não é mais um local seguro. Harry suspeita que haja perigos dentro do castelo, mas Dumbledore está mais empenhado em prepará-lo para a batalha final que se aproxima rapidamente. Juntos, eles trabalham para encontrar a chave para desbloquear as defesas de Voldemort e, para esse fim, Dumbledore recruta seu velho amigo e colega Horácio Slughorn, que ele acredita possuir informações cruciais. Mesmo quando o confronto decisivo se aproxima, o romance floresce para Harry,…', 153, NULL, '/hTQQ5l9mxA3Rob8PTyvrNNGuj6y.jpg', '/ze6Mx4QE5mQVXRYmG2flncqqle4.jpg', 7.7, 21465, 25.15, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:52'),
(171, 1516698, 'filme', 'O Último Nascer do Sol', 'The Last Sunrise', 2026, 'Ry é uma estudante universitária que convive com uma doença crônica. Durante uma viagem de férias para a ilha de Maiorca com a sua mãe, Ry se apaixona inesperadamente por Julián. À medida que aprende a se entregar ao presente, o agravamento de sua condição de saúde e segredos familiares guardados há anos ameaçam desmoronar tudo antes que o verão chegue ao fim.', 107, NULL, '/aUP8lmnCvOUiG0n1ciXaeFEou3j.jpg', '/zFCWfU2ViMIm38G1W8UsnSpqmWn.jpg', 6.9, 247, 25.12, 'en', 47, 50, 50, 25, 50, 50, 32, 46, 67, 1, '2026-11-18 19:13:53'),
(172, 986056, 'filme', 'Thunderbolts*', 'Thunderbolts*', 2025, 'Depois de se verem presos em uma armadilha mortal, uma equipe não convencional de sete anti-heróis deve embarcar em uma missão perigosa que os forçará a confrontar os cantos mais sombrios de seus passados.', 126, NULL, '/zkysYSX51ddSPQuiDTjkGCS6vyh.jpg', '/rthMuZfFv4fqEU4JVbgSW9wQ8rs.jpg', 7.3, 4324, 25.11, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:13:53'),
(173, 12444, 'filme', 'Harry Potter e as Relíquias da Morte - Parte 1', 'Harry Potter and the Deathly Hallows: Part 1', 2010, 'Harry, Ron e Hermione estão determinados em sua missão de descobrir e acabar com o segredo da imortalidade e do poder de destruição de Voldemort – os Horcruxes. Fugitivos e sozinhos, os três amigos devem apenas contar uns com os outros, agora mas do que nunca... Mas as Forças das Trevas no caminho ameaçam separá-los para sempre.', 146, NULL, '/67FVFOTaeBUQnimhCWpUkDawDct.jpg', '/slW0M2G9txC0aUbftCTm1nYX1K8.jpg', 7.7, 21065, 25.06, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:54'),
(174, 105, 'filme', 'De Volta para o Futuro', 'Back to the Future', 1985, 'Marty McFly, um típico adolescente americano dos anos 80, acidentalmente é enviado de volta ao ano de 1955 em um carro modificado para ser uma máquino do tempo, inventada por um cientista louco. Durante sua fantástica e maluca viagem no tempo, McFly tem que fazer com que seus futuros pais se encontrem e se apaixonem, para que assim ele possa ir de volta para o futuro.', 115, NULL, '/i996T0lI1fGtFEowiH3V6eZthL0.jpg', '/5bzPWQ2dFUl2aZKkp7ILJVVkRed.jpg', 8.3, 22786, 25.03, 'en', 58, 92, 100, 85, 58, 58, 87, 91, 83, 1, '2026-11-18 19:13:55'),
(175, 12445, 'filme', 'Harry Potter e as Relíquias da Morte - Parte 2', 'Harry Potter and the Deathly Hallows: Part 2', 2011, 'No final épico, a batalha entre as forças do bem e do mal no mundo da bruxaria toma proporções de uma guerra mundial. As apostas nunca foram tão altas e ninguém está a salvo. Mas é harry que pode ser convocado para fazer um derradeiro sacrifício, à medida que ele se aproxima cada vez mais do confronto final com Lorde Voldemort. Tudo termina aqui.', 130, NULL, '/yD3VosOVW8WxPUzBDpEdzfv5pGx.jpg', '/cbcpDn6XJaIGoOil1bKuskU8ds4.jpg', 8.1, 22756, 25.03, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:55'),
(176, 1248832, 'filme', 'Digger', 'Digger', 2026, 'O homem mais poderoso do mundo embarca em uma missão frenética para provar que é o salvador da humanidade, antes que o desastre desencadeado por ele destrua tudo.', 129, NULL, '/2qelG58fO3tOSPrDVzOW8hfxY3V.jpg', '/4A3r1AjJg9Wa6ms3MGOScetCY0o.jpg', 7.5, 529, 25, 'en', 41, 60, 50, 49, 52, 50, 36, 52, 67, 1, '2026-11-18 19:13:56'),
(177, 1381078, 'filme', 'O Amor de Sua Vida', 'Love of Your Life', 2026, 'Maya, uma enfermeira inteligente e irônica, é envolvida por um amor envolvente, que coloca sua vida em uma trajetória que ela nunca teria imaginado.', 111, NULL, '/noVjD52nAvgPK2XtVZSej1nFzin.jpg', '/4hneB0UFKOZAGJHqJ3VhDcG72uH.jpg', 6.7, 239, 24.98, 'en', 47, 50, 50, 25, 50, 50, 32, 46, 67, 1, '2026-11-18 19:13:56'),
(178, 862, 'filme', 'Toy Story: Um Mundo de Aventuras', 'Toy Story', 1995, 'Buzz Lightyear é o novo e sofisticado astronauta de brinquedo do garoto Andy. Buzz não imaginava que encontraria um rival: Woody, um cowboy de brinquedo que, dominado pelo ciúme, acredita ter perdido um lugar precioso no coração do seu dono. Os dois brinquedos vivem brigando até que vão parar nas garras do vizinho, um verdadeiro destruidor de brinquedos. Agora, mais do que nunca, Buzz e Woody precisam precisam se unir para escapar do perigo. Com a ajuda de seus amigos da caixa de brinquedos, eles vão viver uma incrível aventura.', 81, NULL, '/686F0CEPmI4ZXjFbWtIHQOBwnfI.jpg', '/8AqWECiUHnz1Crj69uB9vhiK9Le.jpg', 8, 20844, 24.65, 'en', 58, 100, 100, 85, 80, 50, 83, 57, 100, 1, '2026-11-18 19:13:57'),
(179, 675, 'filme', 'Harry Potter e a Ordem da Fênix', 'Harry Potter and the Order of the Phoenix', 2007, 'Lord Voldemort está de volta, mas o Ministério da Magia está fazendo tudo a seu alcance para impedir que a comunidade mundial de bruxos descubra isso – incluindo indicar a oficial do Ministério, Dolores Umbridge, como a nova professora de Defesa Contra as Artes das Trevas de Hogwarts. Quando Umbridge se recusa a ensinar a prática de mágica defensiva, Rony e Hermione convencem Harry a secretamente treinar um grupo de estudantes para a guerra de magia que está prestes a estourar.', 138, NULL, '/tIf9aUyNljda9MG1pjlOLHCZ3b0.jpg', '/pkxPkHOPJjOvzfQOclANEBT8OfK.jpg', 7.7, 21506, 24.64, 'en', 55, 64, 100, 69, 50, 50, 94, 69, 67, 1, '2026-11-18 19:13:58'),
(180, 1368166, 'filme', 'A Empregada', 'The Housemaid', 2025, 'Millie é uma mulher passando por dificuldades que se sente aliviada com a chance de um novo começo como empregada doméstica de Nina e Andrew, um casal rico. Logo, ela descobre que os segredos da família são muito mais perigosos do que os seus.', 131, NULL, '/qaqAdyuk8Fcgfsj19Cj3OpJ8hN.jpg', '/zTnAnYIn0Iv3cn0ZHlzLhou3ybm.jpg', 7.2, 3375, 24.64, 'en', 61, 40, 50, 87, 22, 86, 64, 52, 67, 1, '2026-11-18 19:13:58'),
(181, 803796, 'filme', 'Guerreiras do K-Pop', 'KPop Demon Hunters', 2025, 'Quando não estão lotando estádios, as estrelas do K-pop Rumi, Mira e Zoey usam seus poderes secretos para proteger os fãs contra ameaças sobrenaturais.', 95, NULL, '/gbdMa7woiuF7IiEB5Spwv5od4oo.jpg', '/w3Bi0wygeFQctn6AqFTwhGNXRwL.jpg', 8, 3373, 24.53, 'en', 75, 100, 100, 79, 58, 50, 84, 62, 100, 1, '2026-11-18 19:13:59'),
(182, 1290821, 'filme', 'Missão Refúgio', 'Shelter', 2026, 'Um ex-assassino de aluguel, agora um homem recluso numa ilha costeira remota, salva uma garota de uma tempestade terrível, colocando os dois na mira do perigo. Forçado a sair da aposentadoria e do isolamento, o homem é obrigado a enfrentar seu passado perigoso para proteger a menina enquanto tenta sobreviver uma jornada tensa repleta de perigos e redenção.', 107, NULL, '/hSvhZRkbYD9crC4nqy8uCk9EdFH.jpg', '/nHxWyy18SvAZ8jJeemtS8k1UNjM.jpg', 7.7, 2041, 24.42, 'en', 55, 48, 50, 100, 12, 62, 74, 52, 83, 1, '2026-11-18 19:13:59'),
(183, 373571, 'filme', 'Godzilla II: Rei dos Monstros', 'Godzilla: King of the Monsters', 2019, 'Membros da agência Monarch enfrentam monstros gigantescos, incluindo o poderoso Godzilla, que entra em choque com Mothra, Rodan e seu maior inimigo, King Ghidorah, o monstro de três cabeças. Essas antigas superespécies disputam a supremacia, deixando a própria existência da humanidade em risco.', 132, NULL, '/2umU3r6V4V2gTmSnZJmH61nTorF.jpg', '/mzRJpkWPjXdXak0WCc8ZxVH4hug.jpg', 6.7, 7026, 24.39, 'en', 76, 58, 97, 88, 56, 58, 95, 86, 67, 1, '2026-11-18 19:14:00'),
(184, 22, 'filme', 'Piratas do Caribe: A Maldição do Pérola Negra', 'Pirates of the Caribbean: The Curse of the Black Pearl', 2003, 'O pirata Jack Sparrow tem seu navio saqueado e roubado pelo capitão Barbossa e sua tripulação. Com o navio de Sparrow, Barbossa invade a cidade de Port Royal, levando consigo Elizabeth Swann, filha do governador. Para recuperar sua embarcação, Sparrow recebe a ajuda de Will Turner, um grande amigo de Elizabeth. Eles desbravam os mares em direção à misteriosa Ilha da Morte, tentando impedir que os piratas-esqueleto derramem o sangue de Elizabeth para desfazer a maldição que os assola.', 143, NULL, '/qlwCuP4QC79QV5pjOI08Z7KAYxP.jpg', '/uRNgkJSkNBFbbn9fPsEjDIy8Sh3.jpg', 7.8, 23120, 24.34, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:14:01'),
(185, 823464, 'filme', 'Godzilla e Kong: O Novo Império', 'Godzilla x Kong: The New Empire', 2024, 'O poderoso Kong e o temível Godzilla se unem contra uma colossal ameaça mortal escondida no mundo dos humanos, que ameaça a existência de sua espécie e da nossa. Mergulhando profundamente nos mistérios da Ilha da Caveira e nas origens da Terra Oca, o filme irá explorar a antiga batalha de Titãs que ajudou a forjar esses seres extraordinários e os ligou à humanidade para sempre.', 115, NULL, '/fWSGD2yrzz6hscocnMD8AEXIThk.jpg', '/gvLG3Fnznkxl4SmYfcK8gUuqxM8.jpg', 7, 4977, 24.3, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:01'),
(186, 106646, 'filme', 'O Lobo de Wall Street', 'The Wolf of Wall Street', 2013, 'Durante seis meses, Jordan Belfort trabalhou duro em uma corretora de Wall Street, seguindo os ensinamentos de seu mentor Mark Hanna. Quando finalmente consegue ser contratado como corretor da firma, acontece o Black Monday, que faz com que as bolsas de vários países caiam repentinamente. Sem emprego e bastante ambicioso, ele acaba trabalhando para uma empresa de fundo de quintal que lida com papéis de baixo valor, que não estão na bolsa de valores. É lá que Belfort tem a idéia de montar uma empresa focada neste tipo de negócio, cujas vendas são de…', 180, NULL, '/xfbnEVFKS26YHLuuckP0i58GPlo.jpg', '/7Nwnmyzrtd0FkcRyPqmdzTPppQa.jpg', 8, 26959, 24, 'en', 45, 60, 42, 55, 24, 50, 28, 51, 83, 1, '2026-11-18 19:14:02'),
(187, 1228710, 'filme', 'Star Wars: O Mandaloriano e Grogu', 'The Mandalorian and Grogu', 2026, 'O maligno Império caiu e os senhores da guerra Imperiais ainda estão espalhados pela galáxia. Enquanto a jovem Nova República luta para proteger tudo pelo que a Rebelião batalhou, ela conta com a ajuda do lendário caçador de recompensas Mandaloriano Din Djarin e seu jovem aprendiz Grogu.', 132, NULL, '/dNwaS0tnwgQRaQFPY5MbGxdmYXr.jpg', '/ysLlsAxwgNSxBWHCgTKJrmjxpRQ.jpg', 7.5, 2005, 23.95, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:02'),
(188, 98, 'filme', 'Gladiador', 'Gladiator', 2000, 'Nos dias finais do reinado de Marcus Aurelius, o imperador desperta a ira de seu filho Commodus ao tornar pública sua predileção em deixar o trono para Maximus, o comandante do exército romano. Sedento pelo poder, Commodus mata seu pai, assume a coroa e ordena a morte de Maximus, que consegue fugir antes de ser pego e passa a se esconder sob a identidade de um escravo e gladiador do Império Romano.', 155, NULL, '/4DUClyGA6OqjXv6yC0Imf6THGfp.jpg', '/Ar7QuJ7sJEiC0oP3I8fKBKIQD9u.jpg', 8.2, 21888, 23.92, 'en', 43, 46, 76, 83, 50, 50, 80, 59, 83, 1, '2026-11-18 19:14:03'),
(189, 497, 'filme', 'À Espera de um Milagre', 'The Green Mile', 1999, 'Milagres acontecem em lugares inesperados, mesmo no bloco de celas para o corredor da morte na Penitenciária Cold Mountain. Lá, John Coffey, um gentil e gigante prisioneiro com poderes sobrenaturais, traz um senso de espírito e humanidade aos seus guardas e colegas de cela.', 189, NULL, '/etnQFCNnTbXAi1wWB6WCWWzetjL.jpg', '/amZavErrjrdgDwhsIdpWxHNenIx.jpg', 8.5, 20152, 23.91, 'en', 58, 36, 78, 45, 16, 50, 61, 59, 83, 1, '2026-11-18 19:14:04'),
(190, 315635, 'filme', 'Homem-Aranha: De Volta ao Lar', 'Spider-Man: Homecoming', 2017, 'Depois de atuar ao lado dos Vingadores, chegou a hora de Peter Parker voltar para casa e para a sua vida, já não mais tão normal.', 133, NULL, '/1nkwRL17cAGO8A1yu3miRBdvOsl.jpg', '/lAsr1ytUq0ATWdCbcjf59pupPFy.jpg', 7.3, 24267, 23.78, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:04'),
(191, 424, 'filme', 'A Lista de Schindler', 'Schindler\'s List', 1993, 'O alemão Oskar Schindler viu na mão de obra judia uma solução barata e viável para lucrar com negócios durante a guerra. Com sua forte influência dentro do partido nazista, foi fácil conseguir as autorizações e abrir uma fábrica. O que poderia parecer uma atitude de um homem não muito bondoso, transformou-se em um dos maiores casos de amor à vida da História, pois este alemão abdicou de toda sua fortuna para salvar a vida de mais de mil judeus em plena luta contra o extermínio alemão.', 195, NULL, '/lfJAj9OGsiSsbFxouRkGKqibHxf.jpg', '/zb6fM1CX41D9rF9hdgclu0peUmy.jpg', 8.6, 18202, 23.68, 'en', 38, 6, 50, 33, 54, 50, 89, 5, 83, 1, '2026-11-18 19:14:05'),
(192, 1022789, 'filme', 'Divertida Mente 2', 'Inside Out 2', 2024, '\"Divertida Mente 2\", da Disney e da Pixar, retorna à mente da adolescente Riley, e o faz no momento em que a sala de comando está passando por uma demolição repentina para dar lugar a algo totalmente inesperado: novas emoções! Alegria, Tristeza, Raiva, Medo e Nojinho não sabem bem como reagir quando Ansiedade aparece, e tudo indica que ela não está sozinha.', 100, NULL, '/lHKNS35r4RTa9GO72vdadMLxoiV.jpg', '/p5ozvmdgsmbWe0H8Xk7Rc8SCwAB.jpg', 7.5, 7176, 23.57, 'en', 59, 100, 100, 85, 80, 50, 82, 60, 100, 1, '2026-11-18 19:14:06'),
(193, 454639, 'filme', 'Mestres do Universo', 'Masters of the Universe', 2026, 'Adam caiu na Terra quando era criança e perdeu a espada mágica que o ligava a Eternia. Quase 20 anos depois, ele a recupera e retorna ao seu planeta natal para protegê-lo do malvado Esqueleto, mas primeiro precisa desvendar seu passado.', 133, NULL, '/atpb7NKSyM4bJSUY8vQTunzK4Na.jpg', '/5MUMB3aPEPEQPCIAaygXFUTWE9Y.jpg', 7.1, 2366, 23.52, 'en', 73, 64, 100, 89, 56, 58, 100, 96, 83, 1, '2026-11-18 19:14:06'),
(194, 1234821, 'filme', 'Jurassic World: Recomeço', 'Jurassic World Rebirth', 2025, 'Cinco anos após os eventos de Jurassic World: Domínio, a ecologia do planeta se mostrou inóspita para os dinossauros, com os poucos sobreviventes vivendo isolados nas regiões equatoriais. Zora Bennett é contratada para liderar uma equipe de especialistas cujo objetivo é obter o material genético das três maiores criaturas, cujo DNA contém a chave para a criação de um medicamento que trará grandes benefícios à humanidade. Mas a operação se cruzará com uma família cujo barco virou, e todos acabarão em uma ilha proibida, ocupada por dinossauros de inúmeras…', 134, NULL, '/zuEC2i3I2P7QIcLoUJNBwqRYO4S.jpg', '/zNriRTr0kWwyaXPzdg1EIxf0BWk.jpg', 6.2, 3960, 23.33, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:07'),
(195, 843352, 'filme', 'Legend of the White Dragon', 'Legend of the White Dragon', 2026, 'Após três anos de esconderijo forçado como fugitivo, Erik Reed —um ex-super-herói conhecido como Dragão Branco— retorna à cidade que jurou proteger. Seu objetivo: limpar seu nome e se reunir com a família que ele mantém em segredo. Apenas uma coisa está em seu caminho: o misterioso Dragon Prime, que não medirá esforços para se vingar do Dragão Branco.', 97, NULL, '/k0L5ZQP4PjdNziVGvcOeaihXyCc.jpg', '/iBfpVJCn2nKSkuWjv1Wp4GTiqoG.jpg', 6.7, 89, 23.32, 'en', 73, 64, 100, 89, 56, 58, 100, 96, 83, 1, '2026-11-18 19:14:07'),
(196, 447365, 'filme', 'Guardiões da Galáxia: Vol. 3', 'Guardians of the Galaxy Vol. 3', 2023, 'Peter Quill, que ainda está se recuperando da perda de Gamora, tem que reunir a sua equipe para defender o universo e proteger um dos seus. Uma missão que, se não for concluída com sucesso, pode levar ao fim dos Guardiões como os conhecemos.', 150, NULL, '/4yycSPnchdNAZirGkmCYQwTd3cr.jpg', '/5YZbUmjbMa3ClvSW1Wj3D6XGolb.jpg', 7.9, 9127, 23.32, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:08'),
(197, 808, 'filme', 'Shrek', 'Shrek', 2001, 'Em um pântano distante vive Shrek, um ogro solitário que vê, sem mais nem menos, sua vida ser invadida por uma série de personagens de contos de fada. Todos eles foram expulsos de suas casas pelo maligno Lorde Farquaad. Determinado a recuperar a tranquilidade, Shrek faz um acordo com Farquaad: todos os personagens poderão retornar aos seus lares se ele e seu amigo Burro resgatarem uma princesa que foi aprisionada por um dragão.', 90, NULL, '/wxeqfC221YMptRRdzxlijAh7q8l.jpg', '/2Biv1mSzaaxWOqvcnDZn4GcYEAb.jpg', 7.8, 19608, 23.17, 'en', 67, 100, 100, 85, 80, 50, 100, 69, 100, 1, '2026-11-18 19:14:11'),
(198, 2062, 'filme', 'Ratatouille', 'Ratatouille', 2007, 'Remy, morador de Paris, aprecia boa comida e tem um paladar bastante sofisticado. Ele adoraria se tornar um chef para poder criar e desfrutar de obras-primas culinárias para o deleite de seu coração. O único problema é que Remy é um rato. Quando acaba no esgoto debaixo de um dos melhores restaurantes de Paris, o roedor gourmet encontra-se na posição ideal para realizar o seu sonho.', 110, NULL, '/41Co0TRUJNyvjr2vHBEcAKAEFpX.jpg', '/zeoaHdXRDd5IoUiMVsNhwTZm78B.jpg', 7.9, 19232, 23.04, 'en', 67, 100, 100, 67, 80, 50, 82, 61, 100, 1, '2026-11-18 19:14:12'),
(199, 1233413, 'filme', 'Pecadores', 'Sinners', 2025, 'Dispostos a deixar suas vidas conturbadas para trás, irmãos gêmeos retornam à sua cidade natal para recomeçar suas vidas do zero, quando descobrem que um mal ainda maior está à espera deles para recebê-los de volta.', 138, NULL, '/v0Ljeti537c6cNKweuEN0iaU3x4.jpg', '/j7KqDRzjbvIjDv7cdHz9G3ZYEQy.jpg', 7.5, 5577, 22.94, 'en', 61, 20, 68, 100, 26, 62, 66, 52, 83, 1, '2026-11-18 19:14:12'),
(200, 786892, 'filme', 'Furiosa: Uma Saga Mad Max', 'Furiosa: A Mad Max Saga', 2024, 'Quando o mundo entra em colapso, a jovem Furiosa é sequestrada do Green Place das Muitas Mães e cai nas mãos da horda de motoqueiros liderada pelo Senhor da Guerra Dementus. Vagando pelo deserto condenado, eles encontram a Cidadela controlada por Immortan Joe. Enquanto os dois tiranos lutam por poder e controle, Furiosa terá que sobreviver a muitos desafios para encontrar e trilhar o caminho de volta para casa.', 148, NULL, '/7qOSKoOAPgemYhBwbJgBWcCxPWZ.jpg', '/raph7qjAGTMXaIjVxt6ZDSXRzUr.jpg', 7.4, 5397, 22.93, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:13'),
(201, 11036, 'filme', 'Diário de uma Paixão', 'The Notebook', 2004, 'Na década de 40, o operário Noah Calhoun e a rica Allie estão desesperadamente apaixonados, mas os pais da jovem não aprovam o namoro. Quando Noah vai para a Segunda Guerra Mundial, parece ser o fim do romance. Enquanto isso, Allie se envolve com outro homem. Mas quando Noah retorna para a pequena cidade anos mais tarde, próximo ao casamento de Allie, logo se torna claro que a paixão ainda não acabou.', 123, NULL, '/hO6k34ZNDwWzgcnzFbqYf2Rjg5W.jpg', '/zdXnJqBaGFVtLoPNuMeKfEYUViZ.jpg', 7.9, 13064, 22.92, 'en', 47, 50, 50, 25, 50, 50, 32, 45, 67, 1, '2026-11-18 19:14:13'),
(202, 198663, 'filme', 'Maze Runner: Correr ou Morrer', 'The Maze Runner', 2014, 'Num cenário pós-apocalíptico, uma comunidade de rapazes descobre que estão presos num labirinto misterioso. Juntos, terão de descobrir como escapar, resolver o enigma e revelar o arrepiante segredo acerca de quem os colocou ali e por que razão.', 113, NULL, '/efAJzIyjYlgdO7fzfMBJcFZqI5v.jpg', '/eTlcNXGv32zkVI7ZDHhfeaKHXKQ.jpg', 7.2, 18671, 22.54, 'en', 75, 48, 92, 100, 28, 94, 100, 85, 100, 1, '2026-11-18 19:14:14'),
(203, 360920, 'filme', 'O Grinch', 'The Grinch', 2018, 'O Grinch é um ser verde que não suporta o Natal e, todo ano, precisa impedir que os habitantes da cidade vizinha de Quemlândia comemorem a data. Decidido a acabar com a festa, ele resolve invadir os lares dos vizinhos e roubar tudo o que está relacionado ao Natal.', 85, NULL, '/hGnQmQARgtXtoesIGAsmmTbMKfH.jpg', '/5lWIYxYEqWi8j3ZloxXntw3ImBo.jpg', 6.9, 4583, 22.53, 'en', 67, 100, 100, 67, 80, 50, 82, 62, 100, 1, '2026-11-18 19:14:15'),
(204, 10138, 'filme', 'Homem de Ferro 2', 'Iron Man 2', 2010, 'Em um mundo ciente da existência do Homem de Ferro, o inventor bilionário Tony Stark sofre pressão de todos os lados para compartilhar sua tecnologia com as forças armadas. Ele resiste para divulgar os segredos de sua inigualável armadura, com medo de que estas informações caiam nas mãos erradas.', 124, NULL, '/vzROjQbgKWMVf2EldXipCcjpuBL.jpg', '/7lmBufEG7P7Y1HClYK3gCxYrkgS.jpg', 6.9, 23253, 22.52, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:14:15'),
(205, 348, 'filme', 'Alien: O Oitavo Passageiro', 'Alien', 1979, 'Quando a tripulação da sonda espacial Nostromo responde a um pedido de socorro vindo de um planeta inóspito, eles descobrem uma forma de vida mortal que se reproduz dentro de humanos. Agora, a tripulação deve lutar para permanecer viva e impedir que a criatura chegue até a Terra.', 117, NULL, '/rFHzJrkO1kNIezb6rFog5oCJUEn.jpg', '/AmR3JG1VQVxU8TfAvljUhfSFUOx.jpg', 8.2, 17160, 22.48, 'en', 72, 22, 94, 64, 36, 58, 58, 81, 67, 1, '2026-11-18 19:14:16'),
(206, 271110, 'filme', 'Capitão América: Guerra Civil', 'Captain America: Civil War', 2016, 'Depois do ataque de Ultron, os políticos decidem controlar os Vingadores, já que suas ações afetam toda a humanidade. A decisão coloca o Capitão América em rota de colisão com o Homem de Ferro.', 137, NULL, '/dsvUR5aEVSkB1Sro7nT6Khqik71.jpg', '/7FWlcZq3r6525LWOcvO9kNWurN1.jpg', 7.5, 24877, 22.47, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:17'),
(207, 389, 'filme', '12 Homens e uma Sentença', '12 Angry Men', 1957, 'Um jovem porto-riquenho é acusado do brutal crime de ter matado o próprio pai. Quando ele vai a julgamento, doze jurados se reúnem para decidir a sentença, levando em conta que o réu deve ser considerado inocente até que se prove o contrário. Onze dos jurados têm plena certeza de que ele é culpado, e votam pela condenação, mas um jurado acha que é melhor investigar mais para que a sentença seja correta. Para isso ele terá que enfrentar diferentes interpretações dos fatos, e a má vontade dos outros jurados, que só querem ir logo para suas casas.', 96, NULL, '/aiHIhV8c45FzIlbqYlswrrNyQD6.jpg', '/qqHQsStV6exghCM7zbObuYBiYxw.jpg', 8.6, 10608, 22.45, 'en', 43, 30, 50, 35, 46, 50, 48, 45, 50, 1, '2026-11-18 19:14:17'),
(208, 977942, 'filme', 'O Rebelde', 'The Uprising', 2026, 'Enquanto a guerra e a peste devastam a Inglaterra do século XIV, um humilde camponês dá início a uma revolta, reunindo um exército de homens e mulheres do povo para desafiar o poder do rei numa luta desesperada por justiça e sobrevivência.', 127, NULL, '/kvE28LKAjRlkf2x3G6BmSCYyOk7.jpg', '/kAlAFblqBI6aGXItR4DRpT5Tozg.jpg', 7.7, 428, 22.39, 'en', 44, 31, 58, 53, 46, 50, 74, 20, 83, 1, '2026-11-18 19:14:18'),
(209, 124905, 'filme', 'Godzilla', 'Godzilla', 2014, 'Joe Brody criou o filho sozinho após a morte da esposa em um acidente na usina nuclear em que ambos trabalhavam, no Japão. Ele nunca aceitou a catástrofe e quinze anos depois continua remoendo o acontecido, tentando encontrar alguma explicação. Ford Brody, agora adulto, é soldado do exército americano e precisa lutar desesperadamente para salvar a população mundial e em especial sua família do gigantesco, inabalável e incrivelmente assustador monstro Godzilla.', 123, NULL, '/9dyFXQwmFHI1gMn2JEczgKD1hwO.jpg', '/6CLNOzMXO9bvapDD8gsdwkJU4wN.jpg', 6.4, 10162, 22.38, 'en', 61, 38, 92, 71, 50, 58, 82, 85, 83, 1, '2026-11-18 19:14:18'),
(210, 3933, 'filme', 'A Noiva Cadáver', 'Corpse Bride', 2005, 'As famílias de Victor e Victoria estão arranjando seu casamento. Nervoso com a cerimônia, Victor vai sozinho à floresta para ensaiar seus votos. No entanto, o que ele pensava ser um tronco de árvore na verdade é o braço esquelético de Emily, uma noiva que foi assassinada depois de fugir com seu amor. Convencida que Victor acabara de lhe pedir a mão em casamento, Emily o leva para o mundo dos mortos, mas ele precisa retornar rapidamente antes que Victoria se case com o malvado Lorde Barkis.', 77, NULL, '/nT7W8LfhzVybfFsnQJ4qQfqn5KX.jpg', '/v23fWgJUEt8EMmvn19btIacxP8E.jpg', 7.6, 10680, 22.34, 'en', 69, 82, 100, 37, 56, 50, 64, 55, 83, 1, '2026-11-18 19:14:19'),
(211, 1032863, 'filme', 'A Hipótese do Amor', 'The Love Hypothesis', 2026, 'Olive é uma brilhante candidata ao doutorado focada em seu futuro no meio acadêmico. Mas quando ela percebe que sua melhor amiga Ahn se apaixonou por seu crush Jeremy, Olive impulsivamente beija o intimidador professor Adam Carlsen para provar que ela superou a paixonite. O que começa como um ato desesperado de amizade se transforma em um relacionamento falso com regras, limites e um acordo mutuamente benéfico. Quando o arranjo deles começa a confundir as linhas entre encenação e realidade, Olive é forçada a testar sua hipótese mais assustadora até…', 112, NULL, '/9TQyjZ9PHCiPR8eylF8dulUFreu.jpg', '/o7Oy9Gbx1CCyaweL8xUhtMW4Puq.jpg', 7.8, 752, 22.29, 'en', 45, 100, 50, 53, 64, 50, 32, 46, 67, 1, '2026-11-18 19:14:20'),
(212, 1477712, 'filme', 'O Sorveteiro', 'Ice Cream Man', 2026, 'Um sorveteiro misterioso distribui um doce amaldiçoado que transforma crianças em assassinas, sedentas por sangue e sem piedade com os adultos. Enquanto o massacre toma conta das ruas, três jovens que escaparam por pouco da maldição correm contra o tempo para descobrir a origem desse homem e impedir que a matança se espalhe, antes que não sobre ninguém vivo.', 86, NULL, '/8bUXuKrdYQFMdx7ogoN0f5cm8iq.jpg', '/3DV7c9FoogMORFGUFDbTcCtzxOr.jpg', 5.3, 341, 22.29, 'en', 55, 42, 60, 100, 28, 62, 38, 52, 83, 1, '2026-11-18 19:14:20'),
(213, 280, 'filme', 'O Exterminador do Futuro 2: O Julgamento Final', 'Terminator 2: Judgment Day', 1991, 'O jovem John Connor é a chave para a vitória da civilização sobre uma rebelião de robôs do futuro. No entanto, ele torna-se alvo de T-1000, um exterminador que pode assumir a forma que desejar e que foi enviado do futuro para matá-lo. Outro exterminador, o renovado T-800, também é enviado de volta ao passado para proteger o garoto. Quando John e sua mãe embarcam na fuga com T-800, o menino cria um vínculo forte e inesperado com o robô.', 136, NULL, '/eTIY2LO5cDclxgKtCHuvIKdF3c3.jpg', '/izkMjmhauFx9DjoBQqM5sM5WAwE.jpg', 8.2, 15206, 22.24, 'en', 70, 41, 92, 95, 40, 70, 91, 83, 83, 1, '2026-11-18 19:14:21'),
(214, 475557, 'filme', 'Coringa', 'Joker', 2019, 'Isolado, intimidado e desconsiderado pela sociedade, o fracassado comediante Arthur Fleck inicia seu caminho como uma mente criminosa após assassinar três homens em pleno metrô. Sua ação inicia um movimento popular contra a elite de Gotham City, da qual Thomas Wayne é seu maior representante.', 122, NULL, '/xLxgVxFWvb9hhUyCDDXxRPPnFck.jpg', '/rlay2M5QYvi6igbGcFjq8jxeusY.jpg', 8.1, 28722, 22.23, 'en', 51, 20, 42, 69, 0, 62, 46, 52, 83, 1, '2026-11-18 19:14:22'),
(215, 1314481, 'filme', 'O Diabo Veste Prada 2', 'The Devil Wears Prada 2', 2026, 'Miranda Priestly navega por sua carreira em meio ao declínio das publicações tradicionais de revistas. Ela se confronta com Emily Charlton, sua ex-assistente, agora uma influente executiva de um grupo de luxo, que detém verbas publicitárias de que Miranda Priestly precisa desesperadamente.', 119, NULL, '/50yWyY981TyUHhoxxSEKwO70FmQ.jpg', '/dRoFlUbH1l51ACmx5oPCI3jfvZq.jpg', 7, 2569, 22.21, 'en', 41, 60, 50, 49, 52, 50, 36, 52, 67, 1, '2026-11-18 19:14:22'),
(216, 502356, 'filme', 'Super Mario Bros. O Filme', 'The Super Mario Bros. Movie', 2023, 'Transportados do Brooklyn para o Reino Cogumelo num passe de mágica, dois corajosos encanadores conhecem uma princesa e combatem um tirano que cospe fogo.', 92, NULL, '/ij8sapIEbLf2g8npOu6XgsQS2w0.jpg', '/9n2tJBplPbgR2ca05hS5CKXwP2c.jpg', 7.6, 11337, 22.09, 'en', 75, 100, 100, 70, 80, 50, 91, 67, 100, 1, '2026-11-18 19:14:23'),
(217, 8587, 'filme', 'O Rei Leão', 'The Lion King', 1994, 'Mufasa, o Rei Leão, e a rainha Sarabi apresentam ao reino o herdeiro do trono, Simba. O recém-nascido recebe a bênção do sábio babuíno Rafiki, mas ao crescer é envolvido nas artimanhas de seu tio Scar, o invejoso e maquiavélico irmão de Mufasa, que planeja livrar-se do sobrinho e herdar o trono.', 89, NULL, '/8aIvm8OaJISOpVTt7rMIh7X35G5.jpg', '/wXsQvli6tWqja51pYxXNG1LFIGV.jpg', 8.3, 20427, 21.76, 'en', 60, 62, 82, 39, 66, 50, 61, 49, 83, 1, '2026-11-18 19:14:23'),
(218, 269149, 'filme', 'Zootopia: Essa Cidade é o Bicho', 'Zootopia', 2016, 'Em uma cidade de animais antropomórficos, uma raposa fugitiva vigarista e um coelho policial recruta precisam trabalhar juntos para desvendar uma conspiração.', 108, NULL, '/27Ko4be7CeFmq2hVN7lp7TWG1sd.jpg', '/9tOkjBEiiGcaClgJFtwocStZvIT.jpg', 7.8, 18749, 21.64, 'en', 59, 100, 100, 85, 80, 50, 82, 60, 100, 1, '2026-11-18 19:14:24'),
(219, 1212763, 'filme', 'A Morte do Demônio: Em Chamas', 'Evil Dead Burn', 2026, 'Após a perda do marido, uma mulher busca consolo com seus sogros em sua casa isolada. À medida que, um a um, eles são transformados em Deadites — transformando o encontro em uma reunião familiar infernal —, ela descobre que os votos que fez em vida... continuam vivos mesmo após a morte.', 117, NULL, '/fteLdvfRnltfLjAEnsl5E3vImnW.jpg', '/o0jkkpcN81QqSl8DMLScBCXyUH9.jpg', 7.6, 1966, 21.61, 'en', 61, 22, 60, 67, 36, 50, 40, 52, 50, 1, '2026-11-18 19:14:25'),
(220, 216015, 'filme', 'Cinquenta Tons de Cinza', 'Fifty Shades of Grey', 2015, 'Anastasia Steele (Dakota Johnson) é uma estudante de literatura de 21 anos, recatada e virgem. Uma dia ela deve entrevistar para o jornal da faculdade o poderoso magnata Christian Grey (Jamie Dornan). Nasce uma complexa relação entre ambos: com a descoberta amorosa e sexual, Anastasia conhece os prazeres do sadomasoquismo, tornando-se o objeto de submissão do sádico Grey.', 125, NULL, '/fAfsfaRyQV5LKNvYoqlav0Gr3uC.jpg', '/7IGKrY1f1KfwMipx9wZC4NRgIdF.jpg', 5.9, 12640, 21.55, 'en', 47, 40, 50, 49, 34, 62, 40, 46, 83, 1, '2026-11-18 19:14:25'),
(221, 76600, 'filme', 'Avatar: O Caminho da Água', 'Avatar: The Way of Water', 2022, '12 anos depois de explorar Pandora e se juntar aos Na\'vi, Jake Sully formou uma família com Neytiri e se estabeleceu entre os clãs do novo mundo. Porém, a paz não durará para sempre.', 192, NULL, '/hm6nONQOgVpKmRK5YUX9EqfJ0NH.jpg', '/kJsPVzdyBrYHLomuNv5SJDXUQ2f.jpg', 7.6, 14903, 21.53, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:26'),
(222, 769, 'filme', 'Os Bons Companheiros', 'GoodFellas', 1990, 'A história real de Henry Hill, um garoto meio irlandês e meio siciliano do Brooklyn que é adotado por gangsters do bairro ainda jovem e sobe na hierarquia de uma família da máfia sob a orientação de Jimmy Conway.', 146, NULL, '/sTReXuaND1AjkXUfjl1gqRcuGfI.jpg', '/6qgSKYgkHLL0vAVbsqRfo8KmZgL.jpg', 8.5, 15047, 21.45, 'en', 50, 30, 42, 45, 16, 50, 39, 49, 67, 1, '2026-11-18 19:14:27'),
(223, 150540, 'filme', 'Divertida Mente', 'Inside Out', 2015, 'Quando Riley, de 11 anos, se muda para uma nova cidade, suas Emoções - Alegria, Medo, Raiva, Nojinho e Tristeza trabalham juntas para ajudá-la na transição. Porém, uma série de eventos faz com que Alegria e Tristeza se envolvam em uma perigosa aventura que virará o mundo de Riley de cabeça para baixo.', 95, NULL, '/62SAZfLfzhxJWUFJvfIPMw6QUpE.jpg', '/jJKZaTBNenlFclQyjrnvzkRmvWE.jpg', 7.9, 24184, 21.37, 'en', 55, 100, 100, 67, 74, 50, 72, 60, 100, 1, '2026-11-18 19:14:27'),
(224, 603692, 'filme', 'John Wick 4: Baba Yaga', 'John Wick: Chapter 4', 2023, 'Com o preço por sua cabeça cada vez maior, John Wick leva sua luta contra a alta mesa global enquanto procura os jogadores mais poderosos do submundo, de Nova York a Paris, de Osaka a Berlim.', 169, NULL, '/rXTqhpkpj6E0YilQ49PK1SSqLhm.jpg', '/7I6VUdPj6tQECNHdviJkUHD2u89.jpg', 7.7, 8546, 21.28, 'en', 60, 41, 50, 100, 8, 62, 68, 52, 83, 1, '2026-11-18 19:14:28'),
(225, 11324, 'filme', 'Ilha do Medo', 'Shutter Island', 2010, 'No verão de 1954, os agentes judiciais Teddy Daniels (DiCaprio) e Chuck Aule (Ruffalo) foram designados para uma ilha remota do porto de Boston para investigar o desaparecimento de uma perigosa assassina (Mortimer) que estava reclusa no hospital psiquiátrico Ashecliffe, um centro penitenciário para criminosos perturbados dirigido pelo sinistro médico John Cawley. (Kingsley). Logo eles descobrem que o centro guarda muitos segredos e que a ilha esconde algo mais perigoso que os pacientes.', 138, NULL, '/erl801HYIodoIBGZeFk0GTwCUBh.jpg', '/lavdyiJWciCJvyLG37ZOs6HJijg.jpg', 8.2, 26839, 21.27, 'en', 57, 20, 50, 69, 16, 86, 54, 51, 83, 1, '2026-11-18 19:14:28'),
(226, 985939, 'filme', 'A Queda', 'Fall', 2022, 'Becky e Hunter são duas amigas que buscam aventura e enfrentam grande alturas em suas escaladas. Depois de um grande drama vivido por elas, as duas decidem escalar uma remota torre de rádio abandonada com mais de 2000 pés de altura. Parecia a aventura perfeita para desligar a mente do trágico acontecimento que vivenciaram com o namorado de uma delas. Elas não contavam que ficariam presas e isoladas naquele lugar sem sinal de celular, sem energia e sem pessoas por perto.', 107, NULL, '/ey5j9PzI1S0jsMPuN8H9ldrGzuX.jpg', '/hlxduUs8y9icWGMzYCDLcYHEQ2u.jpg', 7.2, 5095, 21.2, 'en', 51, 40, 50, 81, 34, 62, 64, 52, 50, 1, '2026-11-18 19:14:29'),
(227, 1439930, 'filme', 'O Justiceiro: Uma Última Morte', 'The Punisher: One Last Kill', 2026, 'Enquanto Frank Castle busca um significado além da vingança, uma força inesperada o arrasta de volta para a luta.', 51, NULL, '/ppRmgI2MbEOADvKKvlNoRJHPXOT.jpg', '/qO55CD8tgVL1T4WKn6zYFFiD6lL.jpg', 8.2, 2417, 21.17, 'en', 51, 38, 50, 77, 22, 50, 56, 52, 83, 1, '2026-11-18 19:14:30'),
(228, 840464, 'filme', 'Destruição Final 2', 'Greenland 2: Migration', 2026, 'Tendo encontrado a segurança do bunker da Groenlândia depois que o cometa Clarke dizimou a Terra, a família Garrity deve agora arriscar tudo para embarcar em uma jornada angustiante através do deserto da Europa para encontrar um novo lar.', 99, NULL, '/s6nzVekLSd1y0vGjLz8WPfC1Sau.jpg', '/cLFbDVfhllIMybpo2fkGNzehiQG.jpg', 6.4, 1664, 21.16, 'en', 61, 48, 100, 93, 34, 70, 98, 94, 83, 1, '2026-11-18 19:14:30'),
(229, 1184918, 'filme', 'Robô Selvagem', 'The Wild Robot', 2024, 'Um robô – unidade ROZZUM 7134, abreviadamente “Roz” – naufraga em uma ilha desabitada e deve aprender a se adaptar ao ambiente hostil, gradualmente construindo relacionamentos com os animais da ilha e se tornando o pai adotivo de um filhote de ganso órfão.', 101, NULL, '/gAHNIZKG8fmK7njOTpMmLKJXiag.jpg', '/1pmXyN3sKeYoUhu5VBZiDU4BX21.jpg', 8.3, 6860, 21.15, 'en', 79, 94, 100, 75, 72, 58, 100, 94, 100, 1, '2026-11-18 19:14:31'),
(230, 1284465, 'filme', 'A Morte de Robin Hood', 'The Death of Robin Hood', 2026, 'Atormentado pelas cicatrizes de uma vida marcada pelo crime, Robin Hood sobrevive por pouco àquela que acreditava ser sua batalha final. Gravemente ferido, ele é encontrado por uma mulher misteriosa que o recolhe das sombras e passa a cuidar de seus ferimentos. Com o corpo fora de combate, cada erro cometido no passado volta para assombrá-lo.', 122, NULL, '/o0QndnepFPWget2kdKpzh26RBYt.jpg', '/lh3BDkmWJh998n4fQcHYcVi7dpm.jpg', 6.7, 629, 21.12, 'en', 47, 50, 76, 89, 50, 50, 86, 60, 83, 1, '2026-11-18 19:14:31'),
(231, 585, 'filme', 'Monstros S.A.', 'Monsters, Inc.', 2001, 'O astro do susto, Sulley, e seu falante assistente, Mike, trabalham na Monstros S.A., a maior fábrica de processamento de gritos da cidade de Monstrópolis. A principal fonte de energia do mundo dos monstros provém da coleta dos gritos das crianças humanas. Os monstros acreditam que as crianças são tóxicas, e entram em pânico quando uma menininha invade seu mundo. Sulley e Mike fazem de tudo para levar a garota de volta para casa, mas enfrentam desafios monstruosos e algumas situações hilárias em suas atrapalhadas aventuras.', 92, NULL, '/5p6cdAeUevsLOX0oI1T4JIul4QO.jpg', '/c7VbRPlev1bRfKvTxr98erw5T7B.jpg', 7.9, 20533, 20.97, 'en', 67, 100, 100, 67, 80, 50, 82, 61, 100, 1, '2026-11-18 19:14:32'),
(232, 1712451, 'filme', 'Resident Dead', 'Resident Dead', 2026, NULL, 89, NULL, '/qKhMVWwFikSUzOpkhOl35GBLkGH.jpg', '/yKx5gYrYgakKZuUWAsuFDStBroy.jpg', 5.5, 85, 20.87, 'en', 61, 22, 60, 67, 36, 50, 40, 52, 50, 1, '2026-11-18 19:14:32'),
(233, 866398, 'filme', 'Beekeeper: Rede de Vingança', 'The Beekeeper', 2024, 'Clay está em busca de vingança e não vai parar até acabar com o sistema criminoso responsável pela morte de sua amiga. O plano brutal de Clay, um ex-agente de uma organização secreta poderosa conhecida como “Beekeepers”, ganha dimensões nacionais envolvendo governos e as instituições mais influentes do mundo. Determinado a fazer justiça com suas próprias mãos, ele está disposto a tudo e não vai poupar ninguém para concluir seu plano.', 105, NULL, '/raNfPn7DGbh1Ffwq4Y9BO1Iektv.jpg', '/f0ACHVpV707zqu4etZrXnWNdSgL.jpg', 7.3, 4725, 20.86, 'en', 51, 44, 50, 100, 12, 62, 68, 52, 83, 1, '2026-11-18 19:14:33'),
(234, 37165, 'filme', 'O Show de Truman: O Show da Vida', 'The Truman Show', 1998, 'Truman Burbank é um pacato vendedor de seguros que leva um vida simples com sua esposa Meryl Burbank. Porém algumas coisas ao seu redor fazem com que ele passe a estranhar sua cidade, seus supostos amigos e até sua mulher. Após conhecer a misteriosa Lauren, ele fica intrigado e acaba descobrindo que toda sua vida foi monitorada por câmeras e transmitida em rede nacional.', 103, NULL, '/3mEoGWyJCZTSoYyjFD3gFd6hzU4.jpg', '/rmiG2uwcNoGFmBKMoa1pIcf514L.jpg', 8.2, 21253, 20.8, 'en', 40, 60, 50, 49, 52, 50, 37, 49, 67, 1, '2026-11-18 19:14:33'),
(235, 49026, 'filme', 'Batman: O Cavaleiro das Trevas Ressurge', 'The Dark Knight Rises', 2012, 'Após ser culpado pela morte de Harvey Dent e passar de herói a vilão, Batman desaparece. As coisas mudam com a chegada de uma ladra misteriosa, a Mulher-Gato, e Bane, um terrorista mascarado, que fazem Batman abandonar seu exílio forçado.', 165, NULL, '/j4z01cnbTCaVX69bik1612pSuH6.jpg', '/c3OHQncTAnKFhdOTX7D3LTW6son.jpg', 7.8, 25339, 20.71, 'en', 51, 44, 50, 100, 12, 62, 68, 51, 83, 1, '2026-11-18 19:14:34'),
(236, 1290418, 'filme', 'The Cycle', 'The Cycle', 2026, 'Uma filha desvenda o passado sombrio do pai depois que seu corpo, desaparecido há 36 anos, é encontrado em uma cena de crime horrível.', 111, NULL, '/n5gSNf55KWfDc9hqP4H1KCCSutE.jpg', '/bgHW6AJl2SdKzxglvf9tshXbI84.jpg', 6.8, 163, 20.68, 'en', 71, 12, 60, 97, 8, 86, 48, 52, 83, 1, '2026-11-18 19:14:34'),
(237, 12, 'filme', 'Procurando Nemo', 'Finding Nemo', 2003, 'Nemo, um jovem peixe-palhaço aventureiro, é inesperadamente levado de sua casa na Grande Barreira de Corais para o aquário do consultório de um dentista. Cabe ao seu preocupado pai Marlin e à simpática mas esquecida peixe Dory trazer Nemo para casa - encontrando tubarões vegetarianos, tartarugas surfistas, medusas hipnóticas, gaivotas esfomeadas e muito mais pelo caminho.', 100, NULL, '/djbivExXSZb0sTO8uYaaQC5vMRM.jpg', '/eCynaAOgYYiw5yN5lBwz3IxqvaW.jpg', 7.8, 21238, 20.67, 'en', 65, 94, 100, 75, 72, 50, 92, 59, 83, 1, '2026-11-18 19:14:35'),
(238, 950387, 'filme', 'Um Filme Minecraft', 'A Minecraft Movie', 2025, 'Quatro desajustados são subitamente puxados por um portal misterioso ao Mundo Superior: um paraíso bizarro e cúbico que vive na base da imaginação. Para voltar para casa, eles embarcam em uma jornada mágica com um artesão experiente e inusitado, Steve. Juntos, sua aventura desafiará todos os cinco a serem ousados e se reconectarem com as qualidades que tornam cada um deles singularmente criativo.', 101, NULL, '/15phvDlveLgyXwa5ISVpaJJwO0w.jpg', '/2Nti3gYAX513wvhp8IiLL6ZDyOm.jpg', 6.2, 3463, 20.66, 'en', 58, 100, 100, 67, 74, 50, 92, 70, 100, 1, '2026-11-18 19:14:35'),
(239, 68721, 'filme', 'Homem de Ferro 3', 'Iron Man 3', 2013, 'Depois de um inimigo reduzir o mundo de Tony Stark a destroços, o Homem de Ferro precisa aprender a confiar em seus instintos para proteger aqueles que ama, especialmente sua namorada, e lutar contra seu maior medo: o fracasso.', 130, NULL, '/C7MZwRTjvEy7gkWcLJeBGZFE1w.jpg', '/4TSqtluelcWByj8YZdqwzQVjI0O.jpg', 6.9, 24176, 20.64, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:14:36'),
(240, 1594914, 'filme', 'Lucky Strike', 'Lucky Strike', 2026, 'Um soldado americano ferido luta para sobreviver atrás das linhas inimigas durante a Batalha das Ardenas, na Segunda Guerra Mundial, contra os alemães, confiando em seu instinto, habilidades de espionagem e um rádio portátil para evitar a captura e encontrar o caminho de volta para sua unidade.', 102, NULL, '/kzRAd7mj39ZY3FGNrDdZjqx56tn.jpg', '/uujYvxE9s6KY4SbBZ0ZFN3oBJhW.jpg', 6.4, 68, 20.5, 'en', 51, 34, 58, 95, 66, 50, 100, 40, 67, 1, '2026-11-18 19:14:36');
INSERT INTO catalogo_obras (id, tmdb_id, tipo, titulo, titulo_original, ano, sinopse, duracao, temporadas, poster_path, backdrop_path, nota, votos, popularidade, idioma_original, eixo_1, eixo_2, eixo_3, eixo_4, eixo_5, eixo_6, eixo_7, eixo_8, confianca, ativo, atualizado_em) VALUES
(241, 36557, 'filme', '007: Cassino Royale', 'Casino Royale', 2006, 'Depois de obter o status 00 e uma licença para matar, o agente secreto James Bond parte em sua primeira missão como 007. Bond precisa derrotar um banqueiro privado que financia terroristas em um jogo de pôquer de alto risco no Casino Royale, Montenegro.', 144, NULL, '/lfOk6E07jTLZsxj0SoSoAmTqhk1.jpg', '/klJMCIblHLFwCuGjKz7tyOpekIC.jpg', 7.6, 12242, 20.38, 'en', 47, 56, 76, 100, 40, 62, 98, 59, 83, 1, '2026-11-18 19:14:37'),
(242, 566525, 'filme', 'Shang-Chi e a Lenda dos Dez Anéis', 'Shang-Chi and the Legend of the Ten Rings', 2021, 'Shang-Chi precisa confrontar o passado que pensou ter deixado para trás. Ao mesmo tempo, ele é envolvido em uma teia de mistérios da organização conhecida como Dez Anéis.', 132, NULL, '/d3wNegI8XJF8Kto6KhlqPicBRAp.jpg', '/r7K6Xt0RX4Mw0cAbZVw5cyb1Tux.jpg', 7.5, 10962, 20.28, 'en', 59, 76, 100, 100, 56, 50, 100, 70, 83, 1, '2026-11-18 19:14:37'),
(243, 1297842, 'filme', 'Um Cabra Bom de Bola', 'GOAT', 2026, 'Uma pequena cabra com grandes sonhos recebe uma oportunidade única na vida de se juntar aos profissionais e jogar berrobol, um esporte de alta intensidade, misto e de contato total, dominado pelos animais mais rápidos e ferozes do mundo.', 100, NULL, '/x0SRTrltSJi1iQiIAUpyvkxnr41.jpg', '/vcM0CWnMGdOo6ty1iyt7zE1jtd6.jpg', 8, 1167, 20.19, 'en', 59, 100, 82, 67, 80, 50, 60, 52, 83, 1, '2026-11-18 19:14:38'),
(244, 10681, 'filme', 'WALL-E', 'WALL·E', 2008, 'No ano 2800, num planeta Terra devastado e sem vida, depois de centenas de anos solitários a fazer aquilo para que foi construído - limpar o planeta de lixo - o pequeno robô WALL-E descobre uma nova missão na sua vida quando conhece uma moderna e brilhante robô exploradora chamada EVE. Os dois vão viajar pela galáxia e viver uma aventura emocionante e inesquecível.', 97, NULL, '/qNiwJPVCO4cgiM8LVtxwPV2HxHS.jpg', '/nYs4ZwnJBK4AgljhvzwNz7fpr3E.jpg', 8.1, 21209, 20.19, 'en', 79, 82, 100, 57, 72, 58, 88, 85, 83, 1, '2026-11-18 19:14:38'),
(245, 346698, 'filme', 'Barbie', 'Barbie', 2023, 'No mundo mágico das Barbies, \"Barbieland\", uma das bonecas começa a perceber que não se encaixa como as outras. Depois de ser expulsa, ela parte para uma aventura no \"mundo real\", onde descobre que a beleza está no interior de cada um.', 114, NULL, '/pP12F7Gutn6CpHYaIPBlDRHlMlk.jpg', '/1esAE8sLJRWWFsLLeh5r3g2WanI.jpg', 6.9, 11829, 20.15, 'en', 49, 94, 100, 79, 58, 50, 84, 70, 83, 1, '2026-11-18 19:14:38'),
(246, 370172, 'filme', '007: Sem Tempo para Morrer', 'No Time to Die', 2021, 'Bond deixou o serviço ativo e está desfrutando de uma vida tranquila na Jamaica. Sua paz é interrompida quando o seu velho amigo Felix Leiter, da CIA, aparece pedindo sua ajuda. A missão de resgatar um cientista sequestrado acaba sendo muito mais difícil do que o esperado, deixando Bond no caminho de um vilão misterioso e armado com uma nova tecnologia perigosa.', 163, NULL, '/ymiLbqoSxGSkMeM2vW6JWpmnPjL.jpg', '/x9td0NQha0t44K2qgcMipLOGjVi.jpg', 7.3, 7573, 20.03, 'en', 47, 56, 76, 100, 40, 62, 98, 60, 83, 1, '2026-11-18 19:14:39'),
(247, 652, 'filme', 'Tróia', 'Troy', 2004, 'Quando Páris, o príncipe de Troia, se apaixona por Helena, rainha de Esparta, o rei inicia uma guerra de anos entre os dois reinos. Para vencer, Esparta conta com Aquiles, um guerreiro lendário que comanda um exército próprio.', 162, NULL, '/iKp2NxUkqPVSPN2FdXUn9gxj4Nn.jpg', '/ZPcC5hJh21QiW0jmhMQhZeSoGu.jpg', 7.2, 11736, 19.98, 'en', 47, 66, 76, 100, 56, 50, 90, 59, 67, 1, '2026-11-18 19:14:39'),
(248, 575265, 'filme', 'Missão: Impossível - O Acerto Final', 'Mission: Impossible - The Final Reckoning', 2025, 'Depois de escapar de um acidente de trem calamitoso, Ethan percebe que a Entidade está escondida a bordo de um antigo submarino russo, mas um inimigo do seu passado chamado Gabriel também está no encalço.', 169, NULL, '/yKQjrwgEkPOGel3JKT2neJzu0jh.jpg', '/538U9snNc2fpnOmYXAPUh3zn31H.jpg', 7.2, 3342, 19.93, 'en', 51, 60, 76, 100, 40, 62, 100, 60, 83, 1, '2026-11-18 19:14:40'),
(249, 429617, 'filme', 'Homem-Aranha: Longe de Casa', 'Spider-Man: Far From Home', 2019, 'Peter Parker está em uma viagem de duas semanas pela Europa, ao lado de seus amigos de colégio, quando é surpreendido pela visita de Nick Fury. Convocado para mais uma missão heroica, ele precisa enfrentar vários vilões que surgem em cidades-símbolo do continente, como Londres, Paris e Veneza, e também a aparição do enigmático Mysterio.', 130, NULL, '/tX0o4AdHpidgniTWwfzK0dNTKrc.jpg', '/wqBW5ltBJu0gs26yCc8shQQV82d.jpg', 7.4, 17920, 19.93, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:41'),
(250, 177572, 'filme', 'Operação Big Hero', 'Big Hero 6', 2014, 'O grande robô inflável está sempre a postos para cuidar de Hiro Hamada. Quando algo devastador assola a cidade, o menino prodígio, seus amigos e o robô formam um grupo de heróis para combater o mal.', 102, NULL, '/5EodFesjReSDlX1c0I5ANZijBFy.jpg', '/4s2d3xdyqotiVNHTlTlJjrr3q0H.jpg', 7.7, 17116, 19.91, 'en', 59, 100, 100, 100, 86, 50, 100, 59, 100, 1, '2026-11-18 19:14:41'),
(251, 210577, 'filme', 'Garota Exemplar', 'Gone Girl', 2014, 'Amy Dunne desaparece no dia do seu aniversário de casamento, deixando o marido Nick em apuros. Ele começa a agir descontroladamente, abusando das mentiras, e se torna o suspeito número um da polícia. Com o apoio da sua irmã gêmea, Margo, Nick tenta provar a sua inocência e, ao mesmo tempo, procura descobrir o que aconteceu com Amy.', 149, NULL, '/54nI3vSKlPp42WhJmKVRdmMbkzl.jpg', '/iWak7wT0j6ycCc8lKr4NBz9c7n5.jpg', 7.9, 20697, 19.88, 'en', 57, 20, 50, 69, 16, 86, 54, 51, 83, 1, '2026-11-18 19:14:42'),
(252, 76341, 'filme', 'Mad Max: Estrada da Fúria', 'Mad Max: Fury Road', 2015, 'Em um mundo apocalíptico, Max Rockatansky acredita que a melhor forma de sobreviver é não depender de ninguém. Porém, após ser capturado pelo tirano Immortan Joe e seus rebeldes, Max se vê no meio de uma guerra mortal, iniciada pela imperatriz Furiosa que tenta salvar um grupo de garotas. Também tentando fugir, Max aceita ajudar Furiosa. Dessa vez, o tirano Joe está ainda mais implacável pois teve algo insubstituível roubado.', 120, NULL, '/tH64gzAHDFg7EFcgfkkZyHdGM5P.jpg', '/gqrnQA6Xppdl8vIb2eJc58VC1tW.jpg', 7.6, 24972, 19.85, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:42'),
(253, 272, 'filme', 'Batman Begins', 'Batman Begins', 2005, 'Marcado pelo assassinato de seus pais quando ainda era criança, o milionário Bruce Wayne decide viajar pelo mundo em busca de encontrar meios que lhe permitam combater a injustiça e provocar medo em seus adversários. Após retornar a Gotham City, sua cidade-natal, ele idealiza seu alter-ego: Batman, um justiceiro mascarado que usa força, inteligência e um arsenal tecnológico para combater o crime.', 140, NULL, '/7EyhcdfiLtH0xa6CZkyYuoWL2GJ.jpg', '/9IIBboV7MCT0bTxzXHmWK1Hq558.jpg', 7.7, 23552, 19.81, 'en', 47, 34, 50, 71, 22, 50, 50, 51, 83, 1, '2026-11-18 19:14:43'),
(254, 16869, 'filme', 'Bastardos Inglórios', 'Inglourious Basterds', 2009, 'Durante a Segunda Guerra Mundial, na França, um grupo de judeus americanos conhecidos como Bastardos espalha o terror entre o terceiro Reich. Ao mesmo tempo, Shosanna, uma judia que fugiu dos nazistas, planeja vingança quando um evento em seu cinema reunirá os líderes do partido.', 152, NULL, '/6UjYycIR6VLYgggfNpmSPJHmFS0.jpg', '/bMJxwgLyD47CDQ6BFCT2AMMlID7.jpg', 8.2, 25179, 19.81, 'en', 52, 0, 50, 63, 34, 62, 74, 39, 83, 1, '2026-11-18 19:14:46'),
(255, 218, 'filme', 'O Exterminador do Futuro', 'The Terminator', 1984, 'Em um futuro próximo, a guerra entre humanos e máquinas foi iniciada. Com a tecnologia a seu dispor, um plano inusitado é arquitetado pelas máquinas ao enviar para o passado um andróide com a missão de matar a mãe daquele que viria a se transformar num líder e seu pior inimigo. Contudo, os humanos também conseguem enviar seu representante para proteger a mulher e tentar garantir o futuro da humanidade.', 107, NULL, '/fo4SSoNT1ASI4JP7dOLrosWNWKa.jpg', '/ffdqHMWkh1h9MABwIfbfRJhgFW6.jpg', 7.7, 15447, 19.71, 'en', 60, 44, 92, 100, 40, 70, 95, 83, 83, 1, '2026-11-18 19:14:47'),
(256, 863, 'filme', 'Toy Story 2', 'Toy Story 2', 1999, 'Quando Andy viaja para um acampamento de verão, Woody é sequestrado por Al, um ambiocioso colecionador, que precisa do brinquedo favorito de Andy para completar sua coleção da Gangue do Rodeio. Junto com Jessie, Bala no Alvo e Mineiro, Woody corre o risco de ter que passar o resto de sua vida em exposição num museu. Agora, Buzz, Sr. Cabeça de Batata, Porquinho, Rex e Slinky terão que salvar seu amigo e trazê-lo de volta à vida de brinquedos.', 92, NULL, '/xVhEI1WCgNCCa5I86AqiwuZoog3.jpg', '/nsfVr4QbbunUrHINN9N7JdVAMTf.jpg', 7.6, 15598, 19.69, 'en', 58, 100, 82, 67, 80, 50, 61, 49, 83, 1, '2026-11-18 19:14:47'),
(257, 49051, 'filme', 'O Hobbit: Uma Jornada Inesperada', 'The Hobbit: An Unexpected Journey', 2012, 'Como a maioria dos hobbits, Bilbo Bolseiro leva uma vida tranquila até o dia em que recebe uma missão do mago Gandalf. Acompanhado por um grupo de anões, ele parte numa jornada até a Montanha Solitária para libertar o Reino de Erebor do dragão Smaug.', 183, NULL, '/lZtmn2pLw1kgDYj4Ig4s3DYBQCD.jpg', '/xyXmtuvsoM5J3yNad0nvcetpBdY.jpg', 7.4, 20356, 19.64, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:14:48'),
(258, 205596, 'filme', 'O Jogo da Imitação', 'The Imitation Game', 2014, 'Em 1939, a recém-criada agência de inteligência britânica MI6 recruta Alan Turing, um aluno da Universidade de Cambridge, para entender códigos nazistas, incluindo o \"Enigma\", que criptógrafos acreditavam ser inquebrável. A equipe de Turing, incluindo Joan Clarke, analisa as mensagens de \"Enigma\", enquanto ele constrói uma máquina para decifrá-las.', 113, NULL, '/pNa7vGKv04X2jnKifxLCTHPmWUT.jpg', '/8FCHJ21JBQOgATY2WI8vwYAiXg8.jpg', 8, 18674, 19.6, 'en', 39, 0, 50, 57, 38, 62, 96, 7, 100, 1, '2026-11-18 19:14:49'),
(259, 726209, 'filme', 'O Mundo Depois de Nós', 'Leave the World Behind', 2023, 'As férias de uma família numa casa luxuosa sofrem uma reviravolta quando um ciberataque afeta todos os dispositivos e duas pessoas estranhas batem à porta.', 141, NULL, '/qwHZInQ0MBa1DxHV66ExCCUzBf5.jpg', '/5cRw2QHQz5bp7W2KLdSpZoFoTTw.jpg', 6.4, 3540, 19.58, 'en', 57, 20, 50, 69, 16, 86, 54, 52, 83, 1, '2026-11-18 19:14:49'),
(260, 1242898, 'filme', 'Predador: Terras Selvagens', 'Predator: Badlands', 2025, 'No futuro, em um planeta remoto, um jovem Predador, rejeitado por seu clã, encontra em Thia uma aliada improvável e embarca em uma jornada traiçoeira em busca do adversário supremo.', 107, NULL, '/f3yLlUrJDdDL8d4nxywyotN45SL.jpg', '/82lM4GJ9uuNvNDOEpxFy77uv4Ak.jpg', 7.8, 3917, 19.58, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:14:50'),
(261, 1727734, 'filme', 'Ali G: Ken é Eu?', 'Ali G: Who Iz I?', 2026, 'Depois de 20 anos \"curtindo, fumando e transando\", Ali G descobre que sua namorada, Me Julie, está grávida de oito meses. Com mais uma boca para alimentar, ele sai da loucura e vai à América retomar sua antiga glória… mas logo encontra adversários que irão ameaçar sua vida e a própria existência do seu filho.', 89, NULL, '/j835nBIlJp3nkYaf96z0bD4P8Ux.jpg', '/h7gas4rrcaSitLgF2ODry3Wz9KZ.jpg', 5.6, 200, 19.51, 'en', 41, 76, 50, 61, 58, 50, 40, 52, 50, 1, '2026-11-18 19:14:50'),
(262, 976912, 'filme', 'O Limite do Prazer', 'Graphic Desires', 2023, 'Quando o recluso Franklin trai sua garota com uma mulher misteriosa que ele conhece em um aplicativo de namoro, isso se torna o início de uma obsessão mortal.', 90, NULL, '/fmLQaEPC9uRCbjPs1NI4S90qimH.jpg', '/rHnANzYUmV3WZw3n0yWOLiR3pen.jpg', 6.8, 164, 19.5, 'en', 51, 36, 42, 81, 6, 62, 50, 52, 67, 1, '2026-11-18 19:14:51'),
(263, 350, 'filme', 'O Diabo Veste Prada', 'The Devil Wears Prada', 2006, 'Andrea Sachs é uma jovem que conseguiu um emprego na Runaway Magazine, a mais importante revista de moda de Nova York. Ela passa a trabalhar como assistente de Miranda Priestly, principal executiva da revista. Apesar da chance que muitos sonhariam em conseguir, logo Andrea nota que trabalhar com Miranda não é tão simples assim.', 109, NULL, '/3lAwJ0x87dCv2wRGt7cDdYG7Qnp.jpg', '/gkh6Nt8DtY1XT4gQsyFq9XAVJlJ.jpg', 7.4, 14448, 19.46, 'en', 41, 60, 50, 49, 52, 50, 36, 51, 67, 1, '2026-11-18 19:14:52'),
(264, 1171145, 'filme', 'Caminhos do Crime', 'Crime 101', 2026, 'Um ladrão enigmático realiza assaltos de alto risco ao longo da icônica rodovia 101. Quando ele mira o golpe de sua vida — na esperança de que este seja seu último trabalho —, seu caminho cruza com o de uma corretora de seguros desiludida, forçando os dois a colaborar. Determinado a desvendar o caso, um detetive implacável se aproxima da operação.', 141, NULL, '/3u8Pr8WF9hqMptlnuYL52YXSs8F.jpg', '/kKF4gEiBDArhONlCcunHVgBp3bA.jpg', 7, 1496, 19.39, 'en', 51, 36, 42, 81, 6, 62, 50, 52, 67, 1, '2026-11-18 19:14:52'),
(265, 694, 'filme', 'O Iluminado', 'The Shining', 1980, 'Durante o inverno, um homem é contratado para ficar como vigia em um hotel no Colorado e vai para lá com a esposa e seu filho. Porém, o contínuo isolamento começa a lhe causar problemas mentais sérios e ele vai se tornado cada vez mais agressivo e perigoso, ao mesmo tempo que seu filho passa a ter visões de acontecimentos ocorridos no passado, que também foram causados pelo isolamento excessivo.', 146, NULL, '/47BdQqDWnj3VIzpH9bd2agho2PN.jpg', '/AdKA2F1SzYPhSZdEbjH1Zh75UVQ.jpg', 8.2, 19705, 19.38, 'en', 56, 8, 60, 85, 20, 62, 43, 49, 67, 1, '2026-11-18 19:14:53'),
(266, 1159559, 'filme', 'Pânico 7', 'Scream 7', 2026, 'Quando um novo Ghostface surge na pacata cidade onde Sidney Prescott reconstruiu sua vida, seus medos mais sombrios se tornam reais enquanto sua filha se torna o próximo alvo do assassino. Determinada a proteger sua família, Sidney terá que enfrentar os horrores do seu passado para acabar com o massacre de uma vez por todas.', 114, NULL, '/rEevavl5vebCVEd5imx7D1k8nmV.jpg', '/3eUyLEF5M0ky3h6KJsWiWzaakB8.jpg', 6.2, 1451, 19.36, 'en', 75, 22, 52, 79, 0, 74, 32, 52, 83, 1, '2026-11-18 19:14:53'),
(267, 109445, 'filme', 'Frozen: Uma Aventura Congelante', 'Frozen', 2013, 'A destemida e otimista Anna sai em uma jornada épica, ao lado de Kristoff e sua leal rena Sven, para encontrar sua irmã Elsa, cujos poderes congelantes aprisionaram o reino de Arendelle em um inverno eterno. Encontrando condições de Everest, trolls místicos e um hilário boneco de neve chamado Olaf, Anna e Kristoff enfrentam obstáculos em uma corrida para salvar o reino.', 102, NULL, '/hOZKUJGN0m717LRSQDxhgABqWrf.jpg', '/rj58WQ9ImI0mYDptXdM7euX1Wjt.jpg', 7.2, 18095, 19.28, 'en', 73, 100, 100, 75, 72, 50, 100, 69, 100, 1, '2026-11-18 19:14:54'),
(268, 62, 'filme', '2001: Uma Odisséia no Espaço', '2001: A Space Odyssey', 1968, 'Desde a “Aurora do Homem” (a pré-história), um misterioso monólito negro parece emitir sinais de outra civilização, assim interferindo no nosso planeta. Quatro milhões de anos depois, no século XXI, uma equipe de astronautas liderados pelo experiente David Bowman e Frank Poole é enviada ao planeta Júpiter para investigar o enigmático monólito na nave Discovery, totalmente controlada pelo computador HAL-9000. Entretanto, no meio da viagem, HAL-9000 entra em pane e tenta assumir o controle da nave, eliminando um a um os tripulantes.', 148, NULL, '/pVCmLuATJ0lQs4Vx1zUJUN0if2A.jpg', '/w5IDXtifKntw0ajv2co7jFlTQDM.jpg', 8, 13165, 19.26, 'en', 67, 58, 100, 72, 38, 82, 90, 89, 83, 1, '2026-11-18 19:14:55'),
(269, 1325734, 'filme', 'O Drama', 'The Drama', 2026, 'Profundamente apaixonados e em meio aos preparativos finais para o grande dia do casamento, o casal tem sua felicidade ameaçada quando vêm à tona segredos que jamais poderiam imaginar.', 106, NULL, '/tM3hbeEwJZdQAjwwt5UjFn638AY.jpg', '/1oKLEA9JOhvaBwLpqjROisvWMy7.jpg', 6.9, 2087, 19.26, 'en', 41, 80, 50, 35, 58, 50, 22, 46, 83, 1, '2026-11-18 19:14:55'),
(270, 385687, 'filme', 'Velozes & Furiosos 10', 'Fast X', 2023, 'Dom Toretto enfrenta seu maior desafio até agora: a corrida para salvar a família de um inimigo cheio de rancor e fúria no volante.', 142, NULL, '/xNqt1Om0IlUhDOjZRCL5ewoazVV.jpg', '/4XM8DUTQb3lhLemJC51Jx4a2EuA.jpg', 7, 6641, 19.26, 'en', 55, 48, 50, 100, 12, 62, 74, 52, 83, 1, '2026-11-18 19:14:56'),
(271, 138843, 'filme', 'Invocação do Mal', 'The Conjuring', 2013, 'Harrisville, Rhode Island, Estados Unidos, 1968. Os investigadores paranormais Ed e Lorraine Warren trabalham para ajudar uma família aterrorizada por uma presença sombria em sua fazenda. Forçados a confrontar uma entidade poderosa, os Warrens se vêem presos no caso mais aterrorizante de suas vidas. Baseado numa história real.', 112, NULL, '/1NxHKZW5DPbUFtbF3MxbdSyxRqU.jpg', '/ecKQlAEG95k62SMGhvX83oEqANK.jpg', 7.5, 13308, 19.21, 'en', 61, 12, 60, 91, 20, 62, 48, 51, 67, 1, '2026-11-18 19:14:57'),
(272, 1078605, 'filme', 'A Hora do Mal', 'Weapons', 2025, 'Quando todas as crianças de uma mesma classe, exceto uma, somem misteriosamente, na mesma noite e exatamente ao mesmo tempo, todos da cidade começam a se questionar quem ou o que está por trás deste estranho desaparecimento.', 128, NULL, '/psEJSjQr6I9GSJTdW28CKC4Kffs.jpg', '/8VyTWJrNEyV2MTWvniDVp0MpOAe.jpg', 7.3, 4313, 19.21, 'en', 71, 22, 60, 73, 24, 74, 40, 52, 67, 1, '2026-11-18 19:14:57'),
(273, 7131, 'filme', 'Van Helsing: O Caçador de Monstros', 'Van Helsing', 2004, 'O famoso caçador de monstros Van Helsing é enviado à Transilvânia para ajudar os últimos da linhagem Valerious a derrotar o Conde Drácula. Anna Valerious revela que Drácula formou uma aliança profana com o monstro do Dr. Frankenstein e está determinado a lançar uma maldição secular sobre sua família.', 132, NULL, '/s8fhGCLWbFDbBAOitRzVlMPk5pd.jpg', '/d72ROyJqXQtw2OupW0l15eicRAF.jpg', 6.4, 6959, 19.12, 'en', 61, 42, 86, 100, 42, 50, 80, 59, 83, 1, '2026-11-18 19:14:58'),
(274, 329865, 'filme', 'A Chegada', 'Arrival', 2016, 'Quando seres interplanetários deixam marcas na Terra, a Dra. Louise Banks, uma linguista especialista no assunto, é procurada por militares para traduzir os sinais e desvendar se os alienígenas representam uma ameaça. No entanto, a resposta para todas as perguntas e mistérios coloca em risco  a vida de Louise e a de toda a humanidade.', 116, NULL, '/3rDwbFpn6z5HJUgDjpfhEePx8VI.jpg', '/8MUZz7oPXQftFTslZpRP3CVMOoq.jpg', 7.6, 20200, 19.11, 'en', 71, 30, 84, 45, 32, 82, 64, 86, 83, 1, '2026-11-18 19:14:58'),
(275, 931285, 'filme', 'Mortal Kombat 2', 'Mortal Kombat II', 2026, 'Os campeões favoritos dos fãs – agora acompanhados pelo próprio Johnny Cage – são colocados uns contra os outros numa sangrenta e derradeira batalha, sem regras ou limites, para derrotar o governo sombrio de Shao Kahn.', 116, NULL, '/iILiJSRViTEcF23MHhGCbVm3mfW.jpg', '/4EAAwpylq313qrDqpCxulUrXBNF.jpg', 7.7, 2799, 19.07, 'en', 59, 76, 100, 100, 56, 50, 100, 70, 83, 1, '2026-11-18 19:14:59'),
(276, 262500, 'filme', 'A Série Divergente: Insurgente', 'Insurgent', 2015, 'Em fuga e sob a mira da impiedosa líder de facção Jeanine, Tris luta para proteger as pessoas que ama, enfrentando um desafio impossível após outro, enquanto ela e Quatro correm apra desvendar a verdade sobre o passado – e dessa forma, sobre o futuro – de seu mundo.', 119, NULL, '/6ZUoxkfTH1m4oaZSVvPDhFfyDJf.jpg', '/8YNNyQiPZlF9qv5EGOUK20mnXVk.jpg', 6.4, 10690, 19.04, 'en', 65, 48, 92, 100, 40, 70, 100, 86, 83, 1, '2026-11-18 19:15:00'),
(277, 577922, 'filme', 'Tenet', 'Tenet', 2020, 'Armado com apenas uma palavra – Tenet – e lutando pela sobrevivência do mundo inteiro, o Protagonista viaja através de um mundo crepuscular de espionagem internacional em uma missão que irá desenrolar em algo para além do tempo real.', 152, NULL, '/Ae0pbv4E6YfqfN3UjKWIfQSzP9v.jpg', '/mQOUyqDybTqxl73hO5LujCZsM1o.jpg', 7.2, 11794, 19, 'en', 61, 44, 92, 100, 40, 70, 94, 86, 83, 1, '2026-11-18 19:15:01'),
(278, 293660, 'filme', 'Deadpool', 'Deadpool', 2016, 'Depois de passar por um experimento desonesto que lhe concede um fator de cura acelerado, mas desfigura seu rosto, o ex-agente das Forças Especiais Wade Wilson assume o alter ego de Deadpool. Com suas novas habilidades e um senso de humor sombrio e perverso, Deadpool persegue o homem que quase destruiu sua vida.', 107, NULL, '/tekExNqal2kcHp8BKiHX5jjxK9J.jpg', '/rFj9IKlL75B2pXhZA60jkNWvxeW.jpg', 7.6, 33648, 18.99, 'en', 45, 100, 76, 100, 64, 50, 86, 60, 83, 1, '2026-11-18 19:15:02'),
(279, 545611, 'filme', 'Tudo em Todo o Lugar ao Mesmo Tempo', 'Everything Everywhere All at Once', 2022, 'Uma imigrante chinesa parte rumo a uma aventura onde, sozinha, precisará salvar o mundo, explorando outros universos e outras vidas que poderia ter vivido. Contudo, as coisas se complicam quando ela fica presa nessa infinidade de possibilidades sem conseguir retornar para casa.', 139, NULL, '/2dSZQGwijlXvMSyuGe0FSgrXnv0.jpg', '/fIwiFha3WPu5nHkBeMQ4GzEk0Hv.jpg', 7.7, 8677, 18.96, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:15:02'),
(280, 14160, 'filme', 'Up: Altas Aventuras', 'Up', 2009, 'Carl Fredricksen é um vendedor de balões que, aos 78 anos, está prestes a perder a casa em que sempre viveu com sua esposa, a falecida Ellie. Após um incidente, Carl é considerado uma ameaça pública e forçado a ser internado. Para evitar que isto aconteça, ele põe balões em sua casa, fazendo com que ela levante voo. Carl quer viajar para uma floresta na América do Sul, onde ele e Ellie sempre desejaram morar, mas descobre que um problema embarcou junto: Russell, um menino de 8 anos.', 96, NULL, '/oo5gvGDIiPwbXc3R0snZIuOc517.jpg', '/hGGC9gKo7CFE3fW07RA587e5kol.jpg', 8, 22415, 18.95, 'en', 59, 100, 100, 85, 80, 50, 82, 59, 100, 1, '2026-11-18 19:15:03'),
(281, 58, 'filme', 'Piratas do Caribe: O Baú da Morte', 'Pirates of the Caribbean: Dead Man\'s Chest', 2006, 'Will e Elizabeth estão prestes a se casar quando o lendário pirata Davy Jones, comandante do invencível navio assombrado O Holandês Voador, aparece para cobrar uma dívida do capitão Jack Sparrow, amigo do casal. A única chance de Sparrow se livrar de uma maldição de Jones é encontrando o baú da morte.', 151, NULL, '/yvD1G41HwHgj8afCjmfGbyRmBBR.jpg', '/vr6n6ZFUZvedvIlhfYcbCWcaKyW.jpg', 7.4, 17865, 18.88, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:15:04'),
(282, 1930, 'filme', 'O Espetacular Homem-Aranha', 'The Amazing Spider-Man', 2012, 'Peter Parker está tentando saber mais sobre sua origem. Ele encontra uma pasta que pertenceu ao seu pai e quer descobrir por que seus pais desapareceram. Sua busca o leva a Oscorp e ao dr. Curt Connors, que tem como alterego o letal Lagarto.', 136, NULL, '/gxSsFBCFuDhVQMCuIDoZcmHOqlY.jpg', '/sxskOU71CO8LaNX2LOtjYFUtKv7.jpg', 6.8, 19373, 18.87, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:15:04'),
(283, 111, 'filme', 'Scarface', 'Scarface', 1983, 'Após receber residência permanente nos EUA em troca do assassinato de um oficial do governo cubano, Tony Montana se torna chefe do tráfico de drogas em Miami. A pressão da polícia, as guerras com cartéis colombianos e sua própria paranoia servem para alimentar as chamas de sua eventual queda.', 166, NULL, '/b089YkBDJjOGDQxXkOXBR06Lz2Y.jpg', '/cCvp5Sni75agCtyJkNOMapORUQV.jpg', 8.2, 13701, 18.85, 'en', 50, 38, 50, 77, 22, 50, 57, 49, 83, 1, '2026-11-18 19:15:05'),
(284, 87513, 'filme', 'Motor City', 'Motor City', 2026, 'Um criminoso recém-libertado busca vingança contra aqueles que o incriminaram e o colocaram na cadeia.', 104, NULL, '/djQDbncuITRUOheWun2oecgLIDW.jpg', '/l7asYmqOad01F2u0oCMM8nQjoEP.jpg', 6.2, 149, 18.79, 'en', 55, 48, 50, 100, 12, 62, 74, 52, 83, 1, '2026-11-18 19:15:05'),
(285, 1422, 'filme', 'Os Infiltrados', 'The Departed', 2006, 'Billy Costigan, um jovem policial, recebe a missão de se infiltrar na máfia, mais especificamente no grupo comandado por Frank Costello. Billy conquista sua confiança ao mesmo tempo em que Colin Sullivan, um criminoso que atuou na polícia como informante de Costello, também ascende dentro da corporação. Tanto Billy quanto Colin se sentem aflitos devido à vida dupla que levam. Mas quando a máfia e a polícia descobrem que há um espião entre eles, a vida de ambos passa a correr perigo.', 151, NULL, '/qtnAwzDapzOML4Q9p7lv2bk5gvz.jpg', '/6WRrGYalXXveItfpnipYdayFkQB.jpg', 8.2, 16948, 18.78, 'en', 60, 20, 42, 72, 0, 62, 46, 51, 83, 1, '2026-11-18 19:15:06'),
(286, 12153, 'filme', 'As Branquelas', 'White Chicks', 2004, 'O que acontece quando dois atrapalhados agentes do FBI se disfarçam de princesas mega-ricas para se infiltrarem na alta sociedade? O resultado é situações extremamente engraçadas e diversão total ao ver estes dois irmãos azarados transformando-se em duas senhoritas refinadas e com estilo!', 114, NULL, '/aJZOcorpgloDLkPP6ED0t9sXjNu.jpg', '/di47xqYMCYpjqwnqNlO17X5qXMX.jpg', 7, 4858, 18.75, 'en', 49, 80, 42, 73, 30, 50, 38, 51, 67, 1, '2026-11-18 19:15:07'),
(287, 284054, 'filme', 'Pantera Negra', 'Black Panther', 2018, 'O príncipe T\'Challa retorna a Wakanda para ser coroado rei. Assumindo o manto de Pantera Negra, ele vai à caça de um vilão que roubou um precioso metal de seu país.', 134, NULL, '/ubXNpxL2ASSzY0f8Hxv08pOsV2L.jpg', '/b6ZJZHUdMEFECvGiDpJjlfUWela.jpg', 7.4, 24260, 18.55, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:15:07'),
(288, 1387382, 'filme', 'Temporada de Sangue', 'Hunting Season', 2025, 'Um pai solteiro fará de tudo para proteger sua filha de 13 anos do mundo corrupto que a cerca, enfrentando ameaças que testam seus limites enquanto luta para garantir a ela um futuro mais seguro.', 100, NULL, '/fDXOdFhBoUNyY7GsM11z7EfKk68.jpg', '/eJ0HooOOD1uzI39CfOQNWIiWKlJ.jpg', 7.4, 496, 18.54, 'en', 47, 28, 58, 95, 34, 62, 72, 52, 83, 1, '2026-11-18 19:15:08'),
(289, 1054867, 'filme', 'Uma Batalha Após a Outra', 'One Battle After Another', 2025, 'Bob, um revolucionário fracassado, vive chapado e em um estado de paranoia, sobrevivendo isolado com Willa, sua filha espirituosa e independente. Quando seu perverso arqui-inimigo ressurge após 16 anos e ela desaparece, o ex-radical corre para encontrá-la, pai e filha tendo que enfrentar as consequências do passado dele.', 161, NULL, '/2peYXW6CoruehDnKJGMjl2NuaNB.jpg', '/hiazLNa1UXuX35OTnMQRKOx3eTk.jpg', 7.3, 4548, 18.52, 'en', 49, 70, 42, 97, 14, 62, 46, 52, 83, 1, '2026-11-18 19:15:09'),
(290, 324786, 'filme', 'Até o Último Homem', 'Hacksaw Ridge', 2016, 'Desmond T. Doss, foi o médico do Exército Americano da Segunda Guerra Mundial, que serviu durante a Batalha de Okinawa, se recusando a matar pessoas, tornando-se o primeiro homem da história americana a receber a Medalha de Honra sem disparar um tiro.', 140, NULL, '/mPnU3yKuZpmLjkVXGplhkpX31LY.jpg', '/vDKRMZGFTKP9nQolzeSB1rB1w6p.jpg', 8.2, 15529, 18.48, 'en', 35, 2, 50, 27, 54, 50, 82, 8, 83, 1, '2026-11-18 19:15:09'),
(291, 313369, 'filme', 'La La Land: Cantando Estações', 'La La Land', 2016, 'O pianista Sebastian conhece a atriz Mia, e os dois se apaixonam perdidamente. Em busca de oportunidades para suas carreiras na competitiva Los Angeles, os jovens tentam fazer o relacionamento amoroso dar certo, enquanto perseguem fama e sucesso.', 128, NULL, '/AvMietG6xuobpSSdmVnKuTjv4bL.jpg', '/nlPCdZlHtRNcF6C9hzUH4ebmV1w.jpg', 7.9, 18747, 18.46, 'en', 41, 80, 50, 35, 58, 50, 22, 46, 83, 1, '2026-11-18 19:15:12'),
(292, 1482547, 'filme', 'Fio Mortal', 'Zip Wire', 2026, 'Após testemunhar a morte de sua mãe por uma doença incurável aos 13 anos, uma pesquisadora determinada se dedica a encontrar uma cura, lidando com TOC e seu debilitante medo de alturas.', 94, NULL, '/AaE377fyq5yYsl1aJ7tMIQVLiY.jpg', '/yIwdIsM2Nr6EaiWy23mQqxvmoNh.jpg', 7.4, 104, 18.4, 'en', 56, 36, 58, 95, 40, 62, 76, 52, 67, 1, '2026-11-18 19:15:13'),
(293, 950396, 'filme', 'Entre Montanhas', 'The Gorge', 2025, 'Dois agentes altamente treinados se aproximam à distância após serem enviados para proteger lados opostos de um desfiladeiro misterioso. Quando um mal emerge, eles precisam trabalhar juntos para sobreviver ao que está lá dentro.', 127, NULL, '/7zL6RxMPmpPSdU5OTdVC4dtiKcr.jpg', '/9nhjGaFLKtddDPtPaX5EmKqsWdH.jpg', 7.7, 4419, 18.39, 'en', 65, 60, 84, 67, 40, 70, 68, 80, 83, 1, '2026-11-18 19:15:13'),
(294, 1168190, 'filme', 'Dupla Perigosa', 'The Wrecking Crew', 2026, 'Dois meios-irmãos que não se falavam há muito, Jonny e James, se reencontram após a morte misteriosa do pai deles. Ao buscarem a verdade, desvendam segredos de uma conspiração que pode destruir a família.', 124, NULL, '/jYpk5Zun4VTWrplO3m9BHANi4S5.jpg', '/cz4vLJrmaV1zJlRYbxqtvLzeLWB.jpg', 7.1, 1359, 18.39, 'en', 59, 88, 50, 100, 24, 74, 56, 52, 100, 1, '2026-11-18 19:15:14'),
(295, 207, 'filme', 'Sociedade dos Poetas Mortos', 'Dead Poets Society', 1989, 'Em 1959 na Welton Academy, uma tradicional escola preparatória, um ex-aluno se torna o novo professor de literatura, mas logo seus métodos de incentivar os alunos a pensarem por si mesmos cria um choque com a ortodoxa direção do colégio, principalmente quando ele fala aos seus alunos sobre a \"Sociedade dos Poetas Mortos\".', 128, NULL, '/gMmbJEqEzupp4BYTcRkNsPDPvQE.jpg', '/lFIXZpwwlF9hg8NM3RazaIJDuaj.jpg', 8.3, 13197, 18.28, 'en', 46, 30, 50, 39, 44, 50, 47, 49, 50, 1, '2026-11-18 19:15:15'),
(296, 20352, 'filme', 'Meu Malvado Favorito', 'Despicable Me', 2010, 'Um homem que adora todas as coisas diabólicas, o supervilão Gru traça um plano para roubar a lua. Rodeado de um exército de pequenos ajudantes e seu arsenal de armas e máquinas de guerra, Gru se prepara para destruir quem atravessar seu caminho. Mas ele não esperava pelo seu maior desafio: três adoráveis órfãs que querem ter Gru como pai.', 95, NULL, '/rYZzutMXxvirK9gK01iLo3Blaj3.jpg', '/2XSeKDmIa2KxaiJy4J9e8FrIZhk.jpg', 7.3, 16584, 18.27, 'en', 77, 100, 100, 73, 52, 58, 70, 85, 100, 1, '2026-11-18 19:15:15'),
(297, 466272, 'filme', 'Era Uma Vez em… Hollywood', 'Once Upon a Time in... Hollywood', 2019, 'Los Angeles, 1969. O astro de TV Rick Dalton, um ator em dificuldades especializado em faroestes, e o dublê Cliff Booth, seu melhor amigo, tentam sobreviver em uma indústria cinematográfica em constante mudança. Dalton é vizinho da jovem e promissora atriz e modelo Sharon Tate, que acaba de se casar com o prestigiado diretor polonês Roman Polanski.', 162, NULL, '/zgr02U2Fh0sR5JtaAXY5yBU1wka.jpg', '/kKTPv9LKKs5L3oO1y5FNObxAPWI.jpg', 7.4, 15581, 18.26, 'en', 52, 50, 55, 72, 36, 62, 47, 52, 83, 1, '2026-11-18 19:15:16'),
(298, 1087192, 'filme', 'Como Treinar o Seu Dragão', 'How to Train Your Dragon', 2025, 'Na montanhosa Ilha de Berk, vikings e dragões são inimigos implacáveis há gerações, mas Soluço é diferente. Filho do Chefe Stoico, o Imenso, o criativo e subestimado Soluço desafia séculos de tradição ao fazer amizade com Banguela, um temido dragão Fúria da Noite. Essa relação improvável revela a verdadeira natureza dos dragões, abalando as bases da sociedade viking.', 125, NULL, '/vdvEClt3J8sFWxyMo0Jm7JpouEo.jpg', '/8J6UlIFcU7eZfq9iCLbgc8Auklg.jpg', 7.9, 3247, 18.04, 'en', 59, 98, 100, 100, 78, 50, 100, 70, 100, 1, '2026-11-18 19:15:17'),
(299, 933260, 'filme', 'A Substância', 'The Substance', 2024, 'Uma estrela em declínio descobre uma substância misteriosa que lhe permite criar uma versão mais jovem e perfeita de si mesma. No entanto, o que parece ser uma solução milagrosa para recuperar sua glória logo se transforma em um pesadelo perturbador quando as consequências desta decisão começam a se manifestar de formas sombrias e irreversíveis.', 140, NULL, '/vWeOgzlhnP1sS23H3rzctGHB9Nb.jpg', '/9Whl7RAzes0oMaFAeSqD8ttN3fl.jpg', 7.1, 6807, 17.97, 'en', 81, 15, 94, 49, 36, 58, 48, 86, 67, 1, '2026-11-18 19:15:17'),
(300, 559, 'filme', 'Homem-Aranha 3', 'Spider-Man 3', 2007, 'O relacionamento entre Peter Parker e Mary Jane parece estar dando certo, mas outros problemas começam a surgir. A roupa de Homem-Aranha torna-se preta e acaba controlando Peter, que apesar de aumentar seus poderes, revela o lado obscuro de sua personalidade. Os vilões Venon e Homem-Areia tentam destruir o super-herói.', 139, NULL, '/5831VrgpYNPEokBwxurLVpQ3twM.jpg', '/FfAU0PUs8AJkMU2VbkVNFtRXR4.jpg', 6.5, 16036, 17.95, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:15:18'),
(301, 321612, 'filme', 'A Bela e a Fera', 'Beauty and the Beast', 2017, 'Moradora de uma pequena aldeia francesa, Bela tem o pai capturado pela Fera e decide entregar sua vida ao estranho ser em troca da liberdade do progenitor. No castelo ela conhece objetos mágicos e descobre que a Fera é na verdade um príncipe que precisa de amor para voltar à forma humana.', 129, NULL, '/8JkXzfzwpZNZV72vSbG5c3Vn6Tt.jpg', '/uU1Mt4JWhDvl4vKb3AfxNsorkoM.jpg', 7, 16327, 17.93, 'en', 59, 98, 92, 43, 78, 50, 72, 56, 83, 1, '2026-11-18 19:15:21'),
(302, 68718, 'filme', 'Django Livre', 'Django Unchained', 2012, 'Django é um escravo, comprado pelo caçador de recompensas alemão Dr. King Schultz para auxiliá-lo em uma missão. A dupla acaba fazendo amizade e, após resolver os problemas do caçador, parte em busca por Broomhilda, esposa de Django. Para isso, eles devem enfrentar o vilão Calvin Candie, proprietário da escrava.', 165, NULL, '/ar63Sx8jeqk0OOu2uchS477S2zE.jpg', '/2oZklIzUbvZXXzIFzv7Hi68d6xf.jpg', 8.2, 28992, 17.91, 'en', 37, 30, 50, 29, 48, 50, 66, 21, 67, 1, '2026-11-18 19:15:22'),
(303, 1380417, 'filme', 'No Limite da Justiça', 'By Any Means', 2026, 'Um jovem agente negro do FBI é convocado para encontrar os culpados pela morte do ativista Vernon Dahmer. Para isso, ele precisa trabalhar ao lado de Gregory Scarpa, um dos assassinos mais notórios da máfia e acostumado a lidar com problemas usando violência e métodos questionáveis.', 106, NULL, '/aD01dfnZ0RSrDEEOz7qwm4SReeD.jpg', '/1jANqIbqrWJZb8GM5Kb3L6U8iHi.jpg', 6.7, 119, 17.89, 'en', 47, 40, 42, 75, 6, 62, 72, 20, 83, 1, '2026-11-18 19:15:23'),
(304, 263115, 'filme', 'Logan', 'Logan', 2017, 'Em um futuro próximo, um cansado Logan cuida do doente Professor Xavier em um esconderijo na fronteira mexicana. Mas as tentativas de Logan de se esconder do mundo e de seu legado são interrompidas com a chegada de uma jovem mutante, perseguida por forças sombrias.', 135, NULL, '/f0CtZbae9cXj8bkWdCHzUHx5lsR.jpg', '/4DZxWNSAyksN6N3JkvpJ53Yq6zU.jpg', 7.8, 21094, 17.87, 'en', 61, 38, 92, 71, 50, 58, 82, 86, 83, 1, '2026-11-18 19:15:23'),
(305, 1034541, 'filme', 'Terrifier 3', 'Terrifier 3', 2024, 'O palhaço assassino Art está pronto para espalhar o caos sobre os moradores inocentes do Condado de Miles durante uma pacífica véspera de Natal.', 124, NULL, '/tBMH2u9ERs4CWW19ep6sJA9JCLr.jpg', '/bHfGHipZ32Oec94FDJO4mWs3aZ5.jpg', 6.7, 2111, 17.84, 'en', 61, 22, 60, 67, 36, 50, 40, 52, 50, 1, '2026-11-18 19:15:24'),
(306, 411, 'filme', 'As Crônicas de Nárnia: O Leão, a Feiticeira e o Guarda-Roupa', 'The Chronicles of Narnia: The Lion, the Witch and the Wardrobe', 2005, 'Durante os bombardeios da Segunda Guerra Mundial de Londres, quatro irmãos ingleses são enviados para uma casa de campo onde eles estarão seguros. Um dia, Lucy encontra um guarda-roupa que a transporta para um mundo mágico chamado Nárnia. Depois de voltar, ela logo volta a Nárnia com seus irmãos, Peter e Edmund, e sua irmã, Susan. Lá eles se juntam ao leão mágico, Aslan, na luta contra a Feiticeira Branca.', 143, NULL, '/sDBziWxSTavCNjbayaXaDDwmTiQ.jpg', '/tuDhEdza074bA497bO9WFEPs6O6.jpg', 7.1, 11936, 17.79, 'en', 55, 86, 100, 69, 72, 50, 100, 69, 83, 1, '2026-11-18 19:15:24'),
(307, 228150, 'filme', 'Corações de Ferro', 'Fury', 2014, 'Durante o final da Segunda Guerra Mundial, um grupo de cinco soldados americanos é encarregado de atacar os nazistas dentro da própria Alemanha. Apesar de estarem em quantidade inferior e terem poucas armas, eles são liderados pelo enfurecido Wardaddy, sargento que pretende levá-los à vitória, enquanto ensina o novato Norman a lutar.', 135, NULL, '/tVZXsjBC9HIoKv6WnAv0nWObbrT.jpg', '/95ckrV6wQgbffurAVmETQ5YKASL.jpg', 7.5, 13442, 17.77, 'en', 47, 14, 58, 77, 60, 50, 90, 39, 83, 1, '2026-11-18 19:15:25'),
(308, 283995, 'filme', 'Guardiões da Galáxia - Vol. 2', 'Guardians of the Galaxy Vol. 2', 2017, 'Os Guardiões precisam lutar para manter sua recém descoberta família unida, enquanto descobrem os mistérios sobre o verdadeiro pai de Peter Quill.', 136, NULL, '/jGtBLu0JAKf5JxhWgmF68HROzCA.jpg', '/aJn9XeesqsrSLKcHfHP4u5985hn.jpg', 7.6, 23771, 17.63, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:15:26'),
(309, 572802, 'filme', 'Aquaman 2: O Reino Perdido', 'Aquaman and the Lost Kingdom', 2023, 'Agora mais temível do que nunca, Arraia Negra detém o poder do mítico Tridente Preto e sua ancestral força malévola. Para derrotá-lo, Aquaman recorrerá a seu irmão Orm, o ex-Rei da Atlântida, ainda na prisão, para forjar uma aliança improvável. Juntos, eles vão ter que deixar de lado suas diferenças para proteger seu reino, salvar a família de Aquaman e o mundo da irreversível destruição.', 124, NULL, '/2Mys5JCHhUH6DE9YxLFFZaCsOHu.jpg', '/bckxSN9ueOgm0gJpVJmPQrecWul.jpg', 6.5, 3774, 17.55, 'en', 59, 76, 100, 100, 56, 50, 100, 70, 83, 1, '2026-11-18 19:15:26'),
(310, 285, 'filme', 'Piratas do Caribe: No Fim do Mundo', 'Pirates of the Caribbean: At World\'s End', 2007, 'Will Turner e Elizabeth Swann unem forças com o Capitão Barbossa para libertarem Jack Sparrow da prisão de Davy Jones. Enquanto isso, a tripulação do barco fantasma O Holandês Voador causa estragos nos Sete Mares. Os amigos devem navegar através de águas perigosas para enfrentarem o pirata chinês São Feng e, finalmente, eles devem escolher em que lado ficar na batalha, pois a vida do pirata está em jogo.', 169, NULL, '/j15lZasREutscon6e61LSSNJoN7.jpg', '/1jHxkVXMI5s3vRiyiZooUy1shB5.jpg', 7.3, 16078, 17.54, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:15:27'),
(311, 102382, 'filme', 'O Espetacular Homem-Aranha 2: A Ameaça de Electro', 'The Amazing Spider-Man 2', 2014, 'O jovem Peter Parker está fascinado com as habilidades que adquiriu como Homem-Aranha. Agora, ele precisa lidar com dois problemas: o retorno de um velho amigo, Harry Osborn, e a chegada de um vilão mais forte e poderoso, Electro.', 141, NULL, '/cyMz4OfmNqpuQ02QQOQCbGxQjwK.jpg', '/k0hlAzTryCYX1O1LyC6P8tAa8s0.jpg', 6.6, 14977, 17.52, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:15:28'),
(312, 315162, 'filme', 'Gato de Botas 2: O Último Pedido', 'Puss in Boots: The Last Wish', 2022, 'O Gato de Botas descobre que sua paixão pela aventura cobrou seu preço: ele queimou oito de suas nove vidas, deixando-o com apenas uma vida restante. Gato parte em uma jornada épica para encontrar o mítico Último Desejo e restaurar suas nove vidas.', 103, NULL, '/atJxZfCaQ7kXRFSfbm8cqAKkns7.jpg', '/jr8tSoJGj33XLgFBy6lmZhpGQNu.jpg', 8.2, 9397, 17.52, 'en', 67, 100, 100, 85, 80, 50, 100, 70, 100, 1, '2026-11-18 19:15:28'),
(313, 489, 'filme', 'Gênio Indomável', 'Good Will Hunting', 1997, 'Um professor do MIT descobre que um faxineiro da universidade é um gênio da matemática, e um psicólogo pouco ortodoxo ajuda o jovem a desenvolver seu potencial.', 126, NULL, '/dTe3EpJGnfUeR5swLbWv61iRyFc.jpg', '/xj1Sv1xm4Y0ydBueGuf10Y9qM0O.jpg', 8.2, 14609, 17.43, 'en', 46, 30, 50, 39, 44, 50, 47, 49, 50, 1, '2026-11-18 19:15:29'),
(314, 1124, 'filme', 'O Grande Truque', 'The Prestige', 2006, 'No século 19, em Londres, dois amigos ilusionistas e mágicos, Alfred Borden e Rupert Angier, acabam construindo uma rivalidade, uma batalha por supremacia, que se estende ao longo dos anos e que se transforma em obsessão, cujos resultados serão inevitavelmente trágicos.', 131, NULL, '/4AUW2bGbQjWACUREckGJWXmyF0d.jpg', '/yaExZh6qE2cfyK3o4kAMEq0mkgy.jpg', 8.2, 18485, 17.39, 'en', 67, 26, 84, 39, 32, 82, 58, 85, 83, 1, '2026-11-18 19:15:29'),
(315, 38757, 'filme', 'Enrolados', 'Tangled', 2010, 'O bandido mais procurado do reino, Flynn Rider, se esconde em uma torre e imediatamente se torna prisioneiro de Rapunzel, residente de longa data do local. Dona de cabelos dourados mágicos com 21 metros de comprimento, ela está trancada há anos e quer, desesperadamente, a liberdade. A adolescente determinada faz um acordo com o rapaz, e, juntos, partem para uma aventura emocionante.', 101, NULL, '/wZzVkdnc0kw20lSJc13ZmgTPah3.jpg', '/cWczNud8Y8i8ab0Z4bxos4myWYO.jpg', 7.6, 12889, 17.34, 'en', 65, 94, 100, 75, 72, 50, 92, 59, 83, 1, '2026-11-18 19:15:30'),
(316, 425, 'filme', 'A Era do Gelo', 'Ice Age', 2002, 'Vinte mil anos atrás, num mundo coberto de gelo, o mamute Manfred e a preguiça Sid resgatam um bebê humano órfão. Agora, os dois vão enfrentar muitas aventuras até devolver o filhote de gente à sua tribo, que migrou para um novo acampamento.', 82, NULL, '/dlqC2gJs02gc23XvyOjoz52ToRI.jpg', '/tyVAGH1vw9JDgxPyTUQPn91nIYc.jpg', 7.4, 14835, 17.33, 'en', 59, 100, 100, 85, 80, 50, 82, 59, 100, 1, '2026-11-18 19:15:31'),
(317, 419430, 'filme', 'Corra!', 'Get Out', 2017, 'Agora que Chris e sua namorada, Rose, chegaram à fase de conhecer os pais no namoro, ela o convida para um fim de semana no interior com Missy e Dean. A princípio, Chris acha que o comportamento excessivamente agradável dos dois como tentativas nervosas de lidar com o relacionamento inter-racial da filha, mas, conforme o fim de semana avança, uma série de descobertas cada vez mais perturbadoras o levam a uma verdade que ele jamais poderia ter imaginado.', 104, NULL, '/A0RoSZh8PEYJgDMgM2EV7Ycz3dR.jpg', '/bBQHALHRAaaORlPNXv7fNcRXYdx.jpg', 7.6, 19662, 17.31, 'en', 71, 12, 60, 97, 8, 86, 48, 52, 83, 1, '2026-11-18 19:15:31'),
(318, 939243, 'filme', 'Sonic 3: O Filme', 'Sonic the Hedgehog 3', 2024, 'Sonic, Knuckles e Tails se reúnem contra um novo e poderoso adversário, Shadow, um vilão misterioso com poderes diferentes de tudo que eles já enfrentaram antes. Com suas habilidades superadas em todos os sentidos, a Equipe Sonic deve buscar uma aliança improvável na esperança de parar Shadow e proteger o planeta.', 110, NULL, '/tfM1T6tAivjvy0sLwt6Y9WvlmzB.jpg', '/zOpe0eHsq0A2NvNyBbtT6sj53qV.jpg', 7.6, 3553, 17.29, 'en', 59, 100, 98, 99, 86, 58, 90, 86, 100, 1, '2026-11-18 19:15:32'),
(319, 1288069, 'filme', 'Tenzing', 'Tenzing', 2026, 'Um homem determinado embarca em uma jornada arriscada e desafia probabilidades aparentemente impossíveis para realizar seu sonho de ser o primeiro a chegar ao cume do Monte Everest.', 125, NULL, '/mn0WjDcQhVeWgIiHhmV1WO6tkpY.jpg', '/tKvVgMfM6GS4AGZn2KhP8bX1mJm.jpg', 8.2, 292, 17.29, 'en', 35, 38, 68, 39, 44, 50, 78, 28, 83, 1, '2026-11-18 19:15:32'),
(320, 519182, 'filme', 'Meu Malvado Favorito 4', 'Despicable Me 4', 2024, 'Nesta sequência, o vilão mais amado do planeta retorna e agora Gru, Lucy, Margo, Edith e Agnes dão as boas-vindas a um novo membro da família: Gru Jr., que pretende atormentar seu pai. Enquanto se adapta com o pequeno, Gru enfrenta um novo inimigo, Maxime Le Mal, forçando sua namorada Valentina e a família a fugir do perigo.', 94, NULL, '/s8BefU3RIJrfipTpsDtOiatlp8j.jpg', '/twsxsfao6ZOVvT8LfudH603MMi6.jpg', 6.9, 3460, 17.29, 'en', 73, 100, 100, 99, 86, 58, 96, 86, 100, 1, '2026-11-18 19:15:33');
INSERT INTO catalogo_obras (id, tmdb_id, tipo, titulo, titulo_original, ano, sinopse, duracao, temporadas, poster_path, backdrop_path, nota, votos, popularidade, idioma_original, eixo_1, eixo_2, eixo_3, eixo_4, eixo_5, eixo_6, eixo_7, eixo_8, confianca, ativo, atualizado_em) VALUES
(321, 950028, 'filme', 'O Convite', 'The Invite', 2026, 'O casamento de Joe e Angela está por um fio. Quando eles convidam seus enigmáticos vizinhos do andar de cima para um jantar, a noite toma rumos inesperados e o que prometia ser uma noite tranquila rapidamente descarrila. Os vizinhos trazem uma proposta inesperada e provocativa que obriga os dois casais a confrontarem seus desejos, intimidades e crises existenciais', 107, NULL, '/yXLx87GoPrM1ofZyIdFJOaqCjKP.jpg', '/lEwqBGNR65KZv6Ej5ufcmhZu2y2.jpg', 7.2, 976, 17.28, 'en', 41, 80, 50, 35, 58, 50, 22, 46, 83, 1, '2026-11-18 19:15:34'),
(322, 9806, 'filme', 'Os Incríveis', 'The Incredibles', 2004, 'Beto Pêra e sua mulher Helena estavam entre os maiores super-heróis do mundo, salvando inúmeras vidas e combatendo o mal diariamente. Quinze anos depois, eles foram forçados a adotar novas identidades e a mudar-se para o subúrbio, onde vivem como cidadãos comuns com seus três filhos, Violeta, Flecha e Zezé. Louco para voltar à ação, Beto tem a sua chance quando uma misteriosa ligação o intima a comparecer a uma ilha distante para receber uma missão ultra-secreta. Ele logo descobre que só uma família inteira de super-heróis será capaz de salvar o mundo e…', 115, NULL, '/z8k5EhZZTLsCRF8NWjSe6snWNZg.jpg', '/lxwzY9vNwjDgxWKt3zZ6zcU6rEJ.jpg', 7.7, 19554, 17.17, 'en', 65, 100, 100, 100, 78, 50, 100, 59, 100, 1, '2026-11-18 19:15:34'),
(323, 1301421, 'filme', 'As Ovelhas Detetives', 'The Sheep Detectives', 2026, 'George é um pastor que lê romances policiais para suas queridas ovelhas todas as noites, acreditando que elas não conseguem entender. Mas, quando um incidente misterioso interrompe a vida na fazenda, as ovelhas percebem que precisam se tornar as detetives. Ao seguir as pistas e investigar suspeitos humanos, elas provam que até mesmo ovelhas podem ser brilhantes solucionadoras de crimes.', 109, NULL, '/crW4rarCRUVRSRFy3Bufw8Mwf8l.jpg', '/g6uEVedSBXsZ3QuXKP4WDCeSsOy.jpg', 7.9, 1943, 17.15, 'en', 55, 100, 56, 73, 68, 74, 54, 52, 83, 1, '2026-11-18 19:15:35'),
(324, 490132, 'filme', 'Green Book: O Guia', 'Green Book', 2018, 'Quando Tony Lip, um segurança ítalo-americano, é contratado como motorista do Dr. Don Shirley, um pianista negro de classe alta, durante uma turnê pelo sul dos Estados Unidos, eles devem seguir o \"O Guia\" para leva-los aos poucos estabelecimentos que eram seguros para os afro-americanos. Confrontados com o racismo, o perigo, assim como pela humanidade e o humor inesperados, eles são forçados a deixar de lado as diferenças para sobreviver e prosperar nessa jornada.', 131, NULL, '/u9dldwRwQjTZGlIxKaAtAPLAjOv.jpg', '/5En0fmDagt3Pk8d7P3uTwfeQceg.jpg', 8.2, 13506, 17.11, 'en', 33, 60, 50, 37, 52, 50, 52, 20, 83, 1, '2026-11-18 19:15:36'),
(325, 1304313, 'filme', 'Maldição da Múmia', 'Lee Cronin\'s The Mummy', 2026, 'A filha de um jornalista desaparece num deserto sem deixar rastros, deixando a família dilacerada e em luto. Até que, oito anos mais tarde, a jovem garota reaparece, deixando todos chocados. O problema é que esse encontro aparentemente feliz se transforma em um pesadelo de proporções gigantes.', 133, NULL, '/fI6XBw8k5CWNwxLEYZwpjA89TPg.jpg', '/xugEpZk9YQ0DIz1aFvH5HGkqpZK.jpg', 7.8, 2874, 17.06, 'en', 71, 22, 60, 73, 24, 74, 40, 52, 67, 1, '2026-11-18 19:15:36'),
(326, 10020, 'filme', 'A Bela e a Fera', 'Beauty and the Beast', 1991, 'Em uma pequena aldeia da França vive Bela, uma jovem inteligente que é considerada estranha pelo moradores da localidade, e seu pai, Maurice, um inventor que é visto como um louco. Ela é cortejada por Gaston, que quer casar com ela. Mas apesar de todas as jovens do lugarejo o acharem um homem bonito, Bela não o suporta, pois vê nele uma pessoa primitiva e convencida. Quando o pai de Bela vai para uma feira demonstrar sua nova invenção, ele acaba se perdendo na floresta e é atacado por lobos. Desesperado, Maurice procura abrigo em um castelo, mas acaba…', 110, NULL, '/is4c02QuP70BCVLp27SSlDeByoe.jpg', '/fW4ZCoEZRBqLAJGFQ2g5AdAfPQR.jpg', 7.7, 11047, 17, 'en', 72, 100, 100, 43, 78, 50, 79, 53, 100, 1, '2026-11-18 19:15:37'),
(327, 505642, 'filme', 'Pantera Negra: Wakanda para Sempre', 'Black Panther: Wakanda Forever', 2022, 'A rainha Ramonda, Shuri, M\'Baku, Okoye e as poderosas Dora Milaje lutam para proteger sua nação após a morte do rei T\'Challa. Com a ajuda da Cão de Guerra Nakia e de Everett Ross, eles tentam encontrar um novo caminho para Wakanda.', 162, NULL, '/cryEN3sWlgB2wTzcUNVtDGI8bkM.jpg', '/83H0C66AcvkwpG2738VCTHMY9uv.jpg', 7, 7953, 16.94, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:15:37'),
(328, 822119, 'filme', 'Capitão América: Admirável Mundo Novo', 'Captain America: Brave New World', 2025, 'Após se encontrar com o recém-eleito presidente dos EUA, Thaddeus Ross, Sam se vê no meio de um incidente internacional. Ele deve descobrir o motivo por trás de uma conspiração global nefasta antes que o verdadeiro gênio faça o mundo inteiro ser dominado pelo vermelho.', 119, NULL, '/5nbSgP8f5LMCI0PwVRRaHJaUmR3.jpg', '/ce3prrjh9ZehEl5JinNqr4jIeaB.jpg', 5.9, 3626, 16.93, 'en', 65, 48, 92, 100, 40, 70, 100, 86, 83, 1, '2026-11-18 19:15:38'),
(329, 337167, 'filme', 'Cinquenta Tons de Liberdade', 'Fifty Shades Freed', 2018, 'Superados os principais problemas, Anastasia e Christian agora têm amor, intimidade, dinheiro, sexo, relacionamento estável e um promissor futuro. A vida, no entanto, ainda reserva surpresas para os dois e fantasmas do passado como Jack Hyde e Elena Lincoln voltam a impedir a paz do casal.', 101, NULL, '/xnaSOAq3oaAbMrsgFe9LWYGE7eP.jpg', '/9ywA15OAiwjSTvg3cBs9B7kOCBF.jpg', 6.7, 8471, 16.92, 'en', 47, 50, 50, 25, 50, 50, 32, 46, 67, 1, '2026-11-18 19:15:39'),
(330, 1477104, 'filme', 'Shaun, o Carneiro: A Fera de Mossy Bottom', 'Shaun the Sheep: The Beast of Mossy Bottom', 2026, 'Na véspera do Halloween, na Fazenda Mossy Bottom, a empolgação se transforma em desespero quando o desastrado Fazendeiro destrói o canteiro de abóboras. Shaun tenta consertar a situação com experimentos científicos, mas as coisas saem do controle quando uma fera selvagem surge na floresta.', 81, NULL, '/iV0locT4MZ5s0dLEGVhkEMMwC9H.jpg', '/mG8tVv1RPAKnARWxKTND5dRgMpw.jpg', 7.3, 62, 16.91, 'en', 69, 100, 100, 61, 80, 58, 72, 86, 100, 1, '2026-11-18 19:15:39'),
(331, 1062722, 'filme', 'Frankenstein', 'Frankenstein', 2025, 'Dr. Victor Frankenstein, um cientista brilhante, mas egoísta, dá vida a uma criatura em um experimento monstruoso que acaba levando à ruína tanto do criador quanto de sua trágica criação.', 149, NULL, '/rB0tZwNImTT8febX5qVycZ5YVeF.jpg', '/hpXBJxLD2SEf8l2CspmSeiHrBKX.jpg', 7.6, 4087, 16.76, 'en', 65, 8, 96, 49, 30, 50, 52, 62, 83, 1, '2026-11-18 19:15:40'),
(332, 78, 'filme', 'Blade Runner: O Caçador de Andróides', 'Blade Runner', 1982, 'No início do século 21, uma grande corporação desenvolve um robô que é mais forte e ágil que o ser humano e se equiparando em inteligência. São conhecidos como \"replicantes\" e utilizados como escravos na colonização e exploração de outros planetas. Mas, quando um grupo dos robôs mais evoluídos provoca um motim em uma colônia fora da Terra, este incidente faz os replicantes serem considerados ilegais na Terra, sob pena de morte. A partir de então, policiais de um esquadrão de elite conhecidos como \"Blade Runner\", têm ordem de atirar para matar em…', 117, NULL, '/y5ibL0vFnzsRiIHosw0WOfHtIj1.jpg', '/2spEHYDcyE9r9mS7AFEscfKVDzO.jpg', 7.9, 15652, 16.74, 'en', 60, 20, 84, 63, 28, 70, 73, 83, 83, 1, '2026-11-18 19:15:40'),
(333, 1430077, 'filme', 'Hokum: O Pesadelo da Bruxa', 'Hokum', 2026, 'O escritor solitário Ohm Bauman refugia-se em um hotel isolado para cumprir o último desejo de seus pais. A despedida silenciosa transforma-se em pesadelo quando histórias sobre uma antiga bruxa que assombra a suíte de lua de mel passam a invadir seus sonhos e sua mente. Entre visões perturbadoras e um desaparecimento chocante, Ohm é levado a um confronto aterrorizante com as forças que cercam o local e com os cantos mais sombrios de seu próprio passado.', 108, NULL, '/fn5QNtG3LLXC3e7ZTQDYP92kFYc.jpg', '/1FYdbchGR8WTNlneJ3Pvol5hbGE.jpg', 6.8, 1072, 16.72, 'en', 61, 12, 60, 91, 20, 62, 48, 52, 67, 1, '2026-11-18 19:15:41'),
(334, 10195, 'filme', 'Thor', 'Thor', 2011, 'Como filho de Odin, rei dos deuses nórdicos, Thor logo herdará o trono de Asgard de seu idoso pai. Porém, no dia de sua coroação, Thor reage com brutalidade quando os inimigos dos deuses entram no palácio violando o tratado. Como punição, Odin manda Thor para a Terra. Enquanto seu irmão Loki conspira em Asgard, Thor, agora sem seus poderes, enfrenta sua maior ameaça.', 115, NULL, '/aEV9QmgBqjRTdjsvdCgdK89tavQ.jpg', '/cDJ61O1STtbWNBwefuqVrRe3d7l.jpg', 6.8, 23087, 16.68, 'en', 59, 76, 100, 100, 56, 50, 100, 69, 83, 1, '2026-11-18 19:15:42'),
(335, 9502, 'filme', 'Kung Fu Panda', 'Kung Fu Panda', 2008, 'Po é um panda que trabalha na loja de macarrão da sua família e sonha em transformar-se em um mestre de kung fu. Seu sonho se torna realidade quando, inesperadamente, ele deve cumprir uma profecia antiga e estudar a arte marcial com seus ídolos, os Cinco Furiosos. Po precisa de toda a sabedoria, força e habilidade que conseguir reunir para proteger seu povo de um leopardo da neve malvado.', 95, NULL, '/1YMs3zCt5kICK28RvVgDL1UUtkA.jpg', '/qdthf9WrRDSaIkGVQGhhJ9pz1hn.jpg', 7.3, 13207, 16.65, 'en', 59, 100, 90, 99, 86, 50, 78, 51, 100, 1, '2026-11-18 19:15:42'),
(336, 284053, 'filme', 'Thor: Ragnarok', 'Thor: Ragnarok', 2017, 'Thor está preso do outro lado do universo. Ele precisa correr contra o tempo para voltar a Asgard e parar Ragnarok, a destruição de seu mundo, que está nas mãos da poderosa e implacável vilã Hela.', 131, NULL, '/2K45Fp6koAVoeeYS6aMb9BeNt4F.jpg', '/vLmHH8jAy8Jq8uBsLucd3592WGh.jpg', 7.6, 22783, 16.6, 'en', 59, 100, 100, 100, 64, 58, 100, 94, 100, 1, '2026-11-18 19:15:43'),
(337, 6977, 'filme', 'Onde os Fracos Não Têm Vez', 'No Country for Old Men', 2007, 'Quando um homem se depara com a sangrenta cena de um crime, uma caminhonete carregada de heroína e irresistíveis dois milhões de dólares, sua decisão de levar o dinheiro deflagra uma interminável e violenta reação em cadeia, que nem a lei do Oeste do Texas pode deter.', 122, NULL, '/jdlY8Bhcb4Qzfldr1JaexYBgyW3.jpg', '/fCCvn3xsG29TGKJPvZgTRppsDgk.jpg', 7.9, 14095, 16.54, 'en', 45, 40, 42, 77, 10, 62, 76, 21, 83, 1, '2026-11-18 19:15:44'),
(338, 118, 'filme', 'A Fantástica Fábrica de Chocolate', 'Charlie and the Chocolate Factory', 2005, 'Willy Wonka é o excêntrico dono da maior fábrica de doces do planeta, que decide realizar um concurso mundial para escolher um herdeiro para seu império. Cinco crianças de sorte, entre elas Charlie Bucket, encontram um convite dourado em barras de chocolate Wonka e com isso ganham uma visita guiada pela lendária fábrica de chocolate, que não era visitada por ninguém há quinze anos.', 111, NULL, '/vSl1u0z4TCKL4VPVyr6KDtZibYT.jpg', '/atoIgfAk2Ig2HFJLD0VUnjiPWEz.jpg', 7, 16584, 16.53, 'en', 49, 100, 100, 79, 80, 50, 92, 69, 100, 1, '2026-11-18 19:15:44'),
(339, 949, 'filme', 'Fogo Contra Fogo', 'Heat', 1995, 'O ladrão obsessivo Neil McCauley lidera uma equipe de primeira linha em vários assaltos ousados ​​por Los Angeles, enquanto o determinado detetive Vincent Hanna o persegue sem descanso. Cada homem reconhece e respeita a capacidade e a dedicação do outro, mesmo sabendo que o seu jogo de gato e rato pode terminar em violência.', 170, NULL, '/fv2mQTMJxjMY5EKG3epvjuVUVKJ.jpg', '/uI22JkEMediWyiRqhllNqeeGtW0.jpg', 7.9, 8911, 16.53, 'en', 50, 38, 50, 77, 22, 50, 57, 49, 83, 1, '2026-11-18 19:15:45'),
(340, 857, 'filme', 'O Resgate do Soldado Ryan', 'Saving Private Ryan', 1998, 'Ao desembarcar na Normandia, no dia 6 de junho de 1944, o capitão Miller recebe a missão de comandar um grupo do segundo batalhão para o resgate do soldado James Ryan, caçula de quatro irmãos, dentre os quais três morreram em combate. Por ordens do chefe George C. Marshall, eles precisam procurar o soldado e garantir o seu retorno, com vida, para casa.', 170, NULL, '/hMLxNLCXRDd62acfCBn6mIyW1HU.jpg', '/rW2xRFlJRbTnBJlQTSjQmjevIwb.jpg', 8.2, 18098, 16.51, 'en', 38, 6, 50, 33, 54, 50, 89, 5, 83, 1, '2026-11-18 19:15:45'),
(341, 120467, 'filme', 'O Grande Hotel Budapeste', 'The Grand Budapest Hotel', 2014, 'No período entre as duas guerras mundiais, o famoso gerente de um hotel europeu conhece um jovem empregado e os dois tornam-se melhores amigos. Entre as aventuras vividas pelos dois, constam o roubo de um famoso quadro do Renascimento, a batalha pela grande fortuna de uma família e as transformações históricas durante a primeira metade do século XX.', 100, NULL, '/yabOguSrb8ffUXCkI6t8Rw7xtSh.jpg', '/jK65srQczOKTpW62wPxwwKztGgE.jpg', 8, 16767, 16.4, 'en', 41, 60, 50, 49, 52, 50, 36, 51, 67, 1, '2026-11-18 19:15:46'),
(342, 1433583, 'filme', 'O Peso da Liberdade', 'The Weight', 2026, 'Quando Samuel é separado da filha e enviado para uma prisão brutal, o diretor Clancy faz-lhe uma proposta arriscada: contrabandear ouro de uma mina remota juntamente com um perigoso grupo de reclusos e, em troca, conquistar a sua liberdade.', 113, NULL, '/ruFMBq3r5MhdDoYDcGAqy795Rw2.jpg', '/4klejBUCWsq2F9GHB5EH5mQdFOg.jpg', 6.6, 103, 16.38, 'en', 47, 20, 50, 63, 28, 62, 54, 52, 67, 1, '2026-11-18 19:15:47'),
(343, 38, 'filme', 'Brilho Eterno de uma Mente sem Lembranças', 'Eternal Sunshine of the Spotless Mind', 2004, 'Joel se surpreende ao saber que seu amor verdadeiro, Clementine, o apagou completamente de sua memória. Ele decide fazer o mesmo, mas muda de ideia. Preso dentro da própria mente enquanto os especialistas se mantêm ocupados em seu apartamento, Joel precisa avisá-los para parar.', 108, NULL, '/zqbwK2ugTPauBQwzcNAM3PxVoww.jpg', '/95qi5TJMIBI5VzWHia88Pbrye7Z.jpg', 8.1, 17005, 16.38, 'en', 61, 50, 84, 25, 50, 58, 50, 79, 83, 1, '2026-11-18 19:15:47'),
(344, 399566, 'filme', 'Godzilla vs. Kong', 'Godzilla vs. Kong', 2021, 'Em uma época em que os monstros andam na Terra, a luta da humanidade por seu futuro coloca Godzilla e Kong em rota de colisão que verá as duas forças mais poderosas da natureza no planeta se confrontarem em uma batalha espetacular para as idades. Enquanto Monarch embarca em uma missão perigosa em terreno desconhecido e descobre pistas sobre as origens dos Titãs, uma conspiração humana ameaça tirar as criaturas, boas e más, da face da terra para sempre.', 114, NULL, '/teW53VSLdZMMSmkn5xBBowu3tEr.jpg', '/wWqTMWkEw6HouLd1zPZbZWxtAPr.jpg', 7.5, 10946, 16.35, 'en', 65, 70, 100, 100, 56, 58, 100, 94, 83, 1, '2026-11-18 19:15:48'),
(345, 10588, 'filme', 'O Gato', 'The Cat in the Hat', 2003, 'Conrad e Sally são dois irmãos que, num dia chuvoso, estão em casa sem ter nada para fazer. A única diversão da dupla é ficar brincando com o animal de estimação deles, um peixe. Até que surge um gato travesso, de cartola vermelha e branca, que leva a dupla a um incrível mundo de imaginação.', 82, NULL, '/doGqNxkbvJ5igyWWDRA0B0bmZnw.jpg', '/ihOd5W6qOgrBSLj0uDTnGs8k1aa.jpg', 5.4, 1941, 16.32, 'en', 53, 100, 100, 85, 80, 50, 98, 69, 100, 1, '2026-11-18 19:15:49'),
(346, 1279493, 'filme', 'O Último Grande Assalto', 'The Get Out', 2026, 'Um dono de clube enfrenta perigos dos cartéis após um assalto que ameaça seus planos de aposentadoria. Enquanto a situação se agrava, um comprador misterioso surge, complicando seu sonho de vender o clube e se aposentar com a namorada.', 111, NULL, '/keU6EsXrkcc1uAEsEt1pI8keSsO.jpg', '/9Bv4Oki9u3aKZxDCNDcU4N2mttb.jpg', 6.1, 166, 16.31, 'en', 51, 48, 58, 100, 40, 62, 82, 52, 67, 1, '2026-11-18 19:15:49'),
(347, 284052, 'filme', 'Doutor Estranho', 'Doctor Strange', 2016, 'Após sua carreira ser destruída, um brilhante, porém arrogante, cirurgião ganha uma nova chance em sua vida quando um feiticeiro o treina para se tornar o Mago Supremo.', 115, NULL, '/pb4clPWRJ5AKlSFu1HrrHdt5uAw.jpg', '/kkoiH8ZWxJ9WSAjOadGtuHUQxbm.jpg', 7.4, 24223, 16.27, 'en', 59, 76, 100, 100, 56, 50, 100, 70, 83, 1, '2026-11-18 19:15:50'),
(348, 562, 'filme', 'Duro de Matar', 'Die Hard', 1988, 'O policial de Nova York John McClane está visitando sua família no Natal. Ele participa de uma confraternização de fim de ano na sede da empresa japonesa em que a esposa trabalha. A festa é interrompida por terroristas que invadem o edifício de luxo. McClane não demora a perceber que não há ninguém para salvá-los, a não ser ele próprio.', 132, NULL, '/2PD0HHoyVVAEUhep9JhlKtgyl8m.jpg', '/bvk2AAH64lP2YZs02Q3jskfHT8j.jpg', 7.8, 12883, 16.25, 'en', 50, 48, 58, 100, 40, 62, 83, 49, 67, 1, '2026-11-18 19:15:51'),
(349, 1724, 'filme', 'O Incrível Hulk', 'The Incredible Hulk', 2008, 'Vivendo escondido e longe de Betty Ross, a mulher que ama, o cientista Bruce Banner busca um meio de retirar a radiação gama que está em seu sangue. Ao mesmo tempo ele precisa fugir da perseguição do general Ross, seu grande inimigo, e da máquina militar que tenta capturá-lo, na intenção de explorar o poder que faz com que Banner se transforme no Hulk.', 120, NULL, '/v1UXe9WlwkkZ5YrffUSPdYNeJz3.jpg', '/xfBnQ4mgf1jYZsscJGJjr6ce0Ar.jpg', 6.3, 13371, 16.16, 'en', 65, 70, 100, 100, 56, 58, 100, 93, 83, 1, '2026-11-18 19:15:51'),
(350, 18239, 'filme', 'A Saga Crepúsculo: Lua Nova', 'The Twilight Saga: New Moon', 2009, 'Logo após Bella Swan completar 18 anos, Edward Cullen decide deixá-la para trás em um esforço para protegê-la após um ataque que quase tirou sua vida. Com uma tristeza inconsolável, Bella descobre que ela pode chamar a imagem de Edward sempre que se coloca em perigo e seu desejo em estar com ele a leva a assumir riscos cada vez maiores. Com a ajuda de Jacob Black, seu amigo de infância e um membro da misteriosa tripo Quileute, o coração de Bella vai gradualmente descongelando, enquanto Jacob esconde seu próprio segredo sobrenatural. Ao receber a notícia…', 131, NULL, '/z39dbVwa1iIihdUDHGiRy4tc2Ov.jpg', '/dF2c20sRDgySZLaLS2OUerL07sz.jpg', 6, 10023, 16.16, 'en', 55, 68, 100, 43, 50, 50, 76, 63, 100, 1, '2026-11-18 19:15:52'),
(351, 5920, 'serie', 'O Mentalista', 'The Mentalist', 2008, 'Patrick Jane é famoso por sua habilidade de alta percepção de tudo que está ao seu redor. Ele já quase foi uma celebridade, alegando ser médium vidente, mas agora admite que fingia ter poderes paranormais. Com sua grande habilidade de observação, Patrick trabalha como consultor independente para as autoridades da Califórnia, resolvendo um número considerável de crimes complicados.', NULL, 7, '/bJ0SNoD0DchXo5nH3N81ABIe3H.jpg', '/rJFqKcmMSttdNP58l0dVzY2NcTA.jpg', 8.4, 5025, 2210.6, 'en', 61, 30, 42, 51, 4, 74, 38, 51, 83, 1, '2026-11-18 19:15:52'),
(352, 60735, 'serie', 'Flash', 'The Flash', 2014, 'Um perito forense desperta de um coma com poderes especiais que serão postos à prova na luta contra forças que ameaçam a cidade.', NULL, 9, '/lFxIoMKqkgTuxpghTPHBjoVstMV.jpg', '/gFkHcIh7iE5G0oVOgpmY8ONQjhl.jpg', 7.7, 11875, 2045.43, 'en', 55, 30, 84, 39, 44, 50, 62, 73, 67, 1, '2026-11-18 19:15:56'),
(353, 2734, 'serie', 'Lei & Ordem: Unidade de Vítimas Especiais', 'Law & Order: Special Victims Unit', 1999, 'Detetives que fazem parte da Unidade de Vítimas Especiais da polícia de Nova York investigam crimes de natureza sexual, como estupros, em que a vítima sobrevive, e auxilia as autoridades na investigação.', NULL, 28, '/nYkYmNFfKydgrcO45oNjOnW0FDJ.jpg', '/xhK9YCxNwnE0OB1SWvCY39heHQI.jpg', 8, 4423, 2003.09, 'en', 60, 30, 42, 51, 4, 74, 39, 49, 83, 1, '2026-11-18 19:15:56'),
(354, 1413, 'serie', 'American Horror Story', 'American Horror Story', 2011, 'Uma antologia dramática de terror trazendo a cada temporada novas histórias, cenários e personagens perturbadores.', NULL, 13, '/yCkPLQ10qKIUgRBXmQVVMF1h96d.jpg', '/5G4Bnc4Q0YUK1bwLEUYmIsmm2Ib.jpg', 8.1, 6308, 1907.63, 'en', 65, 30, 84, 45, 32, 74, 62, 73, 83, 1, '2026-11-18 19:15:57'),
(355, 84773, 'serie', 'O Senhor dos Anéis: Os Anéis de Poder', 'The Lord of the Rings: The Rings of Power', 2022, 'Tendo início em uma época de relativa paz, a série acompanha um grupo de personagens que enfrenta o ressurgimento do mal na Terra-média. Das profundezas escuras das Montanhas de Névoa, das majestosas florestas de Lindon, do belíssimo reino da ilha de Númenor, até os confins do mapa, esses reinos e personagens criarão legados que permanecerão vivos muito além de suas partidas.', NULL, 3, '/8FPCnfOftiLTHg5wnJxVdtlF8EN.jpg', '/uVOcz7JBOuZxsx9IYpx6Ah174LX.jpg', 7.2, 4102, 1865.51, 'en', 59, 60, 98, 83, 50, 50, 90, 74, 67, 1, '2026-11-18 19:15:58'),
(356, 1100, 'serie', 'Como Eu Conheci Sua Mãe', 'How I Met Your Mother', 2005, 'No ano de 2030, Ted Mosby, um arquiteto, decide explicar a seus filhos a história de como ele conheceu a mãe deles.', NULL, 9, '/578tlvbrpFwc959bQTT93W2RYA.jpg', '/3f8aW6vcYRP6mTZdgXm83BiuB9t.jpg', 8.1, 6090, 1761.36, 'en', 45, 80, 50, 67, 58, 50, 46, 51, 50, 1, '2026-11-18 19:15:58'),
(357, 1434, 'serie', 'Uma Família da Pesada', 'Family Guy', 1999, 'A série animada apresenta as aventuras da família Griffin. O ignorante Peter e sua esposa Lois residem em Quahog, em Rhode Island e têm três filhos. Meg, a filha mais velha, é uma pária social, e o adolescente Chris é estranho e sem noção quando se trata do sexo oposto. O mais novo, Stewie, é um bebê gênio decidido a matar sua mãe e destruir o mundo. O cachorro falante, Brian, mantém Stewie sob controle enquanto toma martinis e resolve seus próprios problemas de vida.', NULL, 24, '/j28XGzAhvJNGWEHbYrzvREw7kKd.jpg', '/jbTqU6BJMufoMnPSlO4ThrcXs3Y.jpg', 7.4, 5218, 1693.07, 'en', 58, 90, 76, 67, 58, 50, 53, 49, 67, 1, '2026-11-18 19:15:59'),
(358, 57243, 'serie', 'Doctor Who', 'Doctor Who', 2005, 'Acompanhe as incríveis jornadas pelo tempo e espaço do Doutor, um alienígena da linhagem dos senhores do tempo. Nativo do planeta Gallifrey, o Doutor utiliza a Tardis, uma nave capaz de se camuflar como uma cabine de polícia, para explorar o passado e o futuro nos mais distantes lugares do universo.', NULL, 13, '/8xz8ZPiuRLeaganjKd6WtE6S50E.jpg', '/vcFW09U4834DyFOeRZpsx9x1D3S.jpg', 7.6, 3517, 1666.44, 'en', 51, 36, 98, 59, 44, 50, 74, 73, 83, 1, '2026-11-18 19:16:00'),
(359, 2316, 'serie', 'The Office', 'The Office', 2005, 'Michael Scott é o egocêntrico, insensível e incompetente gerente regional de uma subsidiária da Dunder Mifflin Paper Company. Michael acredita ser o cara mais engraçado do escritório, uma fonte de sabedoria para negócios e o melhor amigo de seus funcionários. Ele nem desconfia que a sua equipe o tolera apenas pelo fato dele assinar o contracheque deles. Sem saber o que os seus funcionários pensam a seu respeito, Michael acaba sempre alternando decisões absurdas ou patéticas, mas sempre hilárias.', NULL, 9, '/50DVZEgPwGokQf4o0KHZGQMJqDD.jpg', '/9vMzIrMIncPmtalcxh1MOrgcE6C.jpg', 8.6, 5730, 1621.21, 'en', 45, 80, 50, 67, 58, 50, 46, 51, 50, 1, '2026-11-18 19:16:00'),
(360, 1421, 'serie', 'Família Moderna', 'Modern Family', 2009, 'Você consegue acreditar que todos eles são parentes? Nem eles! Modern Family nos traz uma divertida e inovadora visão do que significa criar uma família nesta época doida em que vivemos. Relacionamentos multiculturais, adoção e casamento de pessoas do mesmo sexo são apenas alguns dos assuntos atuais abordados por esta série que os analisa de modo divertido e sensível. Não importa o tamanho ou a formação, a família sempre vem no primeiro neste hilário modo de olhar \"moderno\" que foca a vida, o amor e as gargalhadas.', NULL, 11, '/gGOZeGx3ggP5O9qvswRPN7PRVWn.jpg', '/nO7EzksrBzlNpAg5rgv8HzaBIkx.jpg', 7.9, 3635, 1597.06, 'en', 45, 80, 50, 67, 58, 50, 46, 51, 50, 1, '2026-11-18 19:16:01'),
(361, 1622, 'serie', 'Sobrenatural', 'Supernatural', 2005, 'Os irmãos Dean e Sam vasculham o país em busca de atividades paranormais, brigando com demônios, fantasmas e monstros no caminho.', 45, 15, '/ovFzkkKknAo2SbM2DfOabxRvzmy.jpg', '/lirPqYLTtd6XZqGn4cS1wiesTq0.jpg', 8.3, 8841, 1570.47, 'en', 65, 30, 84, 45, 32, 74, 62, 73, 83, 1, '2026-11-18 19:16:01'),
(362, 1408, 'serie', 'Dr. House', 'House', 2004, 'O Dr. Gregory House é um médico genial, mas misantropo e viciado em analgésicos, que lidera uma equipe de diagnóstico em um hospital de Nova Jersey. Com um cinismo implacável e métodos pouco ortodoxos, ele trata os casos médicos mais raros e misteriosos como quebra-cabeças complexos, desafiando todos ao seu redor para chegar à verdade.', 44, 8, '/hsH0RgSIFW7oGTri5cGEw1VpfUA.jpg', '/r0Q6eeN9L1ORL9QsV0Sg8ZV3vnv.jpg', 8.6, 8050, 1551.13, 'en', 47, 30, 50, 39, 44, 50, 46, 51, 50, 1, '2026-11-18 19:16:02'),
(363, 1400, 'serie', 'Seinfeld', 'Seinfeld', 1989, 'Jerry e seus três amigos têm o poder de fazer rir não só nas situações ridículas, mas também nas situações corriqueiras.', NULL, 9, '/aCw8ONfyz3AhngVQa1E2Ss4KSUQ.jpg', '/tMRdEsMg9MyXAkcufK9YJEeIaNW.jpg', 8.2, 2528, 1538.51, 'en', 44, 80, 50, 67, 58, 50, 47, 49, 50, 1, '2026-11-18 19:16:03'),
(364, 18165, 'serie', 'Diários de um Vampiro', 'The Vampire Diaries', 2009, 'Elena tenta sobreviver entre os seres sobrenaturais que vivem em segredo. Ela se apaixona pelo misterioso Stefan, mas o retorno do seu irmão, Damon, ameaça essa paixão.', 43, 8, '/lcGQaSrWkkxGuh0JJqyN2TkuNqb.jpg', '/cJYLon9ejKJV7ua03ab8Tj9u067.jpg', 8.3, 9863, 1499.09, 'en', 55, 30, 84, 39, 44, 50, 62, 73, 67, 1, '2026-11-18 19:16:03'),
(365, 4057, 'serie', 'Mentes Criminosas', 'Criminal Minds', 2005, 'Um esquadrão de elite do FBI estuda as maiores mentes criminosas, antecipando seus próximos passos, antes que eles ataquem novamente. A fim de identificar as motivações dos criminosos e detê-los, cada membro da equipe usa a experiência que possui.', NULL, 19, '/trZTeHWcWDn6adkBBuSwfIhxAJn.jpg', '/tUtXfyVy54BY7eJnRtI8Xnmr1ZL.jpg', 8.3, 4230, 1471.83, 'en', 61, 30, 42, 51, 4, 74, 38, 51, 83, 1, '2026-11-18 19:16:04'),
(367, 456, 'serie', 'Os Simpsons', 'The Simpsons', 1989, 'Uma animação sobre uma típica família dos Estados Unidos. Homer é o pai de família nada saudável ou inteligente, que adora beber cerveja. Marge é a esposa e mãe de família dedicada. Bart é o filho de 10 anos, que não leva a escola a sério e tem orgulho disso. Lisa é a garota de 8 anos, um gênio não apreciado. E Maggie é a bebê que não larga a chupeta.', NULL, 38, '/1jGPgDDcmg3Xgs3WO8sfYfbnFoA.jpg', '/jIArNHIekrCSVgdMbKPAXpPY03Y.jpg', 8, 11184, 1389.91, 'en', 58, 90, 76, 67, 58, 50, 53, 49, 67, 1, '2026-11-18 19:16:05'),
(368, 1877, 'serie', 'Phineas e Ferb', 'Phineas and Ferb', 2007, 'Todos os dias, dois meio-irmãos nas férias de verão embarcam em um grande novo projeto, o que irrita sua irmã controladora, Candace, que sempre tenta entrega-los para sua mãe. Enquanto isso, seu animal de estimação Perry o ornitorrinco luta contra o malvado Dr. Doofenshmirtz.', NULL, 6, '/cu2nJgERq8ZmRUlBFPsamdJb7rh.jpg', '/5MWFjQ3NuNtNeOE9FdrVLeNMNPs.jpg', 7.9, 1094, 1311.97, 'en', 67, 100, 100, 67, 80, 50, 76, 73, 100, 1, '2026-11-18 19:16:06'),
(369, 32573, 'serie', 'Strike Back', 'Strike Back', 2010, 'Strike Back é o fruto de uma parceria Reino Unido e Estados Unidos que resultou em uma série de ação militar. A história segue as ações da Seção 20, um ramo secreto do serviço de defesa britânico que opera várias missões de alto risco, prioritárias em todo o mundo.', 45, 8, '/c0ItaC2Grf4WVJ06G87BjNn9pRs.jpg', '/2tL3pNaPQb2ioEYswMkDGVTo1pt.jpg', 7.4, 420, 1284.02, 'en', 43, 36, 64, 59, 44, 50, 58, 51, 67, 1, '2026-11-18 19:16:06'),
(370, 76331, 'serie', 'Succession', 'Succession', 2018, 'Acompanhe a história da família Roy, composta por Logan e seus quatro filhos, que controla um dos maiores conglomerados de meios de comunicação e entretenimento do mundo.', NULL, 4, '/z0XiwdrCQ9yVIr4O0pxzaAYRxdW.jpg', '/d87JXX3DLkRJMfm5StCmmnmhHuX.jpg', 8.3, 1858, 1226.54, 'en', 41, 60, 50, 49, 52, 50, 36, 52, 67, 1, '2026-11-18 19:16:07'),
(371, 83631, 'serie', 'O Que Fazemos Nas Sombras', 'What We Do in the Shadows', 2019, 'Um olhar sobre a vida cotidiana de quatro vampiros que estão juntos há centenas de anos. Após a visita de seu senhor e líder sombrio, eles são lembrados de seu propósito em vir a Nova York há mais de um século.', NULL, 6, '/cWsC3SWssTIBVxA2nZenacBgYh2.jpg', '/mKikck71CvVISUSTLk29fwRbH4y.jpg', 8, 1106, 1194.46, 'en', 53, 80, 84, 67, 58, 50, 62, 74, 67, 1, '2026-11-18 19:16:07'),
(372, 4620, 'serie', 'Eureka', 'Eureka', 2006, 'A cidade de Eureka, no noroeste do Pacífico, está escondendo um misterioso segredo. O governo tem relocado os gênios do mundo e suas famílias para esta cidade rústica há anos, onde a inovação e o caos têm vivido de mãos dadas. O marechal americano Jack Carter se depara com essa estranha cidade depois de destruir seu carro e ficar encalhado ali. Quando os habitantes da cidade se lançam sobre uma criação científica desconhecida, Carter pula para tentar restaurar a ordem e, consequentemente, aprende um dos segredos mais bem guardados do país.', 44, 5, '/f2l5hUk63hPqYTucnFy2HmElFV0.jpg', '/8MQeyFsWrp2ILjbumtxrinmk7t4.jpg', 7.7, 753, 1149.51, 'en', 49, 60, 84, 49, 52, 50, 52, 73, 83, 1, '2026-11-18 19:16:08'),
(373, 2025, 'serie', 'Barrados no Baile', 'Beverly Hills, 90210', 1990, 'Acompanhe os conflitos, tragédias, romances e dilemas de um grupo de jovens que moram na cidade rica e elitista de Beverly Hills, desde o ensino médio até a vida adulta. Eles se tornam amigos e inimigos, se apaixonam e se decepcionam, passam por triângulos amorosos e outras complicações românticas, têm problemas familiares e precisam tomar decisões sobre o futuro.', NULL, 10, '/HPGrWzYfFpIvQQtTl38YMUcjGM.jpg', '/iMFsQ7yyToYg7SkS9Ml0by9UJ0X.jpg', 7.2, 871, 1114.31, 'en', 46, 30, 50, 39, 44, 50, 47, 49, 50, 1, '2026-11-18 19:16:09'),
(374, 18347, 'serie', 'Community', 'Community', 2009, 'Sempre foi dito que universidades comunitárias são um meio escolar para perdedores, um workshop de auto-estima para donas-de-casa recém divorciadas e um lugar onde pessoas velhas vão para manter sua mente ocupada enquanto esperam pela morte. Bem, no Greendale Community College… Isso tudo é verdade! “Community” é focada em um grupo de desviados, onde o líder é um advogado que teve o grau revogado. Eles formam um grupo de estudo, onde acabam aprendendo mais sobre si mesmo, do que sobre a matéria cursada.', NULL, 6, '/3KUjDt8XY7w2Ku70UE0SECmv1zP.jpg', '/1xRfgONYmK3T6FSmbtcuo8eyxVt.jpg', 8, 2242, 1082.53, 'en', 45, 80, 50, 67, 58, 50, 46, 51, 50, 1, '2026-11-18 19:16:09'),
(375, 2398, 'serie', 'Girlfriends', 'Girlfriends', 2000, NULL, 30, 8, '/buFnsyWEg4pPR7dco5Vbsm6HCIY.jpg', '/lJEItmoc7bdqvA0yS5quuBIwW0N.jpg', 7.1, 50, 728.77, 'en', 41, 60, 50, 49, 52, 50, 36, 51, 67, 1, '2026-11-18 19:16:10'),
(376, 2153, 'serie', 'Arthur', 'Arthur', 1996, 'Conta as aventuras e desventuras de um porquinho-da-terra de oito anos, cujo maior charme é ser apenas uma criança normal. Acompanhado da irmã e dos amigos, ele consegue resolver os problemas que aparecem, sempre com imaginação, bondade e muito humor.', 13, 25, '/nYN8okmcsmhd4bGVcqifZ5OCumB.jpg', '/5k3JpB88vubqYVSHHiAhk2T8z17.jpg', 7, 194, 571.32, 'en', 58, 100, 90, 67, 98, 50, 61, 49, 100, 1, '2026-11-18 19:16:10'),
(377, 4177, 'serie', 'Perry Mason', 'Perry Mason', 1957, 'Los Angeles, 1932. Atormentado por seu casamento fracassado e passado traumático na guerra, o advogado criminal Perry Mason (Matthew Rhys) se vê diante de uma chance de redenção, quando o sequestro de uma criança tem um desfecho trágico.', 52, 9, '/sK6JvgNFP1ClT4aF4nPAZiDpAdk.jpg', '/iq4BjyVsDxzg24XnjoGP0Xi2Tz5.jpg', 7.7, 142, 544.54, 'en', 57, 30, 42, 47, 6, 74, 40, 45, 83, 1, '2026-11-18 19:16:11'),
(378, 1416, 'serie', 'Grey\'s Anatomy', 'Grey\'s Anatomy', 2005, 'Os médicos do Grey Sloan Memorial Hospital lidam diariamente com casos e consequências de vida ou morte. É um no outro que eles encontram apoio, conforto, amizade e, às vezes, até mais que amizade... Juntos, eles descobrem o quanto a vida profissional e a pessoal podem ser complicadas e se misturarem no meio do caminho.', NULL, 23, '/vrChGRs0DsoCoaeHif8PlZY637Q.jpg', '/A4NwkQXTXElE5iAsne5RpvS8R2Z.jpg', 8.2, 11143, 532.45, 'en', 47, 30, 50, 39, 44, 50, 46, 51, 50, 1, '2026-11-18 19:16:12'),
(379, 61923, 'serie', 'Star vs. As Forças do Mal', 'Star vs. the Forces of Evil', 2015, 'Guerreira intergaláctica Star Borboleta chega na Terra para viver com a família Diaz. Ela continua lutando contra vilões de todas as dimensões  e ainda no ensino médio, tudo isso principalmente para proteger sua varinha extremamente poderosa, um objeto que ainda a pertence por direito por ser princesa de mewni.', 11, 4, '/mNJyeOwLHOw0vDPbtcWeA1q4Wmt.jpg', '/2UElp7Dkm3SiB9ZEdKEWNmAOijB.jpg', 8.4, 1546, 506.63, 'en', 67, 100, 100, 93, 80, 50, 94, 74, 100, 1, '2026-11-18 19:16:12'),
(380, 61928, 'serie', 'Lucha Underground', 'Lucha Underground', 2014, NULL, 60, 4, '/by1AztJ9I1gjWKPL3XdYxiFOU5T.jpg', '/lQp79IOcrLdPps9BvnKPvOeX6pD.jpg', 7.1, 31, 478.73, 'en', 65, 40, 98, 71, 32, 74, 80, 73, 100, 1, '2026-11-18 19:16:13'),
(382, 61733, 'serie', 'Empire: Fama e Poder', 'Empire', 2015, 'Lucious Lyon saiu das ruas e construiu um império musical com a gravadora Empire. Desde que descobriu uma doença, cria uma competição entre seus filhos pelo comando da empresa.', NULL, 6, '/8Uz4oB6Sa84AZEFif2ZOg2m6K0k.jpg', '/FNeJtRUd5XID186SHzjNNneP3f.jpg', 7.1, 778, 449.87, 'en', 47, 18, 50, 29, 44, 42, 38, 52, 67, 1, '2026-11-18 19:16:14'),
(383, 48866, 'serie', 'Os 100', 'The 100', 2014, '100 anos no futuro, quando a Terra foi abandonada devido à radioatividade, os últimos humanos sobreviventes vivem em uma arca que orbita o planeta - mas a arca não vai durar para sempre. Assim, o regime repressivo escolhe 100 delinquentes juvenis descartáveis para enviar à Terra para ver se o planeta ainda é habitável.', 42, 7, '/cfhfcEt4bOXuVZkTC0nNBpqqiWb.jpg', '/8ZerYKvIaNUJZvAHXYTQu4qTwFw.jpg', 7.9, 8892, 449.84, 'en', 59, 40, 90, 71, 16, 50, 72, 73, 100, 1, '2026-11-18 19:16:15'),
(385, 253376, 'serie', 'A Namorada Ideal', 'The Girlfriend', 2025, 'A Laura tem tudo: uma carreira brilhante, um marido amoroso e um filho precioso, o Daniel. Mas a vida perfeita desmorona quando o Daniel apresenta a Cherry, uma namorada que muda tudo. Após um começo tenso, a Laura fica convencida de que a Cherry esconde algo. Será que ela é uma manipuladora ambiciosa, ou a Laura está paranoica? A verdade é uma questão de perspectiva.', NULL, 1, '/wUu11RqotaShM8s9GfpMChYMG5S.jpg', '/lnVWmFvLv2pTZGsuAJytiqKu541.jpg', 7.1, 171, 429.81, 'en', 53, 26, 50, 39, 32, 74, 40, 52, 67, 1, '2026-11-18 19:16:16'),
(386, 2119, 'serie', 'Águia de Fogo', 'Airwolf', 1984, 'Conta a história de Michael Coldsmith-Briggs III, que é o comandante de uma divisão especial da CIA, chamada de \"A Firma\", que construiu o Águia de Fogo. Ele convoca o piloto Stringfellow Hawke, para recuperar a aeronave desaparecida na Líbia. Hawke vive em uma cabana no topo de uma montanha, isolado. Seu único companheiro é seu cão, Tet. Hawke é um veterano da guerra do Vietnã, onde perdeu seu irmão, desaparecido em combate, desde então vive recluso. Ele tem como único amigo e companheiro de aventuras no Águia de Fogo, o veterano Dominic Santini, uma…', 48, 4, '/uSlnBIJsCkfXcHP7P9cOzmBIk4t.jpg', '/8693rGsfkROQjiwlJD8O2WQV1Et.jpg', 7.6, 503, 407.62, 'en', 58, 60, 98, 83, 50, 50, 91, 71, 67, 1, '2026-11-18 19:16:16'),
(387, 247718, 'serie', 'Terra da Máfia', 'MobLand', 2025, 'O poder está em disputa quando duas famílias do crime se chocam numa batalha que ameaça derrubar impérios e arruinar vidas. No meio está Harry Da Souza, um \"resolvedor de problemas\" que sabe bem onde a lealdade está quando as forças opostas colidem.', NULL, 2, '/jM7bH9b9QT22PtkTyHzxbXx4lDI.jpg', '/h0OC7ouop8YLwbAVfS3UUE2Lw4T.jpg', 8.7, 1266, 407.53, 'en', 51, 30, 42, 45, 16, 50, 38, 52, 67, 1, '2026-11-18 19:16:17'),
(388, 79593, 'serie', 'Magnum P.I.', 'Magnum P.I.', 2018, 'Um ex-integrante da marinha americana retorna do Afeganistão e usa suas habilidades de militar para trabalhar como um investigador particular no Havaí.', NULL, 5, '/hN7DKusbmKPqSZnMG5hemioMAiE.jpg', '/x40yXVPV8tPbuWAjSPGAGauDrhj.jpg', 7.5, 355, 391.73, 'en', 51, 40, 56, 71, 16, 50, 56, 52, 83, 1, '2026-11-18 19:16:18'),
(391, 63333, 'serie', 'The Last Kingdom', 'The Last Kingdom', 2015, 'Enquanto Alfredo, o Grande, defende seu reino de invasões nórdicas, Uhtred - um saxão criado por vikings - planeja reivindicar o que é seu por direito.', 60, 5, '/fMNJjzZUdc8pBVIQ85olSNaBKix.jpg', '/QbtctI8EzlhsyFDMUMyG3fli8B.jpg', 8.3, 2099, 371.56, 'en', 43, 36, 64, 63, 34, 50, 76, 38, 83, 1, '2026-11-18 19:16:19'),
(392, 4588, 'serie', 'ER: Plantão Médico', 'ER', 1994, 'E.R. trata do cotidiano da emergência de um hospital público de Chicago, visto sob a ótica dos médicos e enfermeiros que ali trabalham. Os conflitos profissionais e as histórias dos pacientes atendidos no pronto-socorro misturam-se aos dramas pessoais dos médicos.', 45, 15, '/iTiZNSLY3Yghecg8ejqjbQ3LNoX.jpg', '/en3zftWPQb5Ue6aA8W88RQbtqzd.jpg', 7.8, 993, 359.19, 'en', 46, 30, 50, 39, 44, 50, 47, 49, 50, 1, '2026-11-18 19:16:20'),
(393, 873, 'serie', 'Columbo', 'Columbo', 1971, 'Columbo é uma premiada série policial dos anos 1970 estrelada pelo ator Peter Falk. A série revolucionou as histórias de detetives.\n\nAo contrário do que geralmente ocorre em filmes policiais, cada episódio sempre começa mostrando claramente quem é o assassino, e os pormenores de como cometeu o homicídio. Todos os crimes da série têm um ponto em comum: o criminoso monta um alibi que parece perfeito.\n\nDepois entra em cena Columbo (o seu primeiro nome nunca foi revelado), um tenente da Divisão de Homicídios da Polícia de Los Angeles, sempre vestindo um…', NULL, 10, '/2JCD8vab3fircOU8cM2HJCxfv4I.jpg', '/d7cH4zt3xoqRQnLqYXMPOrUz5k3.jpg', 8.1, 891, 334.63, 'en', 58, 30, 42, 48, 4, 74, 38, 47, 83, 1, '2026-11-18 19:16:21'),
(395, 1411, 'serie', 'Pessoa de Interesse', 'Person of Interest', 2011, 'John Reese, um ex-agente da CIA, é recrutado por Finch, um milionário e gênio da tecnologia, para ajudar na identificação de pessoas envolvidas em futuros crimes.', NULL, 5, '/s5fhbaU1Mk98awGZyALELoqa1Bi.jpg', '/efeMgQn6iRALsOqDa2cqlf6Pw5O.jpg', 8.1, 2242, 313.42, 'en', 69, 40, 90, 77, 4, 74, 72, 73, 100, 1, '2026-11-18 19:16:22'),
(397, 46648, 'serie', 'True Detective', 'True Detective', 2014, 'Mostrando diferentes perspectivas tanto no passado como no presente, a narrativa se foca na investigação dos crimes supostamente cometidos por um serial killer no ano de 1995 feita pelos detetives Rust Cohle e Martin Hart. Nos dias atuais, o caso é aberto novamente e ambos são questionados pelos atuais detetives, já que a polícia tenta novamente prender o mesmo assassino. A série mostrará ao público o que acontece atualmente, ao mesmo tempo em que revela flashbacks da investigação nos anos 90.', NULL, 5, '/1fxr55V72a2gtqyn2b8pf6FslOf.jpg', '/v8YFr8BbU9qsO8PYIulzTeM6Qk.jpg', 8.3, 4501, 262.44, 'en', 57, 38, 44, 39, 32, 74, 40, 51, 67, 1, '2026-11-18 19:16:23'),
(398, 213375, 'serie', 'VisionQuest', 'VisionQuest', 2026, 'Um Visão repaginado tem se escondido daqueles que buscam usá-lo como arma. Enquanto permanece na clandestinidade, ele consulta as personalidades de IA embutidas em sua programação, incluindo o infame Ultron, para encontrar seu verdadeiro propósito. Essa vida tranquila de autorreflexão chega ao fim quando uma recompensa por sua cabeça o força a fugir ao lado de Thomas Shepard, um garoto misterioso que pode ser a reencarnação de seu filho.', NULL, 1, '/WGyAyBPncfuu8MZhLY9RtfZPM0.jpg', '/uoXXbN2PrOxH6UKyP7kYwmGpAAP.jpg', 8.3, 533, 256.48, 'en', 55, 30, 84, 39, 44, 50, 62, 74, 67, 1, '2026-11-18 19:16:24'),
(400, 153312, 'serie', 'Tulsa King', 'Tulsa King', 2022, 'Depois de cumprir 25 anos de prisão, Dwight Manfredi é exilado sem cerimônia por seu chefe da máfia para se estabelecer em Oklahoma. Dwight lentamente constrói um novo império criminoso em Tulsa.', NULL, 4, '/y13WOeZ2rz2Ezpws0RJ0I8sQpG4.jpg', '/mNHRGO1gFpR2CYZdANe72kcKq7G.jpg', 8.3, 2963, 253.53, 'en', 45, 60, 42, 55, 24, 50, 28, 52, 83, 1, '2026-11-18 19:16:26'),
(401, 549, 'serie', 'Lei & Ordem', 'Law & Order', 1990, 'O drama mostra o processo complicado de determinar a culpa ou a inocência, quando vidas estão em jogo. Muitas vezes inspirado pelas notícias mais recentes, o enredo destaca dilemas éticos e pessoais.', NULL, 26, '/3NYN6Paxb2FzIfR9sQEyH1HG1Vw.jpg', '/hrfP9BQ4mOMZOa8nHbFJLSDHBLz.jpg', 7.3, 743, 246.11, 'en', 50, 30, 42, 45, 16, 50, 39, 49, 67, 1, '2026-11-18 19:16:27'),
(402, 387, 'serie', 'Bob Esponja', 'SpongeBob SquarePants', 1999, 'Uma esponja-do-mar chamada Bob Esponja Calça Quadrada mora com seu caracol de estimação na Fenda do Biquíni, no fundo do oceano. Bob trabalha no Siri Cascudo e, nas horas vagas, vive arrumando confusões com seu melhor amigo, a estrela-do-mar Patrick.', NULL, 18, '/yXrtQINkVRyNmfUQFyVG2LuoTqm.jpg', '/f3f5OzzYd8m3zN47DAjKs0sbx00.jpg', 7.7, 3312, 242.29, 'en', 58, 100, 82, 67, 80, 50, 61, 49, 83, 1, '2026-11-18 19:16:27'),
(403, 4614, 'serie', 'NCIS: Investigação Naval', 'NCIS', 2003, 'Sob o exemplar comando de Leroy Jethro Gibbs, uma equipe de agentes especiais investiga crimes relacionados com a Marinha dos Estados Unidos.', NULL, 24, '/abjNx4jqvaJn5UvsuLaBVRVndyJ.jpg', '/rHKRZCBpDFSNc45kzyf665LJYp3.jpg', 7.6, 2623, 241.7, 'en', 51, 40, 56, 71, 16, 50, 56, 51, 83, 1, '2026-11-18 19:16:28'),
(406, 1668, 'serie', 'Friends', 'Friends', 1994, 'Seis jovens são unidos por laços familiares, românticos e, principalmente, de amizade, enquanto tentam vingar em Nova York.', NULL, 10, '/aYm0V4ZzzN2JZTiRzsbSppUD297.jpg', '/l0qVZIpXtIo7km9u5Yqh0nKPOr5.jpg', 8.4, 9603, 227.53, 'en', 44, 80, 50, 67, 58, 50, 47, 49, 50, 1, '2026-11-18 19:16:33'),
(408, 67175, 'serie', 'Elena de Avalor', 'Elena of Avalor', 2016, 'Além de proteger o reino encantado de Avalor, a jovem princesa Elena encontra tempo para a família, os amigos e todos os seus deveres reais!', NULL, 3, '/iGEhtWMXUaqCTKPY00lvfRAHHmy.jpg', '/7xO1zDXvTZAqccijxA77gMNkR87.jpg', 6.4, 89, 213.6, 'en', 73, 90, 100, 83, 68, 50, 96, 74, 100, 1, '2026-11-18 19:16:34'),
(409, 1424, 'serie', 'Orange Is the New Black', 'Orange Is the New Black', 2013, 'Um crime cometido no passado coloca uma privilegiada nova-iorquina na prisão, onde ela faz várias amigas. E inimigas.', NULL, 7, '/enI85hAm51txs8jUY7PWQXR1Xm5.jpg', '/zJiWhsEYCy5BkFCBONoMnUunyZQ.jpg', 7.6, 2964, 208.1, 'en', 45, 60, 42, 55, 24, 50, 28, 51, 83, 1, '2026-11-18 19:16:34'),
(410, 291507, 'serie', 'O Corpo', 'The Body', 2026, 'Na noite de Halloween, as garotas de um grupo de dança são tomadas por desejos profanos, visões fantasmagóricas e culpa católica depois que um ritual de iniciação dá errado.', NULL, 1, '/iHG87S3P8409qOFtYA616BiNLPj.jpg', '/hYJqUoXRZnodGxgVZTM8uwr5kbC.jpg', 7.9, 83, 206.67, 'en', 57, 30, 50, 45, 32, 74, 46, 52, 67, 1, '2026-11-18 19:16:35'),
(411, 65494, 'serie', 'The Crown', 'The Crown', 2016, 'Esta série dramática segue a política, rivalidades e relacionamentos da rainha Elizabeth II, e os eventos que fizeram a história.', NULL, 6, '/ehUMAA3qDR5HNor9DB60g72KNQZ.jpg', '/8VXhcrl5z2I1zEU9X3pkkNrZlD.jpg', 8.2, 2483, 205.43, 'en', 43, 26, 50, 33, 44, 50, 40, 52, 50, 1, '2026-11-18 19:16:36');
INSERT INTO catalogo_obras (id, tmdb_id, tipo, titulo, titulo_original, ano, sinopse, duracao, temporadas, poster_path, backdrop_path, nota, votos, popularidade, idioma_original, eixo_1, eixo_2, eixo_3, eixo_4, eixo_5, eixo_6, eixo_7, eixo_8, confianca, ativo, atualizado_em) VALUES
(412, 67744, 'serie', 'MINDHUNTER', 'MINDHUNTER', 2017, 'Um agente da Unidade de Crimes em Série do FBI desenvolve avançadas técnicas de psicologia criminal ao perseguir notórios assassinos e estupradores.', NULL, 2, '/fbKE87mojpIETWepSbD5Qt741fp.jpg', '/lpDVJuIro21gtMj9iXMFKHuroZN.jpg', 8.1, 3216, 203.73, 'en', 51, 30, 42, 45, 16, 50, 38, 52, 67, 1, '2026-11-18 19:16:36'),
(413, 291, 'serie', 'Coronation Street', 'Coronation Street', 1960, 'Coronation Street é uma novela de televisão britânica transmitida pela primeira vez na Granada Television em 1960. Ela foi logo distribuída em outras franquias da ITV. O programa diz respeito à vida dos residentes da Coronation Street em Weatherfield, uma área fictícia de Salford, e gira em torno de suas casas geminadas, cafés, lojas de esquina, bancas de jornais, fábricas de tecidos e o pub Rovers Return.\n\nO programa foi criado em 1960 pelo roteirista local Tony Warren na recém-formada Granada Television, em Manchester. A proposta inicial de Warren…', 22, 67, '/5x1HXqYqPyYw7oc7Isu1lvVmwRP.jpg', '/5APjn4LnV5wWk5DXq7ZewT6zzP1.jpg', 5.3, 121, 197.25, 'en', 43, 34, 50, 38, 50, 42, 42, 47, 50, 1, '2026-11-18 19:16:37'),
(414, 1695, 'serie', 'Monk: Um Detetive Diferente', 'Monk', 2002, 'Após o assassinato não resolvido de sua esposa, Adrian Monk desenvolve um transtorno obsessivo-compulsivo, um pavor de germes e contaminação, que lhe custa o seu trabalho como detetive. Contudo, ele continua a resolver crimes com a ajuda do ex-chefe.', NULL, 8, '/e3mVFigU7u7jSM9iSv4wI1slZky.jpg', '/dMY7XUfEAK0Rl8hsgc8ufEOaiZ2.jpg', 7.9, 1352, 189.6, 'en', 55, 60, 42, 61, 12, 74, 28, 51, 100, 1, '2026-11-18 19:16:37'),
(415, 3497, 'serie', 'Moesha', 'Moesha', 1996, NULL, 22, 6, '/uOTVIUWWuORHpakT5FtOXLEbAvF.jpg', '/eQuNP6LUFKJmP4f4iNLJWoi3g3h.jpg', 6.9, 53, 186.91, 'en', 44, 100, 56, 67, 80, 50, 55, 49, 67, 1, '2026-11-18 19:16:38'),
(416, 2004, 'serie', 'Malcolm', 'Malcolm in the Middle', 2000, 'Malcolm é um garoto gênio precisa lidar com seus três irmãos, bem como com seus pais excêntricos.', NULL, 7, '/rdxW4Lszm6qYB3qd2cexB8U8laW.jpg', '/si3OheCrSpEyK2JUtZOThsZPUR4.jpg', 8.5, 5047, 184.71, 'en', 45, 80, 50, 67, 58, 50, 46, 51, 50, 1, '2026-11-18 19:16:39'),
(417, 108978, 'serie', 'Reacher', 'Reacher', 2022, 'Quando o policial militar aposentado Jack Reacher é preso por um assassinato que não cometeu, ele se vê no meio de uma trama mortal cheia de policiais corruptos, empresários obscuros e políticos conspiradores. Só com sua inteligência, ele precisa descobrir o que está havendo em Margrave, Geórgia.', NULL, 4, '/f1VCQIG2iCyOookdgOzwtUpwWC0.jpg', '/pF0qkRsrHkdYadPWY9AMeFZfcwk.jpg', 8.1, 3610, 182.28, 'en', 55, 60, 56, 89, 22, 50, 66, 52, 67, 1, '2026-11-18 19:16:39'),
(418, 34307, 'serie', 'Shameless', 'Shameless', 2011, 'Situada em Chicago, a família Gallagher, uma família da classe trabalhadora de oito pessoas, terá de sobreviver aos altos e baixos da recessão de hoje. Com uma mãe que está fora de cena e um pai alcoólatra que geralmente acaba desmaiado no chão da sala, e com sua filha Fione, de 18 anos de idade, que tem a tarefa de manter seus cinco irmãos e irmãs na linha reta. Esta série é baseada na série britânica de mesmo nome.', NULL, 11, '/Yi3WVT6hOkPahOwwvmLmif1jhs.jpg', '/3w1iNNuMiFVDDUyycJoSAFksjc7.jpg', 8.2, 3594, 179.54, 'en', 41, 60, 50, 49, 52, 50, 36, 51, 67, 1, '2026-11-18 19:16:40'),
(419, 1433, 'serie', 'American Dad!', 'American Dad!', 2005, 'Stan Smith é um agente da CIA lotado em Langley Falls, na Virginia, cujo objetivo principal da vida é a segurança nacional. Sua família, um peixe dourado falante e um alienígena resgatado da Área 51 mantêm Stan ocupado enquanto ele tenta combater atividades terroristas nos EUA.', NULL, 22, '/eb9sH2am9IUSQ8GhXTNAVoujk8W.jpg', '/iixxhk3ycXmFqBn616pAsC3lu53.jpg', 7, 2500, 176.41, 'en', 59, 90, 76, 67, 58, 50, 52, 51, 67, 1, '2026-11-18 19:16:40'),
(420, 1427, 'serie', 'Broadchurch', 'Broadchurch', 2013, 'O assassinato de um jovem rapaz em uma pequena cidade litorânea traz um agitação da mídia, o que ameaça destruir a comunidade.', NULL, 3, '/2NhBFUTg5KVBmGwafxtLwVdsqrr.jpg', '/9CkwC4rou9468XMLTXaB6bZ0frx.jpg', 7.9, 1073, 172.81, 'en', 57, 26, 42, 45, 4, 74, 32, 51, 83, 1, '2026-11-18 19:16:41'),
(421, 1431, 'serie', 'CSI: Investigação Criminal', 'CSI: Crime Scene Investigation', 2000, 'Um dedicado grupo de investigadores forenses em um laboratório criminal de Las Vegas se empenha para resolver crimes quase sempre macabros. Trabalhando no turno da noite está o supervisor D.B. Russell, um verdadeiro Sherlock Holmes que devora livros de mistério e assassinatos. Os integrantes da equipe de Russell incluem Catherine Willows, Nick Stokes, Sara Sidle, Greg Sanders e Morgan Brody. O time trabalha de perto com o capitão Jim Brass, um detetive experiente. Entre os chefes anteriores do grupo estão Gus Grissom e o Dr. Raymond Langston.', 43, 15, '/1OOXYxrLLupCiUP78fDVGwaq0As.jpg', '/cvlLBcQWpO9X21jDHhgPJnE2aVq.jpg', 7.6, 1454, 167.01, 'en', 61, 30, 42, 51, 4, 74, 38, 51, 83, 1, '2026-11-18 19:16:42'),
(422, 1399, 'serie', 'Game of Thrones', 'Game of Thrones', 2011, 'Em uma terra onde os verões podem durar vários anos e o inverno toda uma vida, sete nobres famílias lutam pelo controle da mítica terra de Westeros, dividida depois de uma guerra. Num cenário que lembra a Europa medieval, reis, rainhas, cavaleiros e renegados usam todos os meios possíveis em um jogo político pela disputa do Trono de Ferro, o símbolo do poder absoluto.', NULL, 8, '/aqomTRKjNZkmNEeOZnEmWrFTmKU.jpg', '/zZqpAXxVSBtxV9qPBcscfXBcL2w.jpg', 8.5, 28203, 166.95, 'en', 51, 36, 98, 59, 44, 50, 74, 73, 83, 1, '2026-11-18 19:16:42'),
(423, 79744, 'serie', 'O Novato', 'The Rookie', 2018, 'John Nolan, um homem de 40 anos, deixa para trás sua vida confortável em uma cidade pequena para viver seu sonho de ser um agente policial no Departamento de Polícia de Los Angeles. Como o novato mais velho, ele enfrenta a descrença de seus colegas.', NULL, 9, '/yCPGrd6fzbftuaH97OUS6tUdE4B.jpg', '/6iNWfGVCEfASDdlNb05TP5nG0ll.jpg', 8.5, 3624, 165.27, 'en', 45, 60, 42, 55, 24, 50, 28, 52, 83, 1, '2026-11-18 19:16:43'),
(424, 1871, 'serie', 'EastEnders', 'EastEnders', 1985, 'A vida dos moradores da Albert Square, uma área fictícia localizada em  um dos bairros de East End, na Inglaterra. Por mais de 25 anos,  acompanha-se os dramas do dia-a-dia dessas pessoas, sempre em busca da  felicidade.', 30, 42, '/ETFWCToRFx45vNAsNexh31ufSE.jpg', '/2jzrUm0vGW2TqJPds1PfZVRYrh7.jpg', 4.3, 232, 157.87, 'en', 46, 14, 42, 29, 16, 42, 25, 49, 83, 1, '2026-11-18 19:16:44'),
(426, 3002, 'serie', 'The Benny Hill Show', 'The Benny Hill Show', 1969, NULL, 60, 19, '/pKoqzPido6dJmClHF13k5Nglede.jpg', '/bp30imMTFKAcxrZMi4hjBwY91A6.jpg', 7.2, 188, 156.43, 'en', 37, 76, 50, 58, 58, 50, 40, 47, 50, 1, '2026-11-18 19:16:45'),
(427, 1911, 'serie', 'Bones', 'Bones', 2005, 'A Dra. Temperance Brennan é uma antropóloga forense altamente qualificada que trabalha no Instituto Jeffersonian e escreve romances. Ela possui um talento impressionante para enxergar pistas em ossos de vítimas, e por isso a polícia a chama para ajudar em investigações quando os restos mortais estão tão decompostos, queimados ou destruídos que métodos de identificação padrão são inúteis. Temperance frequentemente trabalha em parceria com o agente especial Seeley Booth, ex-atirador de elite do exército que não confia na ciência ou em cientistas para…', NULL, 12, '/rElaRnNez2dXBCMv1THHdVcroFY.jpg', '/aSye04zKzWtUP3U6Cl4bOXc5Ih9.jpg', 8.2, 3642, 156.21, 'en', 51, 30, 42, 45, 16, 50, 38, 51, 67, 1, '2026-11-18 19:16:45'),
(428, 44006, 'serie', 'Chicago Fire: Heróis Contra o Fogo', 'Chicago Fire', 2012, 'Acompanhe o dia-a-dia intenso e os dramas dos oficiais do Departamento de Bombeiros de Chicago e paramédicos do Quartel 51. A equipe composta por bombeiros, equipe de resgate e paramédicos, irá passar por situações tensas e delicadas, arriscando suas próprias vidas para salvar pessoas em perigo, além de ter que lidar com os conflitos pessoais e os desafios que surgem por conta das diferenças entre os companheiros de equipe.', 42, 15, '/iD8lx0VgmpCZMhycI0Xw72wCuRS.jpg', '/otaBZzLIqrKdXcovbAvVONJCnb4.jpg', 8.4, 2472, 153.39, 'en', 47, 30, 50, 39, 44, 50, 46, 51, 50, 1, '2026-11-18 19:16:46'),
(429, 19885, 'serie', 'Sherlock', 'Sherlock', 2010, 'Nesta versão moderna dos livros de Sir Arthur Conan Doyle, o excêntrico Sherlock usa inteligência, psicologia e intuição para interpretar pistas.', 90, 4, '/7WTsnHkbA0FaG6R9twfFde0I9hl.jpg', '/8rvLEmdI4gLrMO1rLqbNdnNcPFE.jpg', 8.5, 6880, 150.28, 'en', 57, 26, 42, 45, 4, 74, 32, 51, 83, 1, '2026-11-18 19:16:47'),
(430, 65701, 'serie', 'Good Mythical Morning', 'Good Mythical Morning', 2012, NULL, 10, 31, '/jMpBQr2aNOFAI6wsC47zsOG6qOh.jpg', '/hvFCS0dMeC3ffiF4uYTKzUAkvYL.jpg', 6.9, 99, 150.26, 'en', 45, 80, 50, 67, 58, 50, 46, 51, 50, 1, '2026-11-18 19:16:47'),
(431, 194766, 'serie', 'O Verão Que Mudou Minha Vida', 'The Summer I Turned Pretty', 2022, 'Todo verão, Belly e sua família vão pra casa de praia dos Fishers em Cousins. Todo verão é igual... até Belly completar dezesseis anos. Relacionamentos novos surgirão, verdades dolorosas serão reveladas e Belly mudará para sempre. É um verão de primeiro amor, primeira desilusão amorosa e muito crescimento - é o verão em que ela fica bonita.', NULL, 3, '/49AV6vqypkekwI5kjKTvBokB9n1.jpg', '/jCQV3rHNbgHKo3N4G6CARbVEjPV.jpg', 8.1, 1164, 146.79, 'en', 47, 30, 50, 39, 44, 50, 46, 52, 50, 1, '2026-11-18 19:16:48'),
(433, 2190, 'serie', 'South Park', 'South Park', 1997, 'Série animada que satiriza com muito humor negro a sociedade estadounidense ao apresentar situações bizarras e surreais protagonizadas por Stan, Kyle, Eric e Kenny, as crianças mais travessas de South Park.', NULL, 29, '/ojwZ7dO7CUVUjbUDW81XaBjqy6h.jpg', '/3UviYOlhn8EgXMBuiT6MnUuo1w9.jpg', 8.3, 5283, 141.98, 'en', 58, 90, 76, 67, 58, 50, 53, 49, 67, 1, '2026-11-18 19:16:49'),
(434, 124364, 'serie', 'Origem', 'FROM', 2022, 'Desvende o mistério de uma cidade no centro dos EUA. Enquanto os moradores lutam para manter um senso de normalidade, eles também devem sobreviver às ameaças da floresta ao redor, incluindo as criaturas aterrorizantes que surgem quando o sol se põe.', NULL, 4, '/eK9ZDIq7gPFRJ0GGaWvgrXLZgXX.jpg', '/m7eiSGHFzr584zFmetGqkqaU6BN.jpg', 8.5, 4456, 140.75, 'en', 65, 30, 84, 45, 32, 74, 62, 74, 83, 1, '2026-11-18 19:16:50'),
(438, 1396, 'serie', 'Breaking Bad', 'Breaking Bad', 2008, 'Ao saber que tem câncer, um professor passa a fabricar metanfetamina pelo futuro da família, mudando o destino de todos.', NULL, 5, '/hGwm9Cj3CdbJIqQWNExQqiYmCd4.jpg', '/tsRy63Mu5cu8etL1X7ZLyf7UP1M.jpg', 9, 19145, 134.81, 'en', 51, 30, 42, 45, 16, 50, 38, 51, 67, 1, '2026-11-18 19:16:51'),
(439, 764, 'serie', 'Midsomer Murders', 'Midsomer Murders', 1997, 'Um investigador veterano e um jovem sargento investigam assassinatos na comunidade de Midsomer.', 90, 26, '/pz7tsWxe0TTdfJnWPjZAEnrSl5M.jpg', '/qVmgq1KXBp6BF2EqYPPaUG9iUGy.jpg', 7.4, 385, 134.51, 'en', 56, 26, 42, 45, 4, 74, 33, 49, 83, 1, '2026-11-18 19:16:52'),
(440, 693, 'serie', 'Donas de Casa Desesperadas', 'Desperate Housewives', 2004, 'Atrás da fachada perfeita de cartão postal de um condomínio fechado vivem quatro mulheres cujas vidas podem ser qualquer coisa, menos idílicas. A desajeitada Susan é divorciada e mãe da adolescente Julie. Lynette é casada com Tom e a mãe estressada de quatro filhos indisciplinados. Bree é a Martha Stewart da vizinhança, mas sua perfeição mascara seus desajustes. A ex-modelo Gabrielle, casada com o bonitão e bem-sucedido Carlos, quer ter tudo sem abrir mão de nada. Assistindo a tudo isso está Mary Alice, que se suicidou mas comenta sobre a vida de seus…', 42, 8, '/q7pPKBq79FwgPRA8jaETWrURd5R.jpg', '/hW9NOFs8xUevb90KQYHhbifp9Po.jpg', 7.9, 2179, 132.36, 'en', 51, 60, 50, 55, 40, 74, 36, 51, 83, 1, '2026-11-18 19:16:53'),
(441, 1402, 'serie', 'The Walking Dead', 'The Walking Dead', 2010, 'Nos Estados Unidos pós-apocalíptico, um pequeno grupo de sobreviventes segue viajando à procura de uma nova casa longe dos mortos-vivos. O desespero por segurança e suprimentos os coloca constantemente à beira da sanidade.', NULL, 11, '/9lb02gTh4LLB17yAEXFd4C3R4JP.jpg', '/rAOjnEFTuNysY7bot8zonhImGMh.jpg', 8.1, 18383, 132.24, 'en', 55, 40, 98, 65, 44, 50, 80, 73, 83, 1, '2026-11-18 19:16:53'),
(443, 1405, 'serie', 'Dexter', 'Dexter', 2006, 'Renomado funcionário da Polícia de Miami, Dexter esconde de todos uma segunda identidade: ele é um assassino em série que mata os criminosos que a polícia não consegue prender.', 60, 8, '/f1nV5NBIFwfQLw5g8FVrdt90FAy.jpg', '/nS5ZSmrX92lu1GYAlXZye1mkDfd.jpg', 8.2, 6042, 127.15, 'en', 61, 30, 42, 51, 4, 74, 38, 51, 83, 1, '2026-11-18 19:16:55'),
(444, 254630, 'serie', '12 12 12', '12 12 12', 2026, 'Um roubo leva 12 meses para ser planejado, 12 horas para ser executado e um ladrão que não é capturado em até 12 dias nunca mais será. Ao longo de três linhas do tempo eletrizantes, um agente do FBI e um criminoso profissional travam um jogo mortal de gato e rato pela Europa.', NULL, 1, '/8q6BvFQuKM1Rud4E9NQDaMGy9EL.jpg', '/tjy25xpiFeo2gahl7N0hoxbRtG7.jpg', 6.4, 34, 127.02, 'en', 51, 40, 56, 71, 16, 50, 56, 52, 83, 1, '2026-11-18 19:16:55'),
(447, 64432, 'serie', 'The Magicians: Escola de Magia', 'The Magicians', 2015, 'Após entrar para uma escola secreta de magia, o jovem Quentin Coldwater descobre um mundo de fantasia que é real e representa um perigo à humanidade. Baseado na obra de Lev Grossman.', 45, 5, '/kyq31lGYq1XrHLy7lyjEAXaAjQ7.jpg', '/qb9vehNFxTpPrazhD7JJ6QtEtCv.jpg', 7.6, 1742, 124.88, 'en', 55, 30, 84, 39, 44, 50, 62, 74, 67, 1, '2026-11-18 19:16:57'),
(448, 32726, 'serie', 'Bob\'s Burgers', 'Bob\'s Burgers', 2011, 'A série acompanha Bob da terceira geração de uma família de proprietários de restaurantes, responsável por administrar a hamburgueria \"Bob\'s Burgers\" junto com sua esposa e seus três filhos. Bob e sua peculiar família têm grandes ideias para os hambúrgueres, mas estão pobres em serviço e em sofisticação.', NULL, 16, '/iIHsQe3Qjs3NH62HdamyQEPeqTR.jpg', '/2AVPwdHJsF044jT39akgLxxv2zx.jpg', 7.8, 1169, 124.85, 'en', 59, 90, 76, 67, 58, 50, 52, 51, 67, 1, '2026-11-18 19:16:58'),
(449, 60625, 'serie', 'Rick e Morty', 'Rick and Morty', 2013, 'O brilhante cientista beberrão Rick sequestra Morty, seu neto aborrescente, para viver loucuras em outros mundos e dimensões alternativas.', NULL, 9, '/5qfd0e2uMbVInX3YdeFbDsfxi1t.jpg', '/iFOkrSrJRwE27PwbyQeYLlMJXzw.jpg', 8.7, 11606, 123.38, 'en', 67, 100, 100, 93, 58, 50, 86, 73, 100, 1, '2026-11-18 19:16:58'),
(450, 502, 'serie', 'Vila Sésamo', 'Sesame Street', 1969, 'Em uma rua especial no centro da cidade, os habitantes, humanos e bonecos, ensinam temas pré-escolares com comédia, desenhos animados, jogos e canções.', NULL, 56, '/efyqi8KvJcYrnFA9cDOL3Ph9bxs.jpg', '/tNi2aJPdCKfielGYzIi3IKxStz9.jpg', 7.1, 303, 123.17, 'en', 42, 100, 58, 64, 76, 50, 46, 47, 67, 1, '2026-11-18 19:16:59'),
(451, 4604, 'serie', 'Smallville: As Aventuras do Superboy', 'Smallville', 2001, 'Antes da vida como Super-Homem, o jovem Clark Kent encara os problemas da adolescência enquanto aprende a controlar seus poderes e usá-los para proteger a cidade de Smallville.', 43, 10, '/gjGwov0xDKWmoaYulwUb9tOzlOT.jpg', '/4wVq9ICc4MI2XcssrumpCOhKLpI.jpg', 8.2, 4675, 119.02, 'en', 55, 40, 98, 65, 44, 50, 80, 73, 83, 1, '2026-11-18 19:17:00'),
(452, 32692, 'serie', 'Sangue Azul', 'Blue Bloods', 2010, 'Uma família composta por membros que trabalham a favor da lei, cada um à sua maneira: o avô era policial, o pai também o é, um dos filhos é um policial que gosta de usar a violência nos interrogatórios, o outro filho é um recém-saído da academia de polícia e a filha é uma advogada do Estado. Nada os detém na hora de fazerem justiça e a sua ocupação é mais do que um trabalho: é uma questão de família.', NULL, 14, '/ovcXCEON7zvzAfJZKOywW132JwB.jpg', '/goDtZCB5pFIuuSfYDvApe6iXTID.jpg', 7.8, 1046, 118.99, 'en', 51, 30, 42, 45, 16, 50, 38, 51, 67, 1, '2026-11-18 19:17:00'),
(453, 95480, 'serie', 'Slow Horses', 'Slow Horses', 2022, 'Este drama perspicaz acompanha uma equipe disfuncional de agentes da MI5 – e seu chefe arrogante, o notório Jackson Lamb – enquanto navegam os mistérios e ilusões do mundo da espionagem para proteger a Inglaterra de forças sinistras.', NULL, 6, '/rdNvIaPXpkUZl5tQLsTP15osfu2.jpg', '/gPQppUnLx9vqPDLz3WwZ2HJsNbt.jpg', 8.1, 1138, 118.54, 'en', 57, 26, 42, 45, 4, 74, 32, 52, 83, 1, '2026-11-18 19:17:01'),
(454, 58841, 'serie', 'Chicago P.D.: Distrito 21', 'Chicago P.D.', 2014, 'O Distrito 21 do Departamento de Polícia de Chicado é composto pelos policiais uniformizados que lidam com o crime nas ruas e pela Unidade de Inteligência, que lida com crimes maiores como tráfico de drogas e assassinatos.', NULL, 14, '/3k9YHHlENlcIT8g2BqeXsaDI2Hh.jpg', '/18KSsDgcGQds7yOMC6MVRTbVJwt.jpg', 8.4, 2656, 118.15, 'en', 51, 30, 42, 45, 16, 50, 38, 51, 67, 1, '2026-11-18 19:17:02'),
(455, 1480, 'serie', 'Ally McBeal: Minha Vida de Solteira', 'Ally McBeal', 1997, 'Ally McBeal é uma advogada que tem o desejo de encontrar um parceiro ideal para se casar e de se dar bem na vida, emocionalmente e profissionalmente. Toda a trama se desenrola num escritório de advocacia, em Boston, onde Ally e o resto de seus colegas excêntricos trabalham e vivem situações bastante irreais.', 43, 5, '/weS8htxS2j0EQ6jorK3WOR1dZpH.jpg', '/xCMs3IxaGqKSc5cwngRUlhmjbwl.jpg', 6.5, 400, 117.98, 'en', 40, 60, 50, 49, 52, 50, 37, 49, 67, 1, '2026-11-18 19:17:02'),
(456, 33880, 'serie', 'A Lenda de Korra', 'The Legend of Korra', 2012, 'Korra, uma jovem rebelde de 17 anos, deixa a tradição de lado para se tornar um Avatar e manter a Cidade da República livre das forças do mal dos mundos físico e espiritual.', 23, 4, '/yDRskxx7kXoB9ImdXi05Db5EG3L.jpg', '/bauKfP3CX5JPAXpmveOlPG1pngC.jpg', 8.2, 2506, 116.72, 'en', 81, 70, 100, 68, 50, 50, 83, 70, 83, 1, '2026-11-18 19:17:03'),
(457, 57532, 'serie', 'Patrulha Canina', 'PAW Patrol', 2013, 'Seis cachorrinhos heroicos liderados por um garoto de 10 anos realizam arriscadas missões de resgate sempre com bom humor, habilidades especiais e veículos muito legais!', NULL, 14, '/pQ0bBHR9Q3wurjNMjnqal0gJaYo.jpg', '/7OrV2aAH5Yp7hA9zCCvUloLvZtl.jpg', 7, 830, 116.25, 'en', 65, 80, 84, 57, 68, 50, 62, 51, 67, 1, '2026-11-18 19:17:06'),
(460, 61118, 'serie', 'Você é o Pior', 'You\'re the Worst', 2014, 'Gretchen e Jimmy são provavelmente as últimas pessoas que você imaginaria ver em um relacionamento. Auto-destrutivos, independentes e egocêntricos, Jimmy é um escritor introspectivo e Gretchen é uma executiva de relações pessoais em Los Angeles. Apesar de tudo o que pode dar muito errado, eles acabam dando uma chance a este improvável romance.', 26, 5, '/whXfP89yXz4AwQ9dzWCTGcl9YvV.jpg', '/3gqDstdBLUbJ2jY3hl953iS97D4.jpg', 7.4, 271, 112.14, 'en', 41, 60, 50, 49, 52, 50, 36, 51, 67, 1, '2026-11-18 19:17:08'),
(461, 80748, 'serie', 'FBI', 'FBI', 2018, 'A série acompanha os bastidores das operações do FBI em NY, onde os agentes Maggie Bell, Omar Adom e equipe buscam manter a cidade e o país a salvo.', NULL, 9, '/br3xWBUu7W0dXsMev0XXVvoMxuE.jpg', '/j9nU0GHNakbQhoFCDE61OrvMjTC.jpg', 7.9, 972, 110.64, 'en', 51, 40, 56, 71, 16, 50, 56, 52, 83, 1, '2026-11-18 19:17:09'),
(462, 121, 'serie', 'Doctor Who', 'Doctor Who', 1963, 'Doctor Who é uma série clássica de ficção científica produzida pela britânica BBC entre os anos de 1963 e 1989. A história gira em torno de um viajante do tempo alienígena conhecido apenas como “Doutor” que viaja a bordo da TARDIS (acrônimo de Time and Relative Dimensions in Space), sua nave cuja aparência externa se assemelha a uma cabine da polícia londrina da década de 1960. Juntamente com seus companheiros, o Doutor explora o espaço e o tempo, corrigindo males e resolvendo problemas.', 25, 26, '/uvxLuymTnNeFyiphc8YpCU91agb.jpg', '/8VWgyQjExeMgeg6Qzv6agduMU1A.jpg', 7.9, 732, 108.86, 'en', 47, 36, 98, 56, 44, 50, 74, 69, 83, 1, '2026-11-18 19:17:09'),
(464, 1620, 'serie', 'CSI: Miami', 'CSI: Miami', 2002, 'Um time de investigadores forenses da Flórida usa tecnologia de ponta e métodos policiais tradicionais para solucionar crimes.', 42, 10, '/uMLbHU7a7RWTg1vacCNtHnnzbPU.jpg', '/bhG1XJ1fubbZkLnoBAxNrzzGXOg.jpg', 7.7, 1765, 108.17, 'en', 61, 30, 42, 51, 4, 74, 38, 51, 83, 1, '2026-11-18 19:17:11'),
(465, 2883, 'serie', 'Sombras da Noite', 'Dark Shadows', 1966, 'Série gótica que retrata acontecimentos sobrenaturais, fantasmas, bruxas, lobisomens e um vampiro de quase 200 anos de idade. As histórias intercalam-se entre o tempo atual e o século 18.', 22, 12, '/eRtnI7qTJIiPUmlY3J8TTM3jlT7.jpg', '/fmFsm4dq02k2Xxs7M887unPAiXd.jpg', 7.3, 100, 107.89, 'en', 52, 18, 84, 26, 44, 42, 54, 69, 83, 1, '2026-11-18 19:17:11'),
(466, 46952, 'serie', 'Lista Negra', 'The Blacklist', 2013, 'Após se entregar à polícia, um brilhante fugitivo oferece ajuda ao FBI, mas apenas se a novata Elizabeth Keen for sua parceira.', NULL, 10, '/2wsMtmq61hb3o6pX7MabTeCu9Yi.jpg', '/2eIlCirgcvEwmCSYh2wDfz5Sxvz.jpg', 7.6, 3791, 106.78, 'en', 61, 30, 42, 51, 4, 74, 38, 51, 83, 1, '2026-11-18 19:17:12'),
(467, 12225, 'serie', 'Peppa Pig', 'Peppa Pig', 2004, 'Junte-se à porquinha Peppa e sua família em aventuras da vida cotidiana que mostram que é possível aprender e se divertir em qualquer situação.', NULL, 9, '/iVaiv0S34JnRKHnYkEiObOI15k5.jpg', '/r9QAxAW2KGQaVnEOxXKJuZ6RSJe.jpg', 6.5, 772, 105.73, 'en', 61, 76, 84, 51, 68, 50, 56, 51, 67, 1, '2026-11-18 19:17:12'),
(468, 2691, 'serie', 'Dois Homens e Meio', 'Two and a Half Men', 2003, 'A vida mulherenga do solteirão Charlie é afetada quando seu irmão divorciado e seu sobrinho de língua afiada vão morar com ele.', NULL, 12, '/b53xHGj5Ys6O81D5v10mZQEPNSR.jpg', '/coHpOy9OJyFiHWeH36cSHMpLUHC.jpg', 7.4, 3851, 105.16, 'en', 45, 80, 50, 67, 58, 50, 46, 51, 50, 1, '2026-11-18 19:17:13'),
(469, 85077, 'serie', 'The Chosen: Os Escolhidos', 'The Chosen', 2019, 'Aprofundando-se nas histórias de fundo e no contexto das pessoas e eventos dos evangelhos, a Primeira Temporada do projeto de mídia de maior financiamento coletivo pelo público de todos os tempos apresenta pessoas como Simão Pedro, Nicodemos, Maria Madalena, Mateus e, claro, Jesus de uma forma nunca antes vista em filme.', 60, 6, '/9lL4etMuaZnqlSzkf0zEm3gbvlR.jpg', '/2YQFwn9aF7huTFHxn9lFTAn14F.jpg', 8.9, 1072, 104.75, 'en', 47, 62, 70, 65, 66, 50, 72, 52, 83, 1, '2026-11-18 19:17:13'),
(470, 1417, 'serie', 'Glee: Em Busca da Fama', 'Glee', 2009, 'O professor de espanhol Will Schuester resolve comandar o coral da escola, Glee Club. Tentando dar nova vida ao grupo, ele procura diferentes alunos, populares e nerds, como Rachel Berry, Kurt Hummel, Finn Hudson, Quinn Fabray e Brittany Pierce. Schuester tenta equilibrar a sua vida pessoal, enquanto ensaia com os seus novos alunos, mas logo começa a enfrentar as armadilhas da treinadora Sue Sylvester.', NULL, 6, '/825vEXKUmlR7dy3L0rgvX9XA2ho.jpg', '/1orqm4lN8VtYGlxZ1g12ip6iwmG.jpg', 6.8, 1002, 104.61, 'en', 41, 60, 50, 49, 52, 50, 36, 51, 67, 1, '2026-11-18 19:17:14'),
(471, 66732, 'serie', 'Stranger Things', 'Stranger Things', 2016, 'Quando um garoto desaparece, a cidade toda participa nas buscas. Mas o que encontram são segredos, forças sobrenaturais e uma menina.', NULL, 5, '/twfKp60THrcOIep9sjHODOOfO8d.jpg', '/9P4IIMYY3HifqeruZq0ZZ9g7YUi.jpg', 8.5, 22157, 103.56, 'en', 69, 60, 98, 89, 38, 74, 90, 74, 83, 1, '2026-11-18 19:17:15'),
(473, 4607, 'serie', 'Lost', 'Lost', 2004, 'Os sobreviventes de um voo que estava milhas fora do curso caem em uma ilha que abriga um sistema de segurança monstruoso, uma série de abrigos subterrâneos e um grupo de sobrevivencialistas violentos escondidos nas sombras.', NULL, 6, '/a8g8x4XDRZCP0vNL2BSBkCJghLj.jpg', '/yUOFocKDW7MCC5isx4FK8A68QFp.jpg', 8, 5475, 101.95, 'en', 57, 40, 64, 71, 32, 74, 64, 51, 83, 1, '2026-11-18 19:17:16'),
