(1916, 1990, 'serie', 'रामायण', 'रामायण', 1987, NULL, 35, 1, '/gIOtRVKHHyPtyGPsLLhzhSYG1QF.jpg', '/sjaJaXRjp6FrJccBAWup9a8TQ7f.jpg', 8.3, 35, 7.36, 'hi', 46, 89, 70, 71, 75, 43, 82, 49, 100, 1, '2026-11-18 19:32:54'),
(1917, 113218, 'serie', 'Tamarindo', 'इमली', 2020, 'Tudo o que Imlie queria era criar um nome para si mesma na cidade. Mas ao chegar, ela se vê presa no meio da história de amor de Aditya e Malini.', 24, 3, '/sltUDXvpDZK3aVIdtkbImhcJv8t.jpg', '/i8NGdMIyZnGNpSHLDtpPwYXidPe.jpg', 7.4, 83, 7.14, 'hi', 47, 67, 56, 35, 75, 35, 55, 52, 100, 1, '2026-11-18 19:32:55'),
